"""Source-free runtime for compiler-generated decode bundles."""

from __future__ import annotations

import ctypes
import json
import re
import threading
from contextlib import nullcontext
from dataclasses import InitVar, dataclass, field
from math import isfinite, prod
from types import MappingProxyType
from typing import Any, Callable, Collection, Mapping, Sequence

import torch

from .cute_aot_runtime import AotFamily
from .generated_decode_identity import (
    RuntimeDescriptorIdentityError,
    _has_canonical_tape_layout,
    expand_runtime_descriptor_tape,
    runtime_descriptor_sha256,
)


class GeneratedDecodeError(RuntimeError):
    pass


_FAMILY = AotFamily("generated_decode")
_SCALAR_TYPES = {
    "int32": ctypes.c_int32,
    "int64": ctypes.c_int64,
    "fp32": ctypes.c_float,
}
_TORCH_DTYPES = {
    "bf16": torch.bfloat16,
    "fp16": torch.float16,
    "fp32": torch.float32,
    "fp8_e4m3": torch.float8_e4m3fn,
    "fp8_e5m2": torch.float8_e5m2,
    "uint8": torch.uint8,
    "int32": torch.int32,
    "int64": torch.int64,
    "bool": torch.bool,
}
_MAPPING_PROXY_TYPE = type(MappingProxyType({}))

_PACKED_RECEIPT_FIELDS = frozenset({
    "schema_version", "backend", "family", "program", "variant_key",
    "manifest_content_fingerprint",
    "inventory_fingerprint", "wrapper_sha256",
    "architecture", "device_program_key", "implementation_sha256",
    "source_sha256", "runtime_descriptor_sha256", "delivery", "capacity",
    "static_extent_bindings", "num_ctas",
})
_RECEIPT_HASH_FIELDS = (
    "manifest_content_fingerprint",
    "inventory_fingerprint", "wrapper_sha256",
    "implementation_sha256", "source_sha256", "runtime_descriptor_sha256",
)


class _FrozenIdentity(Mapping):
    """Owned immutable snapshot, unlike a proxy over a caller-owned dictionary."""

    __slots__ = ("_values",)

    def __init__(self, values: Mapping) -> None:
        object.__setattr__(self, "_values", MappingProxyType({
            key: _freeze_identity(value) for key, value in values.items()
        }))

    def __setattr__(self, name, value):
        raise AttributeError("launch identity is immutable")

    def __delattr__(self, name):
        raise AttributeError("launch identity is immutable")

    def __getitem__(self, key):
        return self._values[key]

    def __iter__(self):
        return iter(self._values)

    def __len__(self):
        return len(self._values)

    def items(self):
        return self._values.items()

    def __repr__(self):
        return repr(self._values)


def _freeze_identity(value: Any) -> Any:
    """Recursively snapshot JSON-like launch identity into immutable values."""

    value_type = type(value)
    if value_type is _FrozenIdentity:
        return value
    if value is None or value_type in (bool, int, float, str):
        return value
    if value_type in (dict, _MAPPING_PROXY_TYPE):
        return _FrozenIdentity(value)
    if value_type in (list, tuple):
        return tuple(_freeze_identity(item) for item in value)
    if isinstance(value, Mapping):
        return _FrozenIdentity(value)
    if isinstance(value, (list, tuple)):
        return tuple(_freeze_identity(item) for item in value)
    return value


def _json_identity(value: Any) -> Any:
    """Return a JSON-serializable copy of frozen launch identity."""

    if isinstance(value, Mapping):
        return {key: _json_identity(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_json_identity(item) for item in value]
    return value


def _same_json_identity(left: Any, right: Any) -> bool:
    """Compare JSON-like values without Python's bool/int/float coercions."""

    if isinstance(left, Mapping):
        if not isinstance(right, Mapping):
            return False
        left_keys = tuple(left)
        right_keys = tuple(right)
        if (
            any(type(key) is not str for key in (*left_keys, *right_keys))
            or set(left_keys) != set(right_keys)
        ):
            return False
        return all(
            _same_json_identity(left[key], right[key]) for key in left_keys
        )
    if isinstance(left, (list, tuple)):
        return (
            isinstance(right, (list, tuple))
            and len(left) == len(right)
            and all(
                _same_json_identity(left_item, right_item)
                for left_item, right_item in zip(left, right, strict=True)
            )
        )
    return type(left) is type(right) and left == right


def _normalized_cuda_arch(value: Any, *, contract: str) -> str:
    """Return the base SM token shared by accelerated and live arch names."""

    match = (
        re.fullmatch(r"sm([0-9]+)(?:a)?", value)
        if type(value) is str else None
    )
    if match is None:
        raise GeneratedDecodeError(
            f"generated decode {contract} has invalid CUDA architecture {value!r}"
        )
    return f"sm{match.group(1)}"


def _live_cuda_arch(device_index: int) -> str:
    """Derive one live SM token without coercing capability metadata."""

    capability = torch.cuda.get_device_capability(device_index)
    if (
        type(capability) is not tuple
        or len(capability) != 2
        or any(type(value) is not int or value < 0 for value in capability)
    ):
        raise GeneratedDecodeError(
            "generated decode live device has malformed CUDA capability "
            f"{capability!r}"
        )
    major, minor = capability
    return f"sm{major}{minor}"


def _receipt_sha256(value: Any, name: str) -> str:
    try:
        valid = (
            isinstance(value, str)
            and len(value) == 64
            and len(bytes.fromhex(value)) == 32
        )
    except ValueError:
        valid = False
    if not valid:
        raise GeneratedDecodeError(
            f"packed generated decode receipt has invalid {name!r}")
    return value.lower()


def _packed_runtime_descriptor_identity(
    signature: Mapping[str, Any],
    descriptor: Mapping[str, Any],
    *,
    variant_key: str | None = None,
) -> tuple[str, str, str]:
    """Authenticate the complete runtime descriptor and its selection key."""

    base_fields = {
        "schema_version",
        "implementation_sha256",
        "source_sha256",
        "runtime_descriptor_sha256",
    }
    schema_version = signature.get("schema_version")
    if (
        isinstance(schema_version, bool)
        or not isinstance(schema_version, int)
    ):
        raise GeneratedDecodeError(
            "packed generated decode signature has non-integer schema version"
        )
    expected_fields = (
        base_fields | {"device_program"}
        if schema_version == 4
        else base_fields | {"device_program", "argument_alignments"}
        if schema_version == 5
        else base_fields
        if schema_version == 6
        else base_fields | {"argument_alignments"}
        if schema_version == 7
        else None
    )
    if expected_fields is None or set(signature) != expected_fields:
        raise GeneratedDecodeError(
            "packed generated decode runtime descriptor requires an exact "
            "schema-v4/v5 or packed schema-v6/v7 authoritative signature"
        )
    expected_digest = _receipt_sha256(
        signature.get("runtime_descriptor_sha256"),
        "runtime_descriptor_sha256",
    )
    try:
        actual_digest = runtime_descriptor_sha256(descriptor)
    except RuntimeDescriptorIdentityError as exc:
        raise GeneratedDecodeError(
            "packed generated decode runtime descriptor is not canonical"
        ) from exc
    if actual_digest != expected_digest:
        raise GeneratedDecodeError(
            "packed generated decode runtime descriptor SHA-256 mismatch"
        )

    runtime_program = descriptor.get("device_program")
    device_program = signature.get("device_program", runtime_program)
    if not isinstance(runtime_program, Mapping) or not _same_json_identity(
        runtime_program, device_program
    ):
        raise GeneratedDecodeError(
            "packed generated decode signature disagrees with its runtime "
            "descriptor"
        )
    program_key = device_program.get("key")
    if not isinstance(program_key, str) or not program_key:
        raise GeneratedDecodeError(
            "packed generated decode receipt has no device program key"
        )
    source_sha256 = _receipt_sha256(
        signature.get("source_sha256"),
        "source_sha256",
    )
    if variant_key is not None:
        expected_variant_key = (
            f"generated_{program_key}_{source_sha256[:16]}_"
            f"{expected_digest[:16]}"
        )
        if variant_key != expected_variant_key:
            raise GeneratedDecodeError(
                "packed generated decode variant key disagrees with its "
                "source/runtime-descriptor identity"
            )
    return expected_digest, program_key, source_sha256


def _validated_packed_receipt(receipt: Mapping[str, Any]) -> dict[str, Any]:
    if not isinstance(receipt, Mapping) or not _PACKED_RECEIPT_FIELDS.issubset(receipt):
        raise GeneratedDecodeError(
            "generated decode requires a complete packed-AOT receipt")
    program = receipt["program"]
    if (
        not isinstance(program, Mapping)
        or type(program.get("schema_version")) is not int
        or program.get("schema_version") != 1
        or any(
            not isinstance(program.get(name), str) or not program[name]
            for name in ("registration", "program")
        )
    ):
        raise GeneratedDecodeError(
            "packed generated decode receipt has invalid program identity")
    capacity = receipt["capacity"]
    num_ctas = receipt["num_ctas"]
    static = receipt["static_extent_bindings"]
    minimums = receipt.get("runtime_extent_minimums", {})
    maximums = receipt.get("runtime_extent_maximums", {})
    architecture = receipt["architecture"]
    architecture_valid = (
        type(architecture) is str
        and re.fullmatch(r"sm[0-9]+(?:a)?", architecture) is not None
    )
    if (
        type(receipt["schema_version"]) is not int
        or receipt["schema_version"] != 1
        or receipt["backend"] != "generated_decode_aot"
        or receipt["family"] != "generated_decode"
        or receipt["delivery"] != "packed_aot"
        or any(
            not isinstance(receipt[name], str) or not receipt[name]
            for name in ("variant_key", "architecture", "device_program_key")
        )
        or not architecture_valid
        or isinstance(capacity, bool)
        or not isinstance(capacity, int)
        or capacity <= 0
        or isinstance(num_ctas, bool)
        or not isinstance(num_ctas, int)
        or num_ctas <= 0
        or not isinstance(static, Mapping)
        or not isinstance(minimums, Mapping)
        or not isinstance(maximums, Mapping)
        or any(
            not isinstance(name, str)
            or not name
            or isinstance(value, bool)
            or not isinstance(value, int)
            or value < 0
            for name, value in static.items()
        )
        or any(
            not isinstance(name, str)
            or not name
            or isinstance(value, bool)
            or not isinstance(value, int)
            or value <= 1
            for name, value in minimums.items()
        )
        or any(
            not isinstance(name, str)
            or not name
            or isinstance(value, bool)
            or not isinstance(value, int)
            or value <= 0
            for name, value in maximums.items()
        )
    ):
        raise GeneratedDecodeError(
            "generated decode receipt is not exact packed AOT")
    result = {name: receipt[name] for name in _PACKED_RECEIPT_FIELDS}
    result["program"] = dict(program)
    result["static_extent_bindings"] = dict(static)
    result["runtime_extent_minimums"] = dict(minimums)
    result["runtime_extent_maximums"] = dict(maximums)
    if "build_toolchain_sha256" in receipt:
        result["build_toolchain_sha256"] = _receipt_sha256(
            receipt["build_toolchain_sha256"], "build_toolchain_sha256"
        )
    for name in _RECEIPT_HASH_FIELDS:
        result[name] = _receipt_sha256(receipt[name], name)
    return json.loads(json.dumps(
        result, sort_keys=True, separators=(",", ":")
    ))


@dataclass
class _GeneratedDecodeLaunchCounter:
    _binding_count: int = 1
    _launches_by_active_batch: dict[int, int] = field(default_factory=dict)


_LAUNCH_COUNTERS: dict[str, _GeneratedDecodeLaunchCounter] = {}
_LAUNCH_COUNTERS_LOCK = threading.Lock()


def _register_launch_counter(
    receipt: Mapping[str, Any],
) -> _GeneratedDecodeLaunchCounter:
    receipt_json = json.dumps(
        _validated_packed_receipt(receipt),
        sort_keys=True,
        separators=(",", ":"),
    )
    with _LAUNCH_COUNTERS_LOCK:
        counter = _LAUNCH_COUNTERS.get(receipt_json)
        if counter is None:
            counter = _GeneratedDecodeLaunchCounter()
            _LAUNCH_COUNTERS[receipt_json] = counter
        else:
            counter._binding_count += 1
    return counter


def _record_launch(
    counter: _GeneratedDecodeLaunchCounter,
    active_batch: int,
) -> None:
    with _LAUNCH_COUNTERS_LOCK:
        counter._launches_by_active_batch[active_batch] = (
            counter._launches_by_active_batch.get(active_batch, 0) + 1
        )


def launch_snapshot() -> dict[str, Any]:
    """Return process-cumulative packed-AOT bindings and successful launches.

    Counters are monotonic and never reset. Callers establish a measurement
    boundary by diffing linearizable snapshots. Multiple serving slots bind the
    same exact artifact, so rows aggregate binding and launch counts by
    immutable receipt.
    Counts observe direct ``BoundGeneratedDecode`` dispatches. The current
    runtime is eager; a future graph runtime must instrument graph replay too.
    """

    with _LAUNCH_COUNTERS_LOCK:
        artifacts = [{
            **json.loads(receipt_json),
            "binding_count": int(counter._binding_count),
            "launches_by_active_batch": {
                str(int(active_batch)): int(count)
                for active_batch, count in counter._launches_by_active_batch.items()
            },
        } for receipt_json, counter in sorted(_LAUNCH_COUNTERS.items())]
    return {
        "schema_version": 1,
        "backend": "generated_decode_aot",
        "binding_count": sum(int(row["binding_count"]) for row in artifacts),
        "launch_count": sum(
            int(count)
            for row in artifacts for count in row["launches_by_active_batch"].values()
        ),
        "artifacts": artifacts,
    }


def _interleave_gate_up_rows8(value: torch.Tensor, axis: int) -> torch.Tensor:
    rows = int(value.shape[axis])
    if rows % 16:
        raise GeneratedDecodeError(
            f"gate/up row extent must be divisible by 16, got {rows}")
    half = rows // 2
    gate, up = value.split(half, dim=axis)
    blocked = (*value.shape[:axis], half // 8, 8, *value.shape[axis + 1 :])
    return torch.stack(
        (gate.reshape(blocked), up.reshape(blocked)), dim=axis + 1
    ).reshape(value.shape).contiguous()


def _prepare_weight(
    sources: tuple[torch.Tensor, ...],
    pipeline: str | None,
    *,
    expected_shape: tuple[int, ...] | None = None,
):
    stages = [stage for stage in str(pipeline or "identity").split("|") if stage]
    if stages and stages[0] == "concat_rows":
        value = torch.cat(sources, dim=0)
        stages.pop(0)
    elif stages and stages[0] == "stack_axis0":
        value = torch.stack(sources, dim=0)
        stages.pop(0)
    elif stages and stages[0] == "concat_rows_with_zero_middle":
        if len(sources) != 2 or expected_shape is None:
            raise GeneratedDecodeError(
                "concat_rows_with_zero_middle requires two sources and an "
                "expected shape")
        first, last = sources
        if (
            first.ndim != last.ndim
            or first.ndim != len(expected_shape)
            or tuple(first.shape[1:]) != tuple(last.shape[1:])
            or tuple(first.shape[1:]) != expected_shape[1:]
            or first.dtype != last.dtype
            or first.device != last.device
        ):
            raise GeneratedDecodeError(
                "concat_rows_with_zero_middle sources disagree on storage")
        middle_rows = expected_shape[0] - first.shape[0] - last.shape[0]
        if middle_rows <= 0:
            raise GeneratedDecodeError(
                "concat_rows_with_zero_middle expected shape leaves no middle rows")
        middle = first.new_zeros((middle_rows, *expected_shape[1:]))
        value = torch.cat((first, middle, last), dim=0)
        stages.pop(0)
    elif len(sources) == 1:
        value = sources[0]
    else:
        raise GeneratedDecodeError(
            f"weight recipe has {len(sources)} sources without a combine stage")
    for stage in stages:
        if stage == "identity":
            continue
        if stage in {"cast_bf16", "cast_fp32"}:
            if not value.is_floating_point():
                raise GeneratedDecodeError(
                    "floating weight casts cannot decode packed integer weights; "
                    "a quantized weight recipe must bind its scales explicitly")
            value = value.to(
                torch.bfloat16 if stage == "cast_bf16" else torch.float32)
        elif stage == "squeeze_depthwise_conv1d":
            if value.ndim != 3 or int(value.shape[1]) != 1:
                raise GeneratedDecodeError(
                    "squeeze_depthwise_conv1d expects [channels, 1, kernel]")
            value = value.squeeze(1).contiguous()
        elif stage == "pack_conv1d_segments":
            if value.ndim != 3:
                raise GeneratedDecodeError(
                    "pack_conv1d_segments expects [out, in, kernel]")
            value = value.permute(2, 0, 1).contiguous()
        elif stage == "pack_conv_transpose1d_projection":
            if value.ndim != 3:
                raise GeneratedDecodeError(
                    "pack_conv_transpose1d_projection expects [in, out, kernel]")
            value = value.permute(2, 1, 0).reshape(-1, value.shape[0]).contiguous()
        elif stage == "permute_021":
            if value.ndim != 3:
                raise GeneratedDecodeError(
                    "permute_021 expects a rank-three tensor")
            value = value.permute(0, 2, 1).contiguous()
        elif stage == "reshape_zero_pad_k":
            if (
                value.ndim < 2
                or expected_shape is None
                or len(expected_shape) != 2
            ):
                raise GeneratedDecodeError(
                    "reshape_zero_pad_k requires a compatible 2D expected shape"
                )
            flattened = value.flatten(1)
            if expected_shape[1] < flattened.shape[1]:
                raise GeneratedDecodeError(
                    "reshape_zero_pad_k expected shape truncates the source"
                )
            padded = value.new_zeros((flattened.shape[0], expected_shape[1]))
            padded[:, : flattened.shape[1]] = flattened
            value = padded
        elif stage == "pad_output_rows":
            if (
                expected_shape is None
                or value.ndim < 2
                or len(expected_shape) != value.ndim
                or tuple(value.shape[:-2]) != tuple(expected_shape[:-2])
                or value.shape[-1] != expected_shape[-1]
                or value.shape[-2] > expected_shape[-2]
            ):
                raise GeneratedDecodeError(
                    "pad_output_rows requires a compatible expected shape")
            padded = value.new_zeros(expected_shape)
            padded[..., : value.shape[-2], :] = value
            value = padded
        elif stage == "interleave_gate_up_rows8_axis0":
            value = _interleave_gate_up_rows8(value, 0)
        elif stage == "interleave_gate_up_rows8_axis1":
            value = _interleave_gate_up_rows8(value, 1)
        elif stage == "view_uint8":
            value = value.view(torch.uint8)
        else:
            raise GeneratedDecodeError(
                f"shipped weight recipe uses unsupported preparation {stage!r}")
    return value


def _recipe_expected(
    recipe: Mapping[str, Any],
) -> tuple[tuple[int, ...], torch.dtype]:
    try:
        raw_shape = recipe["shape"]
        raw_dtype = recipe["dtype"]
        if (
            type(raw_shape) not in (list, tuple)
            or any(type(dim) is not int or dim < 0 for dim in raw_shape)
            or type(raw_dtype) is not str
        ):
            raise ValueError("noncanonical weight shape/dtype")
        shape = tuple(raw_shape)
        dtype = _TORCH_DTYPES[raw_dtype]
    except (KeyError, TypeError, ValueError) as exc:
        raise GeneratedDecodeError(
            f"generated decode weight recipe {recipe.get('name')!r} has an "
            "invalid shape/dtype contract"
        ) from exc
    return shape, dtype


def _recipe_variant_branches(
    descriptor: Mapping[str, Any],
    recipe: Mapping[str, Any],
) -> frozenset[str]:
    """Return branches that make a recipe optional for one logical row.

    Missing ownership metadata is deliberately interpreted as required, never
    inactive.  This keeps legacy or malformed descriptors fail-closed while new
    compiler output can authorize zero rows without importing compiler source.
    """

    raw = recipe.get("branches")
    if raw is None:
        return frozenset()
    if (
        not isinstance(raw, Sequence)
        or isinstance(raw, (str, bytes))
        or not raw
        or any(not isinstance(branch, str) or not branch for branch in raw)
    ):
        raise GeneratedDecodeError(
            f"generated decode weight recipe {recipe.get('name')!r} has invalid "
            "branch ownership")
    branches = frozenset(raw)
    if len(branches) != len(raw):
        raise GeneratedDecodeError(
            f"generated decode weight recipe {recipe.get('name')!r} has duplicate "
            "branch ownership")
    if "both" in branches or "tail" in branches:
        return frozenset()

    layer_branches = descriptor.get("weight_layer_branches")
    num_layers = descriptor.get("num_layers")
    if (
        isinstance(num_layers, bool)
        or not isinstance(num_layers, int)
        or num_layers <= 0
        or not isinstance(layer_branches, Sequence)
        or isinstance(layer_branches, (str, bytes))
        or len(layer_branches) != num_layers
        or any(not isinstance(branch, str) or not branch for branch in layer_branches)
    ):
        raise GeneratedDecodeError(
            "generated decode branch-owned weight recipes require an exact "
            "logical layer-branch map")
    unknown = branches - frozenset(layer_branches)
    if unknown:
        raise GeneratedDecodeError(
            f"generated decode weight recipe {recipe.get('name')!r} owns "
            f"undeclared branches {sorted(unknown)}")
    return branches


def _recipe_source_keys(
    recipe: Mapping[str, Any],
    layer: int | None,
    layer_prefix: str,
) -> tuple[str, ...]:
    source_names = tuple(recipe.get("sources") or (recipe["source"],))
    if not source_names or any(
        not isinstance(source, str) or not source for source in source_names
    ):
        raise GeneratedDecodeError(
            f"generated decode weight recipe {recipe.get('name')!r} has invalid "
            "source names")
    return tuple(
        source if layer is None else f"{layer_prefix}.{int(layer)}.{source}"
        for source in source_names
    )


def _recipe_row_sources(
    descriptor: Mapping[str, Any],
    recipe: Mapping[str, Any],
    layer: int | None,
    layer_prefix: str,
    named: Mapping[str, torch.Tensor],
) -> tuple[torch.Tensor, ...] | None:
    """Resolve one physical row, returning ``None`` only when provably inactive."""

    branches = _recipe_variant_branches(descriptor, recipe)
    if branches and layer is not None:
        if isinstance(layer, bool) or not isinstance(layer, int):
            raise GeneratedDecodeError(
                f"generated decode weight recipe {recipe.get('name')!r} has an "
                f"invalid physical layer {layer!r}")
        layer_branches = descriptor["weight_layer_branches"]
        if layer < 0 or layer >= len(layer_branches):
            raise GeneratedDecodeError(
                f"generated decode weight recipe {recipe.get('name')!r} has an "
                f"out-of-range physical layer {layer}")
        if str(layer_branches[layer]) not in branches:
            return None

    keys = _recipe_source_keys(recipe, layer, layer_prefix)
    present = tuple(key in named for key in keys)
    if all(present):
        return tuple(named[key] for key in keys)
    if any(present):
        missing = [key for key, is_present in zip(keys, present) if not is_present]
        raise GeneratedDecodeError(
            f"generated decode weight recipe {recipe.get('name')!r} has "
            f"partially present sources; missing={missing}")
    raise GeneratedDecodeError(
        f"missing generated-decode active weight source {keys[0]!r}")


@dataclass
class GeneratedWeightStorage:
    buffers: dict[str, torch.Tensor]
    aliased_source_bytes: int = 0
    retained_source_bytes: int = 0
    weight_contract: str | None = None
    retained_recipes: tuple["RetainedWeightRecipe", ...] = ()
    finalized: bool = True
    topology_contract: str | None = None
    _recipes: Mapping[str, Any] = field(
        default_factory=lambda: MappingProxyType({}),
        init=False,
        repr=False,
        compare=False,
    )
    _aliased_source_storages: frozenset[tuple[str, int, int]] = field(
        default_factory=frozenset,
        init=False,
        repr=False,
        compare=False,
    )
    _retained_source_storages: frozenset[tuple[str, int, int]] = field(
        default_factory=frozenset,
        init=False,
        repr=False,
        compare=False,
    )


@dataclass(frozen=True)
class RetainedWeightRecipe:
    """One physical row that remains derived from model-owned source tensors."""

    name: str
    physical_row: int
    source_keys: tuple[str, ...]


def _weight_recipes_by_name(
    descriptor: Mapping[str, Any],
) -> Mapping[str, Any]:
    recipes = {}
    for recipe in descriptor["weights"]:
        name = str(recipe["name"])
        if name in recipes:
            raise GeneratedDecodeError(
                f"duplicate generated-decode weight name {name!r}")
        recipes[name] = _freeze_identity({
            key: value for key, value in recipe.items() if key != "knobs"
        })
    return MappingProxyType(recipes)


def weight_storage_contract(descriptor: Mapping[str, Any]) -> str:
    """Identify weight storage independently of program-specific launch knobs."""

    return json.dumps(
        {
            name: _json_identity(recipe)
            for name, recipe in _weight_recipes_by_name(descriptor).items()
        },
        sort_keys=True,
        separators=(",", ":"),
    )


def _track_weight_storage(
    storage: GeneratedWeightStorage,
    descriptor: Mapping[str, Any],
    aliased: Collection[tuple[str, int, int]],
    retained: Collection[tuple[str, int, int]],
) -> GeneratedWeightStorage:
    storage._recipes = _weight_recipes_by_name(descriptor)
    return _set_weight_source_accounting(storage, aliased, retained)


def _set_weight_source_accounting(
    storage: GeneratedWeightStorage,
    aliased: Collection[tuple[str, int, int]],
    retained: Collection[tuple[str, int, int]],
) -> GeneratedWeightStorage:
    aliased_storages = frozenset(aliased)
    retained_storages = frozenset(retained) - aliased_storages
    storage._aliased_source_storages = aliased_storages
    storage._retained_source_storages = retained_storages
    storage.aliased_source_bytes = sum(item[2] for item in aliased_storages)
    storage.retained_source_bytes = sum(item[2] for item in retained_storages)
    return storage


def _weight_buffer_matches(
    value: Any,
    recipe: Mapping[str, Any],
) -> bool:
    shape = tuple(int(item) for item in recipe["shape"])
    if recipe["per_layer"]:
        shape = (len(recipe["physical_layers"]), *shape)
    return (
        isinstance(value, torch.Tensor)
        and tuple(value.shape) == shape
        and value.dtype == _TORCH_DTYPES[recipe["dtype"]]
    )


def _add_weight_views(
    buffers: dict[str, torch.Tensor],
    recipes: Sequence[Mapping[str, Any]],
) -> None:
    for recipe in recipes:
        if recipe.get("kind") != "view":
            continue
        try:
            source = buffers[recipe["source"]]
        except KeyError as exc:
            raise GeneratedDecodeError(
                f"weight view {recipe['name']!r} references unknown physical "
                f"source {recipe['source']!r}"
            ) from exc
        axis = int(recipe["view_axis"]) + (1 if recipe["per_layer"] else 0)
        buffers[recipe["name"]] = source.narrow(
            axis,
            int(recipe["view_start"]),
            int(recipe["shape"][int(recipe["view_axis"])]),
        )


def _storage_identity(value: torch.Tensor) -> tuple[str, int, int]:
    storage = value.untyped_storage()
    # StorageImpl identity remains distinct for independent meta tensors, whose
    # data pointers are all zero. It also identifies aliased views before any
    # real device allocation exists.
    return str(value.device), int(storage._cdata), int(storage.nbytes())


def _tensor_view_identity(value: torch.Tensor) -> tuple[Any, ...]:
    """Identify one exact tensor view without dereferencing its contents."""

    return (
        _storage_identity(value),
        str(value.dtype),
        tuple(value.shape),
        tuple(value.stride()),
        int(value.storage_offset()),
    )


def _recipe_stages(recipe: Mapping[str, Any]) -> tuple[str, ...]:
    return tuple(
        stage for stage in str(recipe.get("prep") or "identity").split("|")
        if stage and stage != "identity"
    )


def _source_view(
    physical: torch.Tensor,
    source: torch.Tensor,
    recipe: Mapping[str, Any],
) -> torch.Tensor | None:
    """Return the original logical weight as a view of one physical row."""

    if recipe.get("sources"):
        return None
    stages = _recipe_stages(recipe)
    facts = []
    probe = torch.empty_strided(
        tuple(source.shape), tuple(source.stride()),
        dtype=source.dtype, device="meta",
    )
    for stage in stages:
        facts.append((tuple(probe.shape), probe.dtype))
        if stage == "cast_bf16":
            if probe.dtype != torch.bfloat16:
                return None
        elif stage == "cast_fp32":
            if probe.dtype != torch.float32:
                return None
        elif stage == "squeeze_depthwise_conv1d":
            if probe.ndim != 3 or int(probe.shape[1]) != 1:
                return None
            probe = probe.squeeze(1)
        elif stage == "view_uint8":
            probe = probe.view(torch.uint8)
        else:
            return None
    if tuple(probe.shape) != tuple(physical.shape) or probe.dtype != physical.dtype:
        return None

    view = physical
    for stage, (shape, dtype) in reversed(tuple(zip(stages, facts))):
        if stage in {"cast_bf16", "cast_fp32"}:
            continue
        if stage == "squeeze_depthwise_conv1d":
            view = view.unsqueeze(1)
        elif stage == "view_uint8":
            view = view.view(dtype).view(shape)
    if tuple(view.shape) != tuple(source.shape) or view.dtype != source.dtype:
        return None
    return view


def _weight_cache_key(
    descriptor: Mapping[str, Any],
    layer_prefix: str,
    engine_buffers: Mapping[str, torch.Tensor],
    weight_sources: Mapping[str, torch.Tensor] | None,
    owned_source_storages: frozenset[tuple[str, int, int]] = frozenset(),
) -> str:
    engines = {
        name: {
            "shape": list(value.shape),
            "dtype": str(value.dtype),
            "device": str(value.device),
            "data_ptr": int(value.data_ptr()),
        }
        for name, value in sorted(engine_buffers.items())
    }
    return json.dumps(
        {
            "layer_prefix": layer_prefix,
            **_weight_topology_identity(descriptor),
            "weights": _json_identity(descriptor["weights"]),
            "engine_buffers": engines,
            "weight_source_objects": (
                None
                if weight_sources is None
                else {
                    name: id(value)
                    for name, value in sorted(weight_sources.items())
                }
            ),
            "owned_source_storages": sorted(owned_source_storages),
        },
        sort_keys=True,
        separators=(",", ":"),
    )


def _weight_topology_identity(descriptor: Mapping[str, Any]) -> dict[str, Any]:
    """Snapshot the logical row topology that determines physical weight contents."""

    return {
        "num_layers": _json_identity(descriptor.get("num_layers")),
        "weight_layer_branches": _json_identity(
            descriptor.get("weight_layer_branches")
        ),
    }


def weight_topology_contract(descriptor: Mapping[str, Any]) -> str:
    """Return the immutable storage-layout identity for a runtime descriptor."""

    return json.dumps(
        _weight_topology_identity(descriptor),
        sort_keys=True,
        separators=(",", ":"),
    )


def _recipe_is_explicit_zero(recipe: Mapping[str, Any]) -> bool:
    """Match the compiler binder's source-free ``zeros`` contract."""

    prep = recipe.get("prep")
    return (
        recipe.get("sources") is None
        and isinstance(prep, str)
        and prep.split("|", 1)[0].strip() == "zeros"
    )


def _validate_named_tensor_aliases(
    module: torch.nn.Module,
    names: Sequence[str],
) -> None:
    parameter_requires_grad = set()
    for name in names:
        parent_name, separator, leaf = name.rpartition(".")
        parent = module.get_submodule(parent_name) if separator else module
        if leaf in parent._parameters:
            previous = parent._parameters[leaf]
            if previous is None:
                raise GeneratedDecodeError(
                    f"generated-decode weight source {name!r} is an empty parameter"
                )
            parameter_requires_grad.add(bool(previous.requires_grad))
        elif leaf not in parent._buffers:
            raise GeneratedDecodeError(
                f"generated-decode weight source {name!r} is not a parameter or buffer"
            )
    if len(parameter_requires_grad) > 1:
        raise GeneratedDecodeError(
            "one generated-decode storage alias has conflicting gradient ownership"
        )


def _replace_named_tensor_aliases(
    module: torch.nn.Module,
    names: Sequence[str],
    value: torch.Tensor,
) -> None:
    """Replace every name for one tensor while preserving tied parameters."""

    _validate_named_tensor_aliases(module, names)
    parameter_locations = []
    buffer_locations = []
    requires_grad = None
    for name in names:
        parent_name, separator, leaf = name.rpartition(".")
        parent = module.get_submodule(parent_name) if separator else module
        if leaf in parent._parameters:
            parameter_locations.append((parent, leaf))
            requires_grad = bool(parent._parameters[leaf].requires_grad)
        else:
            buffer_locations.append((parent, leaf))
    if parameter_locations:
        replacement = torch.nn.Parameter(value, requires_grad=bool(requires_grad))
        for parent, leaf in parameter_locations:
            parent._parameters[leaf] = replacement
    for parent, leaf in buffer_locations:
        parent._buffers[leaf] = value


def allocate_weight_storage_for_loading(
    module: torch.nn.Module,
    descriptor: Mapping[str, Any],
    *,
    device: torch.device | str,
    layer_prefix: str | None = None,
    engine_buffers: Mapping[str, torch.Tensor] | None = None,
) -> GeneratedWeightStorage:
    """Allocate final generated weights and bind load targets into their views.

    This is the pre-load counterpart to :func:`materialize_weights`. Sources
    exactly recoverable as final-layout views are rebound immediately. Recipes
    that require a real transform retain explicit source ownership and must be
    completed with :func:`finalize_weight_storage_after_loading` before launch.
    """

    layer_prefix = str(
        descriptor["weight_layer_prefix"] if layer_prefix is None else layer_prefix
    )
    target_device = torch.device(device)
    named = dict(module.named_parameters(remove_duplicate=False))
    named.update(dict(module.named_buffers(remove_duplicate=False)))
    engine_buffers = dict(engine_buffers or {})
    names_by_object: dict[int, list[str]] = {}
    storage_references: dict[tuple[str, int, int], set[int]] = {}
    for name, value in named.items():
        names_by_object.setdefault(id(value), []).append(name)
        storage_references.setdefault(_storage_identity(value), set()).add(id(value))

    recipes = tuple(descriptor["weights"])
    recipe_names = [str(recipe["name"]) for recipe in recipes]
    if len(recipe_names) != len(set(recipe_names)):
        raise GeneratedDecodeError("generated-decode weight names must be unique")

    source_use_count: dict[int, int] = {}
    binding_plan: list[
        tuple[Mapping[str, Any], int, tuple[str, ...], tuple[torch.Tensor, ...]]
    ] = []
    zero_initialized: set[str] = set()
    for recipe in recipes:
        if recipe.get("kind", "param") != "param":
            continue
        if _recipe_is_explicit_zero(recipe):
            zero_initialized.add(str(recipe["name"]))
            continue
        physical_layers = tuple(recipe["physical_layers"])
        if not recipe["per_layer"] and len(physical_layers) != 1:
            raise GeneratedDecodeError(
                f"weight {recipe['name']!r} cannot stream multiple logical rows "
                "into one shared physical tensor"
            )
        active_rows = 0
        for row, layer in enumerate(physical_layers):
            sources = _recipe_row_sources(
                descriptor, recipe, layer, layer_prefix, named
            )
            if sources is None:
                if not recipe["per_layer"]:
                    raise GeneratedDecodeError(
                        f"weight {recipe['name']!r} has an inactive model-scoped source"
                    )
                zero_initialized.add(str(recipe["name"]))
                continue
            active_rows += 1
            keys = _recipe_source_keys(recipe, layer, layer_prefix)
            for source in sources:
                source_use_count[id(source)] = source_use_count.get(id(source), 0) + 1
            binding_plan.append((recipe, row, keys, sources))
        if recipe["per_layer"] and active_rows == 0:
            raise GeneratedDecodeError(
                f"generated decode weight recipe {recipe['name']!r} has no "
                "active physical rows"
            )

    # Validate every source transformation before allocating or replacing anything.
    direct_bindings = []
    retained_recipes = []
    retained_storages = {}
    for recipe, row, keys, sources in binding_plan:
        expected_shape, expected_dtype = _recipe_expected(recipe)
        physical_probe = torch.empty(
            expected_shape, dtype=expected_dtype, device="meta"
        )
        if len({str(source.device) for source in sources}) != 1:
            raise GeneratedDecodeError(
                f"weight {recipe['name']!r} sources disagree on device"
            )
        source_probes = tuple(
            torch.empty_strided(
                tuple(source.shape), tuple(source.stride()),
                dtype=source.dtype, device="meta",
            )
            for source in sources
        )
        prepared_probe = _prepare_weight(
            source_probes, recipe.get("prep"), expected_shape=expected_shape)
        if (
            tuple(prepared_probe.shape) != expected_shape
            or prepared_probe.dtype != expected_dtype
        ):
            raise GeneratedDecodeError(
                f"weight {recipe['name']!r} prepares as "
                f"{tuple(prepared_probe.shape)}/{prepared_probe.dtype}, expected "
                f"{expected_shape}/{expected_dtype}"
            )

        source = sources[0] if len(sources) == 1 else None
        identity = None if source is None else _storage_identity(source)
        view = None
        if (
            source is not None
            and source_use_count[id(source)] == 1
            and len(storage_references[identity]) == 1
        ):
            view = _source_view(physical_probe, source, recipe)
        if view is not None:
            aliases = tuple(names_by_object[id(source)])
            _validate_named_tensor_aliases(module, aliases)
            direct_bindings.append((recipe, row, source, aliases))
            continue

        retained_recipes.append(RetainedWeightRecipe(
            name=str(recipe["name"]),
            physical_row=int(row),
            source_keys=tuple(keys),
        ))
        for item in sources:
            source_identity = _storage_identity(item)
            retained_storages[source_identity] = source_identity[2]

    planned_shapes: dict[str, tuple[int, ...]] = {}
    for recipe in recipes:
        if recipe.get("kind") == "view":
            continue
        if recipe.get("kind", "param") == "engine_buffer":
            key = recipe.get("engine_buffer")
            try:
                planned_shapes[recipe["name"]] = tuple(engine_buffers[key].shape)
            except KeyError as exc:
                raise GeneratedDecodeError(
                    f"missing engine-owned weight buffer {key!r}"
                ) from exc
            continue
        expected_shape, _expected_dtype = _recipe_expected(recipe)
        physical_layers = tuple(recipe["physical_layers"])
        planned_shapes[recipe["name"]] = (
            (len(physical_layers), *expected_shape)
            if recipe["per_layer"]
            else expected_shape
        )

    for recipe in recipes:
        if recipe.get("kind") != "view":
            continue
        try:
            source_shape = planned_shapes[recipe["source"]]
        except KeyError as exc:
            raise GeneratedDecodeError(
                f"weight view {recipe['name']!r} references unknown physical "
                f"source {recipe['source']!r}"
            ) from exc
        logical_axis = int(recipe["view_axis"])
        recipe_shape, _recipe_dtype = _recipe_expected(recipe)
        if not 0 <= logical_axis < len(recipe_shape):
            raise GeneratedDecodeError(
                f"weight view {recipe['name']!r} has invalid axis {logical_axis}"
            )
        axis = logical_axis + (1 if recipe["per_layer"] else 0)
        start = int(recipe["view_start"])
        length = recipe_shape[logical_axis]
        if (
            not 0 <= axis < len(source_shape)
            or start < 0
            or start + length > source_shape[axis]
        ):
            raise GeneratedDecodeError(
                f"weight view {recipe['name']!r} is outside source "
                f"{recipe['source']!r}"
            )
        actual_shape = list(source_shape)
        actual_shape[axis] = length
        expected_view_shape = (
            (len(tuple(recipe["physical_layers"])), *recipe_shape)
            if recipe["per_layer"]
            else recipe_shape
        )
        if tuple(actual_shape) != expected_view_shape:
            raise GeneratedDecodeError(
                f"weight view {recipe['name']!r} shape does not match its source"
            )

    buffers: dict[str, torch.Tensor] = {}
    for recipe in recipes:
        if recipe.get("kind") == "view":
            continue
        if recipe.get("kind", "param") == "engine_buffer":
            key = recipe.get("engine_buffer")
            buffers[recipe["name"]] = engine_buffers[key]
            continue

        expected_shape, expected_dtype = _recipe_expected(recipe)
        physical_layers = tuple(recipe["physical_layers"])
        shape = (
            (len(physical_layers), *expected_shape)
            if recipe["per_layer"]
            else expected_shape
        )
        initialize_zero = str(recipe["name"]) in zero_initialized
        value = (
            torch.zeros(shape, dtype=expected_dtype, device=target_device)
            if initialize_zero
            else torch.empty(shape, dtype=expected_dtype, device=target_device)
        )
        buffers[recipe["name"]] = value

    aliased_storages = {}
    for recipe, row, source, aliases in direct_bindings:
        value = buffers[recipe["name"]]
        physical = value[row] if recipe["per_layer"] else value
        view = _source_view(physical, source, recipe)
        if view is None:  # The meta validation above established this invariant.
            raise AssertionError("validated generated weight view became invalid")
        _replace_named_tensor_aliases(module, aliases, view)
        identity = _storage_identity(source)
        aliased_storages[identity] = identity[2]

    _add_weight_views(buffers, recipes)

    storage = _track_weight_storage(
        GeneratedWeightStorage(
            buffers=buffers,
            weight_contract=repr(descriptor["weights"]),
            topology_contract=weight_topology_contract(descriptor),
            retained_recipes=tuple(retained_recipes),
            finalized=not retained_recipes,
        ),
        descriptor,
        aliased_storages,
        retained_storages,
    )
    if storage.finalized:
        cache_key = _weight_cache_key(
            descriptor, layer_prefix, engine_buffers, None)
        cache = module.__dict__.setdefault(
            "_kestrel_generated_decode_weight_storage", {})
        cache[cache_key] = storage
    return storage


def finalize_weight_storage_after_loading(
    module: torch.nn.Module,
    descriptor: Mapping[str, Any],
    storage: GeneratedWeightStorage,
    *,
    layer_prefix: str | None = None,
    engine_buffers: Mapping[str, torch.Tensor] | None = None,
) -> GeneratedWeightStorage:
    """Complete retained transforms in a preallocated generated-weight slab."""

    expected_weight_contract = repr(descriptor["weights"])
    if storage.weight_contract != expected_weight_contract:
        raise GeneratedDecodeError(
            "preallocated generated weights do not match the selected program"
        )
    expected_topology_contract = weight_topology_contract(descriptor)
    if storage.topology_contract != expected_topology_contract:
        raise GeneratedDecodeError(
            "preallocated generated weights do not match the selected program topology"
        )

    layer_prefix = str(
        descriptor["weight_layer_prefix"] if layer_prefix is None else layer_prefix
    )
    engine_buffers = dict(engine_buffers or {})
    descriptor_recipes = tuple(descriptor["weights"])
    recipe_names = tuple(str(recipe["name"]) for recipe in descriptor_recipes)
    if len(set(recipe_names)) != len(recipe_names):
        raise GeneratedDecodeError("generated-decode weight names must be unique")
    named = dict(module.named_parameters(remove_duplicate=False))
    named.update(dict(module.named_buffers(remove_duplicate=False)))

    retained_by_row = {}
    for retained in storage.retained_recipes:
        key = (retained.name, retained.physical_row)
        if key in retained_by_row:
            raise GeneratedDecodeError(
                f"duplicate retained generated-weight row {key!r}"
            )
        retained_by_row[key] = retained

    # Validate engine-owned rows and the cache destination before any transform
    # can mutate the physical slab.
    for recipe in descriptor_recipes:
        if recipe.get("kind", "param") != "engine_buffer":
            continue
        name = str(recipe["name"])
        engine_key = recipe.get("engine_buffer")
        try:
            physical = storage.buffers[name]
            engine_value = engine_buffers[engine_key]
        except KeyError as exc:
            raise GeneratedDecodeError(
                f"missing engine-owned weight buffer {exc.args[0]!r}"
            ) from exc
        if _tensor_view_identity(physical) != _tensor_view_identity(engine_value):
            raise GeneratedDecodeError(
                f"engine-owned weight buffer {engine_key!r} no longer matches "
                f"preallocated generated storage {name!r}"
            )

    cache_key = _weight_cache_key(
        descriptor, layer_prefix, engine_buffers, None)
    cache = module.__dict__.setdefault(
        "_kestrel_generated_decode_weight_storage", {})
    cached = cache.get(cache_key)
    if cached is not None and cached is not storage:
        raise GeneratedDecodeError(
            "another generated-weight slab already owns the selected cache key"
        )

    plan = []
    expected_source_rows = set()
    aliased_storages = set()
    retained_storages = set()
    for recipe in descriptor_recipes:
        if (
            recipe.get("kind", "param") != "param"
            or _recipe_is_explicit_zero(recipe)
        ):
            continue
        name = str(recipe["name"])
        try:
            physical = storage.buffers[name]
        except KeyError as exc:
            raise GeneratedDecodeError(
                f"missing preallocated generated-weight buffer {name!r}"
            ) from exc
        layers = tuple(recipe["physical_layers"])
        expected_shape, expected_dtype = _recipe_expected(recipe)
        for row, layer in enumerate(layers):
            key = (name, row)
            target = physical[row] if recipe["per_layer"] else physical
            if tuple(target.shape) != expected_shape or target.dtype != expected_dtype:
                raise GeneratedDecodeError(
                    f"generated-weight row {key!r} has invalid target storage"
                )
            sources = _recipe_row_sources(
                descriptor, recipe, layer, layer_prefix, named
            )
            if sources is None:
                continue
            expected_source_rows.add(key)
            expected_keys = _recipe_source_keys(recipe, layer, layer_prefix)

            retained = retained_by_row.get(key)
            if retained is None:
                # Every non-retained row must still be the exact direct view
                # installed during allocation. Merely sharing the same slab is
                # insufficient because an offset/stride mismatch corrupts ABI.
                if len(sources) != 1 or sources[0].device.type == "meta":
                    raise GeneratedDecodeError(
                        f"generated-weight row {key!r} is neither retained nor "
                        "a loaded direct source"
                    )
                direct_view = _source_view(target, sources[0], recipe)
                if (
                    direct_view is None
                    or _tensor_view_identity(sources[0])
                    != _tensor_view_identity(direct_view)
                ):
                    raise GeneratedDecodeError(
                        f"direct generated-weight row {key!r} no longer aliases "
                        "its exact target view"
                    )
                aliased_storages.add(_storage_identity(sources[0]))
                continue

            if retained.source_keys != expected_keys:
                raise GeneratedDecodeError(
                    f"retained generated-weight row {key!r} changed source ownership"
                )
            if any(source.device.type == "meta" for source in sources):
                raise GeneratedDecodeError(
                    f"retained generated-weight row {key!r} was not loaded"
                )
            if (
                len({str(source.device) for source in sources}) != 1
                or sources[0].device != target.device
            ):
                raise GeneratedDecodeError(
                    f"retained generated-weight row {key!r} sources disagree with "
                    f"target device {target.device}"
                )
            source_probes = tuple(
                torch.empty_strided(
                    tuple(source.shape), tuple(source.stride()),
                    dtype=source.dtype, device="meta",
                )
                for source in sources
            )
            prepared_probe = _prepare_weight(
                source_probes, recipe.get("prep"), expected_shape=expected_shape)
            if (
                tuple(prepared_probe.shape) != expected_shape
                or prepared_probe.dtype != expected_dtype
            ):
                raise GeneratedDecodeError(
                    f"retained generated-weight row {key!r} prepares as "
                    f"{tuple(prepared_probe.shape)}/{prepared_probe.dtype}, expected "
                    f"{expected_shape}/{expected_dtype}"
                )
            plan.append((recipe, key, sources, target))
            retained_storages.update(map(_storage_identity, sources))

    if set(retained_by_row) - expected_source_rows:
        extra = sorted(set(retained_by_row) - expected_source_rows)[0]
        raise GeneratedDecodeError(
            f"retained generated-weight row {extra!r} is not source-backed"
        )
    if not storage.finalized and not plan:
        raise GeneratedDecodeError(
            "unfinalized generated weights declare no retained recipes"
        )
    if storage.finalized:
        _set_weight_source_accounting(
            storage, aliased_storages, retained_storages)
        if cached is None:
            cache[cache_key] = storage
        return storage

    # The load plan is complete before the first physical row is mutated. Only
    # each transformed temporary is released after its copy; the declared source
    # tensors remain module-owned because native prefill still consumes them.
    for recipe, key, sources, target in plan:
        expected_shape, expected_dtype = _recipe_expected(recipe)
        prepared = _prepare_weight(
            sources, recipe.get("prep"), expected_shape=expected_shape)
        if (
            tuple(prepared.shape) != expected_shape
            or prepared.dtype != expected_dtype
            or prepared.device != target.device
        ):
            raise GeneratedDecodeError(
                f"retained generated-weight row {key!r} prepared as "
                f"{tuple(prepared.shape)}/{prepared.dtype}/{prepared.device}, "
                f"expected {expected_shape}/{expected_dtype}/{target.device}"
            )
        with torch.no_grad():
            target.copy_(prepared)

    _set_weight_source_accounting(
        storage, aliased_storages, retained_storages)
    storage.finalized = True
    cache[cache_key] = storage
    return storage


def materialize_weights(
    module: torch.nn.Module,
    descriptor: Mapping[str, Any],
    *,
    layer_prefix: str | None = None,
    engine_buffers: Mapping[str, torch.Tensor] | None = None,
    weight_sources: Mapping[str, torch.Tensor] | None = None,
    _owned_source_storages: frozenset[tuple[str, int, int]] = frozenset(),
) -> GeneratedWeightStorage:
    """Materialize compiler-emitted weight recipes without compiler imports.

    View-compatible sources become views of their physical slab, so native and
    generated execution share storage. Irreversible transforms remain owned by
    both representations.
    """

    layer_prefix = str(
        descriptor["weight_layer_prefix"] if layer_prefix is None else layer_prefix
    )
    if weight_sources is None:
        named = dict(module.named_parameters(remove_duplicate=False))
        named.update(dict(module.named_buffers(remove_duplicate=False)))
    else:
        named = dict(weight_sources)
        if not all(isinstance(value, torch.Tensor) for value in named.values()):
            raise GeneratedDecodeError(
                "generated decode weight sources must map names to tensors")
    engine_buffers = dict(engine_buffers or {})
    cache_key = _weight_cache_key(
        descriptor,
        layer_prefix,
        engine_buffers,
        weight_sources,
        _owned_source_storages,
    )
    cache = module.__dict__.setdefault(
        "_kestrel_generated_decode_weight_storage", {})
    cached = cache.get(cache_key)
    if cached is not None:
        return cached

    source_use_count: dict[int, int] = {}
    storage_references: dict[tuple[str, int, int], set[int]] = {}
    for value in named.values():
        storage_references.setdefault(_storage_identity(value), set()).add(id(value))
    for recipe in descriptor["weights"]:
        if (
            recipe.get("kind", "param") != "param"
            or _recipe_is_explicit_zero(recipe)
        ):
            continue
        for layer in recipe["physical_layers"]:
            sources = _recipe_row_sources(
                descriptor, recipe, layer, layer_prefix, named)
            if sources is None:
                continue
            for value in sources:
                source_use_count[id(value)] = source_use_count.get(id(value), 0) + 1

    buffers = {}
    aliased_storages = {}
    retained_storages = {}
    for recipe in descriptor["weights"]:
        if recipe.get("kind") == "view":
            continue
        if recipe.get("kind", "param") == "engine_buffer":
            key = recipe.get("engine_buffer")
            try:
                buffers[recipe["name"]] = engine_buffers[key]
            except KeyError as exc:
                raise GeneratedDecodeError(
                    f"missing engine-owned weight buffer {key!r}") from exc
            continue
        explicit_zero = _recipe_is_explicit_zero(recipe)
        expected_shape, expected_dtype = _recipe_expected(recipe)
        prepared_rows = []
        source_rows = []
        for layer in recipe["physical_layers"]:
            if explicit_zero:
                sources = ()
                try:
                    source_free_device = next(iter(named.values())).device
                except StopIteration as exc:
                    raise GeneratedDecodeError(
                        "cannot place a source-free generated-decode zero without "
                        "a model weight or explicit weight source"
                    ) from exc
                prepared = torch.zeros(
                    expected_shape,
                    dtype=expected_dtype,
                    device=source_free_device,
                )
            else:
                sources = _recipe_row_sources(
                    descriptor, recipe, layer, layer_prefix, named
                )
                if sources is None:
                    prepared_rows.append(None)
                    source_rows.append(())
                    continue
                prepared = _prepare_weight(
                    sources,
                    recipe.get("prep"),
                    expected_shape=expected_shape,
                )
            if (
                tuple(prepared.shape) != expected_shape
                or prepared.dtype != expected_dtype
            ):
                raise GeneratedDecodeError(
                    f"weight {recipe['name']!r} prepared as "
                    f"{tuple(prepared.shape)}/{prepared.dtype}, expected "
                    f"{expected_shape}/{expected_dtype}")
            prepared_rows.append(prepared)
            source_rows.append(sources)
        if recipe["per_layer"]:
            first = next(
                (prepared for prepared in prepared_rows if prepared is not None),
                None,
            )
            if first is None:
                raise GeneratedDecodeError(
                    f"generated decode weight recipe {recipe['name']!r} has no "
                    "active physical rows")
            factory = torch.zeros if any(
                prepared is None for prepared in prepared_rows
            ) else torch.empty
            value = factory(
                (len(prepared_rows), *expected_shape),
                dtype=expected_dtype,
                device=first.device,
            )
            for row, prepared in enumerate(prepared_rows):
                if prepared is not None:
                    value[row].copy_(prepared)
        else:
            if len(prepared_rows) != 1 or prepared_rows[0] is None:
                raise GeneratedDecodeError(
                    f"generated decode weight recipe {recipe['name']!r} has an "
                    "invalid model-scoped source")
            value = prepared_rows[0].contiguous()
        buffers[recipe["name"]] = value

        for row, sources in enumerate(source_rows):
            physical = value[row] if recipe["per_layer"] else value
            source = sources[0] if len(sources) == 1 else None
            identity = None if source is None else _storage_identity(source)
            view = None
            if (
                source is not None
                and identity not in _owned_source_storages
                and source_use_count[id(source)] == 1
                and len(storage_references[identity]) == 1
            ):
                view = _source_view(physical, source, recipe)
            if view is None:
                for item in sources:
                    source_identity = _storage_identity(item)
                    if source_identity not in _owned_source_storages:
                        retained_storages[source_identity] = source_identity[2]
                continue
            source.data = view
            identity = _storage_identity(source)
            aliased_storages[identity] = identity[2]

    _add_weight_views(buffers, descriptor["weights"])

    storage = _track_weight_storage(
        GeneratedWeightStorage(
            buffers=buffers,
            weight_contract=repr(descriptor["weights"]),
            topology_contract=weight_topology_contract(descriptor),
        ),
        descriptor,
        aliased_storages,
        retained_storages,
    )
    cache[cache_key] = storage
    return storage


def extend_weight_storage(
    storage: GeneratedWeightStorage,
    module: torch.nn.Module,
    descriptor: Mapping[str, Any],
    *,
    layer_prefix: str | None = None,
    engine_buffers: Mapping[str, torch.Tensor] | None = None,
    weight_sources: Mapping[str, torch.Tensor] | None = None,
) -> GeneratedWeightStorage:
    """Return finalized storage covering ``descriptor`` without mutating it."""

    if not isinstance(storage, GeneratedWeightStorage):
        raise GeneratedDecodeError(
            "generated weight storage extension requires materialized storage"
        )
    if not storage.finalized:
        raise GeneratedDecodeError(
            "generated weight storage must be finalized before extension"
        )
    requested = _weight_recipes_by_name(descriptor)
    missing = []
    for recipe in descriptor["weights"]:
        name = str(recipe["name"])
        existing = storage._recipes.get(name)
        if existing is not None:
            if existing != requested[name]:
                raise GeneratedDecodeError(
                    f"generated weight storage has conflicting recipe {name!r}"
                )
            value = storage.buffers.get(name)
            if not _weight_buffer_matches(value, recipe):
                raise GeneratedDecodeError(
                    f"generated weight storage has invalid buffer {name!r}"
                )
            if recipe.get("kind") == "view":
                source = storage.buffers.get(recipe.get("source"))
                if not isinstance(source, torch.Tensor):
                    raise GeneratedDecodeError(
                        f"generated weight storage has invalid view source "
                        f"{recipe.get('source')!r}"
                    )
                try:
                    logical_axis = int(recipe["view_axis"])
                    axis = logical_axis + (1 if recipe["per_layer"] else 0)
                    expected = source.narrow(
                        axis,
                        int(recipe["view_start"]),
                        int(recipe["shape"][logical_axis]),
                    )
                except (IndexError, RuntimeError, TypeError, ValueError) as exc:
                    raise GeneratedDecodeError(
                        f"generated weight storage has invalid view buffer {name!r}"
                    ) from exc
                if _tensor_view_identity(value) != _tensor_view_identity(expected):
                    raise GeneratedDecodeError(
                        f"generated weight storage has invalid view buffer {name!r}"
                    )
            continue
        if name in storage.buffers:
            raise GeneratedDecodeError(
                f"generated weight storage has untracked buffer {name!r}"
            )
        missing.append(recipe)
    if not missing:
        return storage

    missing_values = [
        recipe for recipe in missing if recipe.get("kind") != "view"
    ]
    owned_storages = frozenset(
        _storage_identity(value)
        for value in storage.buffers.values()
        if isinstance(value, torch.Tensor)
    ) | storage._retained_source_storages
    if missing_values:
        addition = materialize_weights(
            module,
            {**descriptor, "weights": missing_values},
            layer_prefix=layer_prefix,
            engine_buffers=engine_buffers,
            weight_sources=weight_sources,
            _owned_source_storages=owned_storages,
        )
    else:
        addition = GeneratedWeightStorage({})

    buffers = {**storage.buffers, **addition.buffers}
    recipes = {**storage._recipes, **addition._recipes}
    _add_weight_views(buffers, missing)
    recipes.update(
        (recipe["name"], requested[recipe["name"]])
        for recipe in missing if recipe.get("kind") == "view"
    )

    combined_aliased = (
        storage._aliased_source_storages
        | addition._aliased_source_storages
    )
    combined_retained = (
        storage._retained_source_storages
        | addition._retained_source_storages
    ) - combined_aliased
    combined = _set_weight_source_accounting(
        GeneratedWeightStorage(buffers=buffers),
        combined_aliased,
        combined_retained,
    )
    combined._recipes = MappingProxyType(recipes)
    return combined


def _physical_operands(descriptor: Mapping[str, Any]) -> dict[str, dict]:
    try:
        values = tuple(descriptor["device_program"]["physical_abi"]["operands"])
        operands = {
            value["abi_name"]: dict(value)
            for value in values
            if isinstance(value, Mapping)
            and isinstance(value.get("abi_name"), str)
            and value["abi_name"]
        }
    except (KeyError, TypeError) as exc:
        raise GeneratedDecodeError(
            "generated decode descriptor has no valid physical ABI") from exc
    if len(operands) != len(values):
        raise GeneratedDecodeError(
            "generated decode physical ABI has malformed or duplicate arguments")
    return operands


def _workspace_bindings(descriptor: Mapping[str, Any]) -> dict[str, dict]:
    try:
        raw = descriptor["device_program"]["workspace_plan"]["bindings"]
    except (KeyError, TypeError) as exc:
        raise GeneratedDecodeError(
            "generated decode descriptor has no valid workspace plan") from exc
    if not isinstance(raw, (list, tuple)) or any(
        not isinstance(value, Mapping) for value in raw
    ):
        raise GeneratedDecodeError(
            "generated decode descriptor has a malformed workspace plan")
    values = tuple(dict(value) for value in raw)
    all_names = tuple(value.get("name") for value in values)
    if (
        any(not isinstance(name, str) or not name for name in all_names)
        or len(all_names) != len(set(all_names))
        or any(
            value.get("storage") not in {
                "activation", "stream", "stream_alias", "output_alias",
            }
            for value in values
        )
    ):
        raise GeneratedDecodeError(
            "generated decode workspace plan has malformed or duplicate names")
    selected = tuple(
        value for value in values
        if value["storage"] in {"activation", "stream"}
    )
    names = tuple(value["name"] for value in selected)
    return dict(zip(names, selected, strict=True))


def _validated_workspace_bindings(
    descriptor: Mapping[str, Any],
    arguments: Sequence[Mapping[str, Any]],
) -> dict[str, dict]:
    bindings = _workspace_bindings(descriptor)
    workspace_arguments = tuple(
        argument for argument in arguments
        if argument.get("source") == "workspace"
    )
    names = tuple(argument.get("name") for argument in workspace_arguments)
    if names != tuple(bindings):
        raise GeneratedDecodeError(
            "generated decode workspace plan does not exactly match workspace "
            "argument order")
    runtime_extent_names = {
        argument.get("name") for argument in arguments
        if (
            argument.get("transport") == "scalar"
            and argument.get("dtype") == "int32"
            and argument.get("source") in {"external", "runtime_extent"}
        )
    }
    batch_capacity = _shape_environment(descriptor, "active_batch")
    if batch_capacity is None and descriptor.get("capacity") is not None:
        batch_capacity = _descriptor_capacity(descriptor)
    for argument, binding in zip(
        workspace_arguments, bindings.values(), strict=True
    ):
        name = str(argument["name"])
        try:
            semantic_shape = tuple(binding["semantic_shape"])
            physical_shape = tuple(binding["physical_shape"])
            dynamic_symbols = tuple(binding["dynamic_symbols"])
            argument_symbols = tuple(argument["dynamic_symbols"])
            argument_shape = tuple(argument["shape"])
        except (KeyError, TypeError) as exc:
            raise GeneratedDecodeError(
                f"generated decode workspace {name!r} is malformed") from exc
        expected_symbols = tuple(sorted({
            dim for dim in semantic_shape if isinstance(dim, str)
        }))
        valid_semantic_shape = all(
            (type(dim) is int and dim > 0)
            or (isinstance(dim, str) and bool(dim))
            for dim in semantic_shape
        )
        valid_physical_shape = all(
            (type(dim) is int and dim > 0)
            or (isinstance(dim, str) and bool(dim))
            for dim in physical_shape
        )
        has_batch_prefix = (
            len(physical_shape) == len(semantic_shape) + 1
            and physical_shape[1:] == semantic_shape
            and batch_capacity is not None
            and _workspace_capacity_shape(descriptor, binding)[0]
            == batch_capacity
        )
        expected_transport = "raw_pointer" if dynamic_symbols else "tensor"
        expected_shape = (1,) if dynamic_symbols else physical_shape
        if (
            binding.get("name") != name
            or argument.get("logical_name") != name
            or argument.get("dtype") != binding.get("dtype")
            or argument.get("access") != "read_write"
            or argument.get("transport") != expected_transport
            or argument_shape != expected_shape
            or dynamic_symbols != expected_symbols
            or argument_symbols != dynamic_symbols
            or not set(dynamic_symbols).issubset(runtime_extent_names)
            or argument.get("dynamic_stride_axes", ())
            or not valid_semantic_shape
            or not valid_physical_shape
            or not (physical_shape == semantic_shape or has_batch_prefix)
            or not isinstance(binding.get("layout"), str)
            or not binding["layout"]
        ):
            raise GeneratedDecodeError(
                f"generated decode workspace {name!r} disagrees with its "
                "compiler argument plan")
    return bindings


def _workspace_dynamic_scalars(
    bindings: Mapping[str, Mapping[str, Any]],
) -> frozenset[str]:
    values = []
    for binding in bindings.values():
        dynamic = binding.get("dynamic_symbols", ())
        if (
            not isinstance(dynamic, (list, tuple))
            or any(type(name) is not str or not name for name in dynamic)
            or len(dynamic) != len(set(dynamic))
        ):
            raise GeneratedDecodeError(
                "generated decode workspace plan has invalid dynamic scalars"
            )
        values.extend(dynamic)
    return frozenset(values)


def _workspace_capacity_shape(
    descriptor: Mapping[str, Any],
    binding: Mapping[str, Any],
) -> tuple[int, ...]:
    name = str(binding.get("name", "<unnamed>"))
    resolved = []
    for dim in binding["physical_shape"]:
        if type(dim) is int:
            value = dim
        elif isinstance(dim, str) and dim:
            value = _shape_environment(descriptor, dim)
        else:
            value = None
        if type(value) is not int or value <= 0:
            raise GeneratedDecodeError(
                f"generated decode workspace {name!r} has unresolved physical "
                f"extent {dim!r}")
        resolved.append(value)
    return tuple(resolved)


def _physical_dynamic_scalars(
    descriptor: Mapping[str, Any],
) -> tuple[str, ...]:
    try:
        physical_abi = descriptor["device_program"]["physical_abi"]
        values = physical_abi.get("dynamic_scalars", ())
    except (AttributeError, KeyError, TypeError) as exc:
        raise GeneratedDecodeError(
            "generated decode descriptor has no valid physical ABI"
        ) from exc
    if (
        not isinstance(values, (list, tuple))
        or any(type(name) is not str or not name for name in values)
        or len(values) != len(set(values))
    ):
        raise GeneratedDecodeError(
            "generated decode physical ABI has invalid dynamic scalars"
        )
    return tuple(values)


def _storage_extent_capacities(
    descriptor: Mapping[str, Any],
    runtime_extents: Mapping[str, Any],
) -> dict[str, int]:
    """Resolve dynamic backing storage against every permitted launch value."""

    operands = _physical_operands(descriptor)
    dynamic_values = _physical_dynamic_scalars(descriptor)
    referenced = set()
    for operand in operands.values():
        for shape_name in ("semantic_shape", "storage_shape"):
            shape = operand.get(shape_name, ())
            if not isinstance(shape, (list, tuple)):
                raise GeneratedDecodeError(
                    f"generated decode physical operand {operand['abi_name']!r} "
                    f"has invalid {shape_name}")
            referenced.update(dim for dim in shape if isinstance(dim, str))
    if set(dynamic_values) != referenced:
        raise GeneratedDecodeError(
            "generated decode physical ABI dynamic scalars disagree with storage "
            "shapes")
    resolved = {}
    for name in dynamic_values:
        try:
            live = runtime_extents[name]
        except KeyError as exc:
            raise GeneratedDecodeError(
                f"generated decode dynamic storage needs runtime extent "
                f"{name!r}") from exc
        if name == "active_batch":
            capacity = descriptor.get("capacity")
        else:
            # Construction-derived storage extents such as Qwen's ``n_pages``,
            # ``page_table_capacity``, and ``state_rows`` intentionally do not
            # enter the compile-time shape environment. Their backing capacity
            # is the value derived from the bound storage itself and becomes a
            # fixed launch stride below. A declared shape-environment value is
            # still authoritative when the compiler specializes one.
            capacity = _shape_environment(descriptor, name)
            if capacity is None:
                capacity = live
        if (
            type(live) is not int
            or live <= 0
            or type(capacity) is not int
            or capacity <= 0
        ):
            raise GeneratedDecodeError(
                f"generated decode dynamic storage has invalid extent "
                f"{name!r}={live!r} or capacity {capacity!r}")
        if live > capacity:
            raise GeneratedDecodeError(
                f"generated decode runtime extent {name!r}={live} exceeds "
                f"storage capacity {capacity}")
        resolved[name] = capacity
    return resolved


def _stride_forming_runtime_extents(
    operands: Mapping[str, Mapping[str, Any]],
    workspace_bindings: Mapping[str, Mapping[str, Any]] | None = None,
) -> frozenset[str]:
    """Return pointer-only shape symbols that physically determine inner strides."""

    fixed = set()
    for operand in operands.values():
        transport = operand.get("transport")
        if transport == "raw_pointer":
            storage_shape = operand.get("storage_shape", ())
            shape = storage_shape if storage_shape else operand.get(
                "semantic_shape", ()
            )
        elif transport == "layer_address_table":
            storage_shape = operand.get("storage_shape", ())
            semantic_shape = operand.get("semantic_shape", ())
            shape = storage_shape if storage_shape else semantic_shape[1:]
        else:
            continue
        if not isinstance(shape, (list, tuple)):
            raise GeneratedDecodeError(
                f"generated decode operand {operand.get('abi_name')!r} has "
                "invalid pointer-only storage shape")
        fixed.update(
            dim for axis, dim in enumerate(shape)
            if axis > 0 and isinstance(dim, str)
        )
    for binding in (workspace_bindings or {}).values():
        if binding.get("dynamic_symbols"):
            semantic_shape = tuple(binding.get("semantic_shape", ()))
            physical_shape = tuple(binding.get("physical_shape", ()))
            prefix = len(physical_shape) - len(semantic_shape)
            if prefix < 0:
                raise GeneratedDecodeError(
                    f"generated decode workspace {binding.get('name')!r} has "
                    "invalid physical/semantic rank")
            fixed.update(
                dim for axis, dim in enumerate(semantic_shape, start=prefix)
                if axis > 0 and isinstance(dim, str)
            )
    return frozenset(fixed)


@dataclass(frozen=True)
class _AddressTableBinding:
    """One generated table plus exact aliases for every address it embeds."""

    table: torch.Tensor
    rows: tuple[torch.Tensor | None, ...]
    pointers: tuple[int, ...]
    table_identity: tuple[Any, ...] = ()


class _AssembledBindings(dict):
    """Named ABI values carrying private provenance for derived tables."""

    __slots__ = (
        "_address_tables",
        "_device_program",
        "_runtime_extents",
        "_sealed",
    )

    def __init__(
        self,
        device_program: Mapping[str, Any],
        runtime_extents: Mapping[str, int],
    ) -> None:
        super().__init__()
        object.__setattr__(self, "_address_tables", {})
        object.__setattr__(self, "_device_program", _freeze_identity(device_program))
        object.__setattr__(
            self,
            "_runtime_extents",
            MappingProxyType(dict(runtime_extents)),
        )
        object.__setattr__(self, "_sealed", False)

    def __setattr__(self, name: str, value: Any) -> None:
        if getattr(self, "_sealed", False):
            raise AttributeError(
                "generated decode binding provenance is immutable")
        object.__setattr__(self, name, value)

    def _seal(self) -> None:
        object.__setattr__(
            self,
            "_address_tables",
            MappingProxyType(dict(self._address_tables)),
        )
        object.__setattr__(self, "_sealed", True)


def _binding_torch_stream(stream: Any, device: torch.device) -> torch.cuda.Stream:
    target = torch.device(device)
    if target.type != "cuda":
        raise GeneratedDecodeError(
            "generated decode pointer tables need a CUDA stream on CUDA")
    if target.index is None:
        target = torch.device("cuda", torch.cuda.current_device())
    if isinstance(stream, torch.cuda.Stream):
        if torch.device(stream.device) != target:
            raise GeneratedDecodeError(
                "generated decode stream and pointer table span CUDA devices")
        return stream
    raw = getattr(stream, "cuda_stream", stream)
    if type(raw) is not int or raw < 0:
        raise GeneratedDecodeError(
            "generated decode stream has no canonical CUDA address")
    address = raw
    if address == 0:
        return torch.cuda.default_stream(target)
    return torch.cuda.ExternalStream(address, device=target)


def _pointer_table(
    pointers: Sequence[int],
    *,
    device: torch.device,
    stream: Any,
) -> torch.Tensor:
    target = torch.device(device)
    if target.type != "cuda":
        return torch.tensor(pointers, dtype=torch.int64, device=target)
    launch_stream = _binding_torch_stream(stream, target)
    with torch.cuda.stream(launch_stream):
        return torch.tensor(pointers, dtype=torch.int64, device=target)


def _resolved_physical_shape(
    shape: Any,
    runtime_extents: Mapping[str, Any],
    *,
    contract: str,
) -> tuple[tuple[int, bool], ...]:
    if not isinstance(shape, (list, tuple)):
        raise GeneratedDecodeError(
            f"generated decode {contract} has an invalid shape contract")
    resolved = []
    for dim in shape:
        if type(dim) is int:
            if dim <= 0:
                raise GeneratedDecodeError(
                    f"generated decode {contract} has an invalid shape contract")
            resolved.append((dim, False))
            continue
        if not isinstance(dim, str) or not dim:
            raise GeneratedDecodeError(
                f"generated decode {contract} has an invalid shape contract")
        try:
            value = runtime_extents[dim]
        except KeyError as exc:
            raise GeneratedDecodeError(
                f"generated decode {contract} needs runtime extent {dim!r}") from exc
        if type(value) is not int or value <= 0:
            raise GeneratedDecodeError(
                f"generated decode {contract} has invalid runtime extent "
                f"{dim!r}={value!r}")
        resolved.append((value, True))
    return tuple(resolved)


def _validate_external_operand_contract(
    argument: Mapping[str, Any],
    operand: Mapping[str, Any],
) -> None:
    name = str(argument.get("name", "<unnamed>"))
    try:
        semantic_shape = tuple(operand["semantic_shape"])
        abi_shape = tuple(operand["abi_shape"])
        argument_shape = tuple(argument["shape"])
        operand_symbols = tuple(operand["dynamic_symbols"])
        argument_symbols = tuple(argument["dynamic_symbols"])
        operand_stride_axes = tuple(operand.get("dynamic_stride_axes", ()))
        argument_stride_axes = tuple(argument.get("dynamic_stride_axes", ()))
    except (KeyError, TypeError) as exc:
        raise GeneratedDecodeError(
            f"generated decode physical operand {name!r} is malformed") from exc
    required_strings = (
        "logical_name", "abi_name", "kind", "owner", "access", "transport",
        "dtype", "logical_dtype", "storage_dtype", "layout",
    )
    if (
        any(
            not isinstance(operand.get(field), str) or not operand[field]
            for field in required_strings
        )
        or not isinstance(operand.get("semantic_shape"), (list, tuple))
        or not isinstance(operand.get("abi_shape"), (list, tuple))
        or not isinstance(operand.get("dynamic_symbols"), (list, tuple))
        or any(not isinstance(symbol, str) or not symbol for symbol in operand_symbols)
        or len(operand_symbols) != len(set(operand_symbols))
        or tuple(sorted(operand_symbols)) != operand_symbols
        or type(operand.get("assumed_align")) is not int
        or operand["assumed_align"] <= 0
        or operand["assumed_align"] & (operand["assumed_align"] - 1)
        or (
            not semantic_shape
            and operand.get("transport") not in {"scalar", "tensor"}
        )
    ):
        raise GeneratedDecodeError(
            f"generated decode physical operand {name!r} is malformed")
    if (
        operand.get("abi_name") != name
        or argument.get("source") != "external"
        or operand.get("logical_name") != argument.get("logical_name")
        or operand.get("transport") != argument.get("transport")
        or operand.get("dtype") != argument.get("dtype")
        or operand.get("access") != argument.get("access")
        or operand.get("assumed_align") != argument.get("assumed_align")
        or abi_shape != argument_shape
        or operand_symbols != argument_symbols
        or operand_stride_axes != argument_stride_axes
    ):
        raise GeneratedDecodeError(
            f"generated decode physical operand {name!r} disagrees with its "
            "argument plan")


_EXTERNAL_OWNER_BY_KIND = {
    "weight": "binder",
    "state": "engine",
    "stream": "engine",
    "runtime": "engine",
    "output": "vm",
}


def _validate_external_operand_owner(operand: Mapping[str, Any]) -> str:
    kind = operand.get("kind")
    owner = operand.get("owner")
    if not isinstance(kind, str) or _EXTERNAL_OWNER_BY_KIND.get(kind) != owner:
        raise GeneratedDecodeError(
            f"generated decode operand {operand.get('abi_name')!r} has invalid "
            f"compiler owner/kind {owner!r}/{kind!r}")
    return str(owner)


def _validate_external_operand_transport(operand: Mapping[str, Any]) -> None:
    name = str(operand["abi_name"])
    transport = operand["transport"]
    semantic_shape = tuple(operand["semantic_shape"])
    abi_shape = tuple(operand["abi_shape"])
    dynamic_symbols = tuple(operand["dynamic_symbols"])
    layer_sources = operand.get("layer_sources", ())
    layer_rows = operand.get("layer_rows", ())
    padding_axes = operand.get("physical_padding_axes", ())
    if not isinstance(layer_sources, (list, tuple)) or not isinstance(
        layer_rows, (list, tuple)
    ) or not isinstance(padding_axes, (list, tuple)):
        raise GeneratedDecodeError(
            f"generated decode operand {name!r} has malformed layer metadata")
    if transport == "scalar":
        valid = (
            not semantic_shape
            and not abi_shape
            and not dynamic_symbols
            and not layer_sources
            and not layer_rows
            and not padding_axes
        )
    elif transport == "raw_pointer":
        valid = (
            abi_shape == (1,)
            and bool(dynamic_symbols)
            and not layer_sources
            and not layer_rows
            and not padding_axes
        )
    elif transport == "layer_address_table":
        valid = (
            len(abi_shape) == 1
            and type(abi_shape[0]) is int
            and abi_shape[0] > 0
            and len(semantic_shape) >= 1
            and semantic_shape[0] == abi_shape[0]
            and operand["dtype"] == "int64"
            and not layer_rows
            and not padding_axes
        )
    elif transport == "tensor":
        valid = not dynamic_symbols and not layer_sources
        expected_shape = semantic_shape
        if valid and layer_rows:
            valid = (
                bool(semantic_shape)
                and type(semantic_shape[0]) is int
                and len(layer_rows) == semantic_shape[0]
                and all(type(row) is int and row >= -1 for row in layer_rows)
            )
            active = tuple(row for row in layer_rows if row >= 0)
            valid = valid and tuple(sorted(active)) == tuple(range(len(active)))
            expected_shape = (len(active), *semantic_shape[1:])
        valid = valid and (
            len(expected_shape) == len(abi_shape)
            and all(type(axis) is int for axis in padding_axes)
            and len(padding_axes) == len(set(padding_axes))
            and tuple(padding_axes) == tuple(sorted(padding_axes))
            and all(0 <= axis < len(abi_shape) for axis in padding_axes)
        )
        if valid and padding_axes:
            valid = (
                operand.get("kind") == "weight"
                and operand.get("owner") == "binder"
                and operand.get("access") == "read"
                and all(
                    (
                        type(abi_extent) is int
                        and type(expected_extent) is int
                        and abi_extent > expected_extent
                    )
                    if axis in padding_axes
                    else abi_extent == expected_extent
                    for axis, (abi_extent, expected_extent) in enumerate(
                        zip(abi_shape, expected_shape, strict=True)
                    )
                )
            )
        else:
            valid = valid and abi_shape == expected_shape
    else:
        valid = False
    if not valid:
        raise GeneratedDecodeError(
            f"generated decode operand {name!r} has invalid {transport!r} "
            "physical transport metadata")


def _external_operand_owner(
    operand: Mapping[str, Any],
    *,
    weights: Mapping[str, torch.Tensor],
    runtime_inputs: Mapping[str, Any],
) -> Mapping[str, Any]:
    owner = _validate_external_operand_owner(operand)
    return weights if owner == "binder" else runtime_inputs


def _validated_external_operands(
    descriptor: Mapping[str, Any],
    arguments: Sequence[Mapping[str, Any]],
) -> dict[str, dict]:
    operands = _physical_operands(descriptor)
    external = tuple(
        argument for argument in arguments
        if argument.get("source") == "external"
    )
    names = tuple(str(argument.get("name")) for argument in external)
    if tuple(operands) != names:
        raise GeneratedDecodeError(
            "generated decode physical ABI does not exactly match external "
            "argument order")
    for argument, operand in zip(external, operands.values(), strict=True):
        _validate_external_operand_contract(argument, operand)
        _validate_external_operand_owner(operand)
        _validate_external_operand_transport(operand)
    return operands


def _validate_raw_pointer_storage(
    argument: Mapping[str, Any],
    operand: Mapping[str, Any],
    value: torch.Tensor,
    runtime_extents: Mapping[str, Any],
) -> None:
    """Validate semantic storage before building the one-element CuTe view."""

    _validate_external_operand_contract(argument, operand)
    name = str(argument["name"])
    semantic_shape = operand.get("semantic_shape")
    if operand.get("layer_sources") or operand.get("layer_rows"):
        raise GeneratedDecodeError(
            f"generated decode raw pointer {name!r} has invalid layer metadata")
    expected = _resolved_physical_shape(
        _physical_storage_shape(
            operand,
            semantic_shape,
            table_rows=False,
        ),
        runtime_extents,
        contract=f"raw pointer {name!r}",
    )
    expected_symbols = tuple(sorted({
        dim for dim in semantic_shape if isinstance(dim, str)
    }))
    dynamic_symbols = operand.get("dynamic_symbols")
    if (
        not isinstance(dynamic_symbols, (list, tuple))
        or tuple(dynamic_symbols) != expected_symbols
    ):
        raise GeneratedDecodeError(
            f"generated decode raw pointer {name!r} has invalid dynamic symbols")
    actual = tuple(int(dim) for dim in value.shape)
    if len(actual) != len(expected):
        raise GeneratedDecodeError(
            f"generated decode raw pointer {name!r} expects rank "
            f"{len(expected)}, got shape {actual}")
    for axis, (actual_dim, (required, dynamic)) in enumerate(
        zip(actual, expected, strict=True)
    ):
        # Capacity slack is representable only on the outermost storage axis.
        # A wider inner axis changes the contiguous strides used by every
        # preceding axis, while the raw-pointer kernel computes those strides
        # from the compiler-owned capacity.
        exact = not dynamic or axis > 0
        valid = actual_dim == required if exact else actual_dim >= required
        if not valid:
            relation = "exactly" if exact else "at least"
            raise GeneratedDecodeError(
                f"generated decode raw pointer {name!r} axis {axis} expects "
                f"{relation} {required}, got {actual_dim} in shape {actual}")
    expected_strides = _contiguous_strides(actual)
    actual_strides = tuple(int(stride) for stride in value.stride())
    if actual_strides != expected_strides:
        raise GeneratedDecodeError(
            f"generated decode raw pointer {name!r} expects contiguous storage "
            f"strides {expected_strides}, got {actual_strides}")
    _validate_tensor_storage_span(value, label=f"raw pointer {name!r}")


def _address_table_rows(
    values: Any,
    operand: Mapping[str, Any],
) -> tuple[Any, ...]:
    name = str(operand.get("abi_name", "<unnamed>"))
    try:
        rows = tuple(values)
    except TypeError as exc:
        raise GeneratedDecodeError(
            f"generated decode address table {name!r} needs tensor rows") from exc
    source_values = operand.get("layer_sources", ())
    if (
        not isinstance(source_values, (list, tuple))
        or any(type(row) is not int or row < 0 for row in source_values)
    ):
        raise GeneratedDecodeError(
            f"generated decode address table {name!r} has invalid layer aliases")
    sources = tuple(source_values)
    if sources:
        if len(rows) != len(sources) or any(row >= len(rows) for row in sources):
            raise GeneratedDecodeError(
                f"generated decode address table {name!r} has {len(rows)} "
                f"state rows for aliases {sources!r}")
        rows = tuple(rows[row] for row in sources)
    return rows


def _symbolic_contiguous_strides(shape: Sequence[Any]) -> tuple[Any, ...]:
    strides = []
    suffix = []
    for dim in reversed(tuple(shape)):
        if not suffix:
            strides.append(1)
        elif all(type(value) is int for value in suffix):
            strides.append(prod(suffix))
        else:
            static = prod(value for value in suffix if type(value) is int)
            symbols = [value for value in suffix if isinstance(value, str)]
            if static != 1:
                symbols.append(str(static))
            strides.append("*".join(symbols) if symbols else 1)
        suffix.append(dim)
    return tuple(reversed(strides))


def _physical_storage_shape(
    operand: Mapping[str, Any],
    semantic_shape: Sequence[Any],
    *,
    table_rows: bool,
) -> tuple[Any, ...]:
    name = str(operand.get("abi_name", "<unnamed>"))
    storage_shape = operand.get("storage_shape", ())
    semantic_axes = operand.get("semantic_axes", ())
    storage_axis_order = operand.get("storage_axis_order", ())
    storage_strides = operand.get("storage_strides", ())
    sequences = (storage_shape, semantic_axes, storage_axis_order, storage_strides)
    if any(not isinstance(item, (list, tuple)) for item in sequences):
        raise GeneratedDecodeError(
            f"generated decode physical operand {name!r} has invalid storage "
            "geometry")
    semantic_storage_shape = tuple(semantic_shape[1:] if table_rows else semantic_shape)
    has_storage_contract = bool(storage_shape)
    if any(bool(item) != has_storage_contract for item in sequences[1:]):
        raise GeneratedDecodeError(
            f"generated decode physical operand {name!r} has incomplete storage "
            "geometry")
    if not has_storage_contract:
        return semantic_storage_shape
    axes_valid = all(
        isinstance(axis, str) and axis
        for axis in (*semantic_axes, *storage_axis_order)
    )
    if (
        not axes_valid
        or len(semantic_axes) != len(semantic_storage_shape)
        or len(semantic_axes) != len(set(semantic_axes))
        or set(semantic_axes) != set(storage_axis_order)
        or len(storage_axis_order) != len(storage_shape)
        or tuple(storage_strides) != _symbolic_contiguous_strides(storage_shape)
    ):
        raise GeneratedDecodeError(
            f"generated decode physical operand {name!r} has invalid storage "
            "geometry")
    by_axis = dict(zip(semantic_axes, semantic_storage_shape, strict=True))
    if tuple(storage_shape) != tuple(by_axis[axis] for axis in storage_axis_order):
        raise GeneratedDecodeError(
            f"generated decode physical operand {name!r} storage shape is not "
            "the declared semantic-axis permutation")
    return tuple(storage_shape)


def _address_table_operand_contract(
    argument: Mapping[str, Any],
    operand: Mapping[str, Any],
    runtime_extents: Mapping[str, Any],
) -> tuple[torch.dtype, tuple[tuple[int, bool], ...], int]:
    name = str(argument["name"])
    _validate_external_operand_contract(argument, operand)
    storage_dtype = operand.get("storage_dtype")
    try:
        expected_dtype = _TORCH_DTYPES[storage_dtype]
    except (KeyError, TypeError) as exc:
        raise GeneratedDecodeError(
            f"generated decode address table {name!r} has an invalid storage "
            "dtype") from exc
    semantic_shape = operand.get("semantic_shape")
    semantic = _resolved_physical_shape(
        semantic_shape,
        runtime_extents,
        contract=f"address table {name!r} semantic shape",
    )
    argument_shape = tuple(argument["shape"])
    if (
        len(argument_shape) != 1
        or len(semantic) < 1
        or semantic[0][1]
        or semantic[0][0] != int(argument_shape[0])
    ):
        raise GeneratedDecodeError(
            f"generated decode address table {name!r} has invalid semantic rows")
    expected_symbols = tuple(sorted({
        dim for dim in semantic_shape if isinstance(dim, str)
    }))
    dynamic_symbols = operand.get("dynamic_symbols")
    if (
        not isinstance(dynamic_symbols, (list, tuple))
        or tuple(dynamic_symbols) != expected_symbols
    ):
        raise GeneratedDecodeError(
            f"generated decode address table {name!r} has invalid dynamic symbols")
    row_shape = _physical_storage_shape(
        operand,
        semantic_shape,
        table_rows=True,
    )
    expected = _resolved_physical_shape(
        row_shape,
        runtime_extents,
        contract=f"address table {name!r} row storage",
    )
    alignment = operand.get("storage_assumed_align", 1)
    if (
        type(alignment) is not int
        or alignment <= 0
        or alignment & (alignment - 1)
    ):
        raise GeneratedDecodeError(
            f"generated decode address table {name!r} has invalid storage "
            "alignment")
    return expected_dtype, expected, alignment


def _validate_address_table_row(
    argument: Mapping[str, Any],
    operand: Mapping[str, Any],
    value: Any,
    runtime_extents: Mapping[str, Any],
    *,
    device: torch.device,
    row: int,
) -> torch.Tensor:
    name = str(argument["name"])
    expected_dtype, expected, alignment = _address_table_operand_contract(
        argument,
        operand,
        runtime_extents,
    )
    if not isinstance(value, torch.Tensor):
        raise GeneratedDecodeError(
            f"generated decode address table {name!r} row {row} is not a tensor")
    alias = value.detach()
    target = torch.device(device)
    if target.type == "cuda" and target.index is None:
        target = torch.device("cuda", torch.cuda.current_device())
    if alias.device != target:
        raise GeneratedDecodeError(
            f"generated decode address table {name!r} row {row} is on "
            f"{alias.device}, expected {target}")
    if alias.dtype != expected_dtype:
        raise GeneratedDecodeError(
            f"generated decode address table {name!r} row {row} expects storage "
            f"dtype {expected_dtype}, got {alias.dtype}")
    _validate_tensor_storage_span(
        alias,
        label=f"address table {name!r} row {row}",
    )
    actual = tuple(int(dim) for dim in alias.shape)
    if len(actual) != len(expected):
        raise GeneratedDecodeError(
            f"generated decode address table {name!r} row {row} expects "
            f"storage rank {len(expected)}, got shape {actual}")
    for axis, (actual_dim, (required, dynamic)) in enumerate(
        zip(actual, expected, strict=True)
    ):
        # Each table entry already supplies the outer row base. Capacity slack
        # is therefore safe only on the row tensor's outermost storage axis;
        # wider inner axes would change compiler-owned contiguous strides.
        exact = not dynamic or axis > 0
        valid = actual_dim == required if exact else actual_dim >= required
        if not valid:
            relation = "exactly" if exact else "at least"
            raise GeneratedDecodeError(
                f"generated decode address table {name!r} row {row} storage "
                f"axis {axis} expects {relation} {required}, got {actual_dim} "
                f"in shape {actual}")
    expected_strides = _contiguous_strides(actual)
    actual_strides = tuple(int(stride) for stride in alias.stride())
    if actual_strides != expected_strides:
        raise GeneratedDecodeError(
            f"generated decode address table {name!r} row {row} expects "
            f"contiguous storage strides {expected_strides}, got "
            f"{actual_strides}")
    if int(alias.data_ptr()) % alignment:
        raise GeneratedDecodeError(
            f"generated decode address table {name!r} row {row} address "
            f"{int(alias.data_ptr()):#x} is not {alignment}-byte aligned")
    return alias


def _address_table(
    values: Any,
    argument: Mapping[str, Any],
    operand: Mapping[str, Any],
    runtime_extents: Mapping[str, Any],
    *,
    device: torch.device,
    stream: Any,
) -> _AddressTableBinding:
    _address_table_operand_contract(argument, operand, runtime_extents)
    rows = _address_table_rows(values, operand)
    expected_shape = tuple(argument["shape"])
    if len(expected_shape) != 1 or len(rows) != int(expected_shape[0]):
        raise GeneratedDecodeError(
            f"generated decode address table {argument['name']!r} has "
            f"{len(rows)} rows for compiler shape {expected_shape}")
    retained = []
    pointers = []
    for row, value in enumerate(rows):
        if value is None:
            # Branch-sparse state tables intentionally carry null rows for
            # layers that do not own this state kind (for example Gemma's
            # alternating local/global KV caches).
            retained.append(None)
            pointers.append(0)
            continue
        alias = _validate_address_table_row(
            argument,
            operand,
            value,
            runtime_extents,
            device=device,
            row=row,
        )
        retained.append(alias)
        pointers.append(int(alias.data_ptr()))
    table = _pointer_table(pointers, device=device, stream=stream)
    return _AddressTableBinding(
        table=table,
        rows=tuple(retained),
        pointers=tuple(pointers),
        table_identity=_tensor_binding_identity(table),
    )


_INT32_MIN = -(1 << 31)
_INT32_MAX = (1 << 31) - 1


def _validated_tape_contract(
    descriptor: Mapping[str, Any],
    *,
    require_metadata: bool = False,
) -> Mapping[str, Any]:
    """Validate the host tape against the compiler-emitted launch ABI."""

    tape = descriptor.get("tape")
    if not isinstance(tape, Mapping):
        raise GeneratedDecodeError(
            "generated decode descriptor has malformed instruction tape"
        )
    metadata_names = {"max_qlen", "num_ctas", "layout"}
    present_metadata = metadata_names & set(tape)
    if present_metadata != metadata_names:
        if present_metadata or require_metadata:
            raise GeneratedDecodeError(
                "generated decode instruction tape lacks exact compiler metadata"
            )
        return tape
    if set(tape) not in (
        {"instr", "qlen", *metadata_names},
        {"instr", "qlen", *metadata_names, "is_queue"},
    ):
        raise GeneratedDecodeError(
            "generated decode instruction tape has noncanonical metadata"
        )
    if "is_queue" in tape and type(tape["is_queue"]) is not bool:
        raise GeneratedDecodeError(
            "generated decode instruction tape has invalid queue metadata"
        )

    num_ctas = tape["num_ctas"]
    max_qlen = tape["max_qlen"]
    if type(num_ctas) is not int or num_ctas <= 0:
        raise GeneratedDecodeError(
            "generated decode instruction tape has invalid CTA count"
        )
    if (
        type(max_qlen) is not int
        or not 0 < max_qlen <= _INT32_MAX
    ):
        raise GeneratedDecodeError(
            "generated decode instruction tape has invalid queue capacity"
        )
    if num_ctas != _descriptor_num_ctas(descriptor):
        raise GeneratedDecodeError(
            "generated decode instruction tape CTA count disagrees with its grid"
        )
    layout = tape["layout"]
    if not _has_canonical_tape_layout(layout):
        raise GeneratedDecodeError(
            "generated decode instruction tape has an incompatible field layout"
        )

    tape_arguments = {
        str(argument["name"]): argument
        for argument in _arguments(descriptor)
        if argument.get("source") == "tape"
    }
    if set(tape_arguments) != {"instruction_tape", "queue_lengths"}:
        raise GeneratedDecodeError(
            "generated decode instruction tape has no exact argument ABI"
        )
    n_fields = layout["n_fields"]
    expected_shapes = {
        "instruction_tape": (num_ctas, max_qlen, n_fields),
        "queue_lengths": (num_ctas,),
    }
    for name, expected_shape in expected_shapes.items():
        argument = tape_arguments[name]
        raw_shape = argument.get("shape")
        if (
            argument.get("transport") != "tensor"
            or argument.get("dtype") != "int32"
            or not isinstance(raw_shape, (list, tuple))
            or any(type(dimension) is not int for dimension in raw_shape)
            or tuple(raw_shape) != expected_shape
        ):
            raise GeneratedDecodeError(
                f"generated decode tape argument {name!r} disagrees with "
                "compiler tape geometry"
            )

    qlen = tape.get("qlen")
    instr = tape.get("instr")
    if not isinstance(qlen, (list, tuple)) or len(qlen) != num_ctas:
        raise GeneratedDecodeError(
            "generated decode instruction tape has malformed queue lengths"
        )
    for value in qlen:
        if (
            type(value) is not int
            or not 0 <= value <= max_qlen
            or not _INT32_MIN <= value <= _INT32_MAX
        ):
            raise GeneratedDecodeError(
                "generated decode instruction tape has an invalid queue length"
            )
    if not isinstance(instr, (list, tuple)) or len(instr) != num_ctas:
        raise GeneratedDecodeError(
            "generated decode instruction tape has malformed CTA rows"
        )
    for cta, rows in enumerate(instr):
        if not isinstance(rows, (list, tuple)) or len(rows) != max_qlen:
            raise GeneratedDecodeError(
                "generated decode instruction tape has malformed queue rows"
            )
        for row_index, row in enumerate(rows):
            if not isinstance(row, (list, tuple)) or len(row) != n_fields:
                raise GeneratedDecodeError(
                    "generated decode instruction tape has malformed instruction rows"
                )
            if any(
                type(value) is not int
                or not _INT32_MIN <= value <= _INT32_MAX
                for value in row
            ):
                raise GeneratedDecodeError(
                    "generated decode instruction tape has a value outside its "
                    "exact int32 ABI"
                )
            if row_index >= qlen[cta] and any(value != -1 for value in row):
                raise GeneratedDecodeError(
                    "generated decode instruction tape has noncanonical padding"
                )
            if (n_fields == 8 and row_index < qlen[cta]
                    and (not 0 <= row[6] <= 3 or row[7] != -1)):
                raise GeneratedDecodeError(
                    "generated decode instruction tape has invalid handoff fields")
    return tape


def _tape_tensor(
    descriptor: Mapping[str, Any],
    argument: Mapping[str, Any],
    *,
    device: torch.device | str,
    tape: Mapping[str, Any] | None = None,
) -> torch.Tensor:
    name = str(argument["name"])
    if tape is None:
        tape = _validated_tape_contract(descriptor)
    if name == "instruction_tape":
        return torch.tensor(
            tape["instr"], dtype=torch.int32, device=device
        ).reshape(tuple(argument["shape"]))
    if name == "queue_lengths":
        return torch.tensor(tape["qlen"], dtype=torch.int32, device=device)
    raise GeneratedDecodeError(f"unknown tape argument {name!r}")


def _binding_storage_specs(
    descriptor: Mapping[str, Any],
    *,
    weights: Mapping[str, torch.Tensor],
    runtime_inputs: Mapping[str, Any],
) -> tuple[tuple[tuple[int, ...], torch.dtype], ...]:
    """Return exact tensor allocations owned by one binding invocation."""

    arguments = _arguments(descriptor)
    tape_contract = (
        _validated_tape_contract(descriptor)
        if any(argument.get("source") == "tape" for argument in arguments)
        else None
    )
    operands = _validated_external_operands(descriptor, arguments)
    workspace_bindings = (
        _validated_workspace_bindings(descriptor, arguments)
        if any(argument.get("source") == "workspace" for argument in arguments)
        else {}
    )
    specs = []
    for argument in arguments:
        source = argument["source"]
        if source in {"workspace", "counter"}:
            shape = (
                _workspace_capacity_shape(
                    descriptor,
                    workspace_bindings[argument["name"]],
                )
                if source == "workspace"
                else tuple(int(dim) for dim in argument["shape"])
            )
            spec = (
                shape,
                _TORCH_DTYPES[argument["dtype"]],
            )
            specs.append(spec)
            if source == "counter":
                # Assembly returns one counter allocation; bind owns a second
                # private reset buffer so caller writes cannot race a launch.
                specs.append(spec)
            continue
        if source == "tape":
            value = _tape_tensor(
                descriptor,
                argument,
                device="meta",
                tape=tape_contract,
            )
            spec = (tuple(value.shape), value.dtype)
            # Assembly exposes one generated tape while bind reconstructs an
            # isolated launch copy from the frozen descriptor.
            specs.extend((spec, spec))
            continue
        if source == "external":
            try:
                operand = operands[argument["name"]]
            except KeyError as exc:
                raise GeneratedDecodeError(
                    f"generated decode external argument {argument['name']!r} "
                    "has no physical ABI") from exc
            _validate_external_operand_contract(argument, operand)
            if operand["transport"] != "layer_address_table":
                continue
            owner = _external_operand_owner(
                operand,
                weights=weights,
                runtime_inputs=runtime_inputs,
            )
            logical_name = operand["logical_name"]
            try:
                value = owner[logical_name]
            except KeyError as exc:
                raise GeneratedDecodeError(
                    f"missing {operand['owner']}-owned input {logical_name!r}"
                ) from exc
            prebuilt = (
                isinstance(value, torch.Tensor)
                and tuple(value.shape) == tuple(argument["shape"])
            )
            if prebuilt:
                raise GeneratedDecodeError(
                    f"generated decode address table {argument['name']!r} cannot "
                    "accept an opaque prebuilt table without pointee provenance"
                )
            rows = _address_table_rows(value, operand)
            expected_shape = tuple(argument["shape"])
            if len(expected_shape) != 1 or len(rows) != int(expected_shape[0]):
                raise GeneratedDecodeError(
                    f"generated decode address table {argument['name']!r} has "
                    f"{len(rows)} rows for compiler shape {expected_shape}")
            spec = ((len(rows),), torch.int64)
            # Binding rebuilds a private launch table from retained row
            # aliases so caller-side edits cannot redirect its pointers.
            specs.extend((spec, spec))
            continue
        if source not in {"runtime_extent", "stream"}:
            raise GeneratedDecodeError(
                f"unsupported generated decode argument source {source!r}"
            )
    return tuple(specs)


def estimate_binding_storage_bytes(
    descriptor: Mapping[str, Any],
    *,
    weights: Mapping[str, torch.Tensor],
    runtime_inputs: Mapping[str, Any],
) -> int:
    """Return allocator-owned tensor bytes for one binding invocation.

    One invocation owns a fresh workspace plus two copies of tape, counters,
    and each derived address table: the caller-visible assembly result and the
    private launch state rebuilt during ``GeneratedDecodeProgram.bind``.
    Caller-owned external tensor storage is not charged here; callers must sum
    this once per invocation without deduplicating pairs.
    """

    return sum(
        prod(shape) * torch.empty((), dtype=dtype, device="meta").element_size()
        for shape, dtype in _binding_storage_specs(
            descriptor,
            weights=weights,
            runtime_inputs=runtime_inputs,
        )
    )


def reserve_binding_storage(
    descriptor: Mapping[str, Any],
    *,
    weights: Mapping[str, torch.Tensor],
    runtime_inputs: Mapping[str, Any],
    device: torch.device | str,
    stream: Any,
) -> tuple[torch.Tensor, ...]:
    """Reserve the exact allocator shapes owned by one future binding.

    The returned tensors carry no launch contents. Keep one returned tuple alive
    per slot/program pair until immediately before ``assemble_bindings`` so the
    device allocator reserves the same size classes as the later allocations.
    CUDA reservations are allocated and recorded on ``stream``; an ambient
    default stream is never inferred.
    """

    target = torch.device(device)
    if target.type == "cuda" and target.index is None:
        target = torch.device("cuda", torch.cuda.current_device())
    allocation_stream = (
        _binding_torch_stream(stream, target) if target.type == "cuda" else None
    )
    context = (
        torch.cuda.stream(allocation_stream)
        if allocation_stream is not None else nullcontext()
    )
    with context:
        reservations = tuple(
            torch.empty(shape, dtype=dtype, device=target)
            for shape, dtype in _binding_storage_specs(
                descriptor,
                weights=weights,
                runtime_inputs=runtime_inputs,
            )
        )
    if allocation_stream is not None:
        for value in reservations:
            value.record_stream(allocation_stream)
    return reservations


def assemble_bindings(
    descriptor: Mapping[str, Any],
    *,
    weights: Mapping[str, torch.Tensor],
    runtime_inputs: Mapping[str, Any],
    runtime_extents: Mapping[str, int],
    stream: Any,
    device: torch.device,
) -> dict[str, Any]:
    """Assemble the compiler-emitted named launch ABI using torch storage."""

    target = torch.device(device)
    if target.type == "cuda" and target.index is None:
        target = torch.device("cuda", torch.cuda.current_device())
    allocation_stream = (
        _binding_torch_stream(stream, target) if target.type == "cuda" else None
    )
    arguments = _arguments(descriptor)
    tape_contract = (
        _validated_tape_contract(descriptor)
        if any(argument.get("source") == "tape" for argument in arguments)
        else None
    )
    operands = _validated_external_operands(descriptor, arguments)
    workspace_bindings = (
        _validated_workspace_bindings(descriptor, arguments)
        if any(argument.get("source") == "workspace" for argument in arguments)
        else {}
    )
    storage_extents = _storage_extent_capacities(descriptor, runtime_extents)
    extent_names = set(storage_extents)
    extent_names.update(_workspace_dynamic_scalars(workspace_bindings))
    extent_names.update(
        str(argument["name"])
        for argument in arguments
        if argument.get("source") == "runtime_extent"
    )
    extent_provenance = {}
    for name in extent_names:
        try:
            value = runtime_extents[name]
        except KeyError as exc:
            raise GeneratedDecodeError(
                f"missing runtime extent {name!r}"
            ) from exc
        if type(value) is not int or value <= 0:
            raise GeneratedDecodeError(
                f"runtime extent {name!r} has invalid value {value!r}")
        extent_provenance[name] = value
    bindings = _AssembledBindings(
        descriptor["device_program"],
        extent_provenance,
    )
    for argument in arguments:
        name = argument["name"]
        source = argument["source"]
        if source == "external":
            try:
                operand = operands[name]
            except KeyError as exc:
                raise GeneratedDecodeError(
                    f"generated decode external argument {name!r} has no physical "
                    "ABI") from exc
            _validate_external_operand_contract(argument, operand)
            logical_name = operand["logical_name"]
            owner = _external_operand_owner(
                operand,
                weights=weights,
                runtime_inputs=runtime_inputs,
            )
            try:
                value = owner[logical_name]
            except KeyError as exc:
                raise GeneratedDecodeError(
                    f"missing {operand['owner']}-owned input {logical_name!r}") from exc
            if operand["transport"] == "layer_address_table":
                prebuilt = (
                    isinstance(value, torch.Tensor)
                    and tuple(value.shape) == tuple(argument["shape"])
                )
                if prebuilt:
                    raise GeneratedDecodeError(
                        f"generated decode address table {name!r} cannot accept "
                        "an opaque prebuilt table without pointee provenance"
                    )
                ownership = _address_table(
                    value,
                    argument,
                    operand,
                    storage_extents,
                    device=target,
                    stream=allocation_stream,
                )
                bindings._address_tables[name] = ownership
                value = ownership.table
            elif operand["transport"] == "raw_pointer":
                if not isinstance(value, torch.Tensor):
                    raise GeneratedDecodeError(
                        f"generated decode raw pointer {name!r} is not a tensor")
                _validate_raw_pointer_storage(
                    argument,
                    operand,
                    value,
                    storage_extents,
                )
            bindings[name] = value
        elif source == "workspace":
            context = (
                torch.cuda.stream(allocation_stream)
                if allocation_stream is not None else nullcontext()
            )
            with context:
                bindings[name] = torch.empty(
                    _workspace_capacity_shape(
                        descriptor,
                        workspace_bindings[name],
                    ),
                    dtype=_TORCH_DTYPES[argument["dtype"]],
                    device=target,
                )
        elif source == "runtime_extent":
            try:
                value = runtime_extents[name]
            except KeyError as exc:
                raise GeneratedDecodeError(f"missing runtime extent {name!r}") from exc
            if type(value) is not int or value <= 0:
                raise GeneratedDecodeError(
                    f"runtime extent {name!r} has invalid value {value!r}")
            bindings[name] = value
        elif source == "tape":
            context = (
                torch.cuda.stream(allocation_stream)
                if allocation_stream is not None else nullcontext()
            )
            with context:
                bindings[name] = _tape_tensor(
                    descriptor,
                    argument,
                    device=target,
                    tape=tape_contract,
                )
        elif source == "counter":
            context = (
                torch.cuda.stream(allocation_stream)
                if allocation_stream is not None else nullcontext()
            )
            with context:
                bindings[name] = torch.zeros(
                    tuple(argument["shape"]),
                    dtype=_TORCH_DTYPES[argument["dtype"]],
                    device=target,
                )
        elif source == "stream":
            bindings[name] = stream
        else:
            raise GeneratedDecodeError(
                f"unsupported generated decode argument source {source!r}")
    bindings._seal()
    return bindings


def derive_runtime_extents(
    descriptor: Mapping[str, Any],
    runtime_inputs: Mapping[str, Any],
    *,
    active_batch: int,
) -> dict[str, int]:
    """Evaluate compiler-declared runtime extents from bound tensors."""

    if type(active_batch) is not int:
        raise GeneratedDecodeError(
            f"active batch has invalid value {active_batch!r}")
    minimum_batch = _runtime_extent_minimums(descriptor).get(
        "active_batch", 1)
    maximum_batch = _runtime_extent_maximums(descriptor).get(
        "active_batch", _descriptor_capacity(descriptor))
    if (
        active_batch < minimum_batch
        or active_batch > maximum_batch
    ):
        raise GeneratedDecodeError(
            f"active batch {active_batch} is outside artifact interval "
            f"[{minimum_batch}, {maximum_batch}]")
    values = {"active_batch": active_batch}
    for binding in descriptor["runtime"]["extents"]:
        name = str(binding["name"])
        kind = str(binding["kind"])
        if kind == "batch_size":
            values[name] = active_batch
            continue
        try:
            source = runtime_inputs[str(binding["source"])]
        except KeyError as exc:
            raise GeneratedDecodeError(
                f"runtime extent {name!r} needs input {binding.get('source')!r}") from exc
        if kind == "tensor_axis":
            values[name] = int(source.shape[int(binding["axis"])])
        elif kind == "tensor_collection_axis":
            if isinstance(source, torch.Tensor):
                # A layer-scoped runtime operand may lower to one contiguous
                # ``[layers, *item_shape]`` raw pointer rather than an address
                # table. The compiler's collection axis is item-relative, so
                # account for the leading layer dimension.
                axis = int(binding["axis"]) + 1
                if axis >= source.ndim or int(source.shape[0]) <= 0:
                    raise GeneratedDecodeError(
                        f"runtime extent {name!r} has malformed stacked collection "
                        f"shape {tuple(source.shape)}")
                extents = {int(source.shape[axis])}
            else:
                try:
                    tensors = tuple(value for value in source if value is not None)
                except TypeError as exc:
                    raise GeneratedDecodeError(
                        f"runtime extent {name!r} needs a tensor collection") from exc
                if not tensors:
                    raise GeneratedDecodeError(
                        f"runtime extent {name!r} has no present source tensor")
                axis = int(binding["axis"])
                extents = {int(tensor.shape[axis]) for tensor in tensors}
            if len(extents) != 1:
                raise GeneratedDecodeError(
                    f"runtime extent {name!r} has inconsistent collection "
                    f"dimensions {sorted(extents)!r}")
            values[name] = extents.pop()
        elif kind == "tensor_reduction":
            prefix = int(values[str(binding["prefix_extent"])])
            selected = source[:prefix]
            reduction = str(binding["reduction"])
            if reduction == "max":
                reduced = int(selected.max().item())
            elif reduction == "min":
                reduced = int(selected.min().item())
            elif reduction == "sum":
                reduced = int(selected.sum().item())
            else:
                raise GeneratedDecodeError(
                    f"runtime extent {name!r} has unknown reduction {reduction!r}")
            values[name] = reduced + int(binding.get("offset", 0))
        else:
            raise GeneratedDecodeError(
                f"runtime extent {name!r} has unknown kind {kind!r}")
    for name, minimum in _runtime_extent_minimums(descriptor).items():
        if name in values and int(values[name]) < minimum:
            raise GeneratedDecodeError(
                f"runtime extent {name!r}={values[name]} is below artifact "
                f"minimum {minimum}")
    for name, maximum in _runtime_extent_maximums(descriptor).items():
        if name in values and int(values[name]) > maximum:
            raise GeneratedDecodeError(
                f"runtime extent {name!r}={values[name]} exceeds artifact "
                f"maximum {maximum}")
    return values


def _arguments(descriptor: Mapping[str, Any]) -> tuple[dict, ...]:
    try:
        values = descriptor["device_program"]["argument_plan"]["arguments"]
    except (KeyError, TypeError) as exc:
        raise GeneratedDecodeError("generated decode descriptor has no argument plan") from exc
    if not isinstance(values, (list, tuple)) or any(
        not isinstance(value, Mapping) for value in values
    ):
        raise GeneratedDecodeError(
            "generated decode descriptor has a malformed argument plan")
    arguments = tuple(dict(value) for value in values)
    names = tuple(argument.get("name") for argument in arguments)
    if (
        any(not isinstance(name, str) or not name for name in names)
        or len(names) != len(set(names))
    ):
        raise GeneratedDecodeError(
            "generated decode argument plan has malformed or duplicate names")
    return arguments


_PACKED_ARGUMENT_KIND_BY_TRANSPORT = {
    "tensor": "memref",
    "layer_address_table": "memref",
    "raw_pointer": "memref",
    "scalar": "scalar",
    "stream": "stream",
}


def _expected_packed_argument_abi(
    descriptor: Mapping[str, Any],
) -> tuple[dict[str, str], ...]:
    """Derive the compiler's named C-wrapper ABI from its serialized plan."""

    result = []
    symbols = set()
    for argument in _arguments(descriptor):
        name = argument["name"]
        symbol = "m_" + re.sub(r"[^0-9A-Za-z_]", "_", name)
        transport = argument.get("transport")
        try:
            kind = _PACKED_ARGUMENT_KIND_BY_TRANSPORT[transport]
        except (KeyError, TypeError) as exc:
            raise GeneratedDecodeError(
                f"generated decode argument {name!r} has unsupported packed "
                f"transport {transport!r}"
            ) from exc
        if not symbol.isidentifier() or symbol in symbols:
            raise GeneratedDecodeError(
                "generated decode argument names do not form a unique packed ABI"
            )
        symbols.add(symbol)
        result.append({"name": symbol, "kind": kind})
    return tuple(result)


def _packed_argument_abi(
    metadata: Mapping[str, Any],
    descriptor: Mapping[str, Any],
) -> tuple[dict[str, str], ...]:
    """Require the packed wrapper's exact ordered name/kind ABI."""

    expected = _expected_packed_argument_abi(descriptor)
    raw = metadata.get("arg_abi")
    if not isinstance(raw, list) or len(raw) != len(expected):
        raise GeneratedDecodeError(
            "packed generated decode argument ABI disagrees with its runtime "
            "descriptor"
        )
    values = []
    for actual, wanted in zip(raw, expected, strict=True):
        if (
            not isinstance(actual, Mapping)
            or set(actual) != {"name", "kind"}
            or type(actual.get("name")) is not str
            or type(actual.get("kind")) is not str
            or not _same_json_identity(actual, wanted)
        ):
            raise GeneratedDecodeError(
                "packed generated decode argument ABI disagrees with its runtime "
                "descriptor"
            )
        values.append({"name": actual["name"], "kind": actual["kind"]})
    return tuple(values)


def _packed_symbol_map(
    raw_symbols: Any,
    inventory_variant_key: Any,
) -> dict[str, str]:
    """Require symbols derived from the packer's stable inventory identity."""

    if type(inventory_variant_key) is not str or not inventory_variant_key:
        raise GeneratedDecodeError(
            "packed generated decode inventory variant key is malformed"
        )
    expected = {
        "cuda_init": f"_mlir_{inventory_variant_key}_cuda_init",
        "cuda_load_to_device": (
            f"_mlir_{inventory_variant_key}_cuda_load_to_device"
        ),
        "ciface_prefix": (
            f"_mlir_{inventory_variant_key}__mlir_ciface_"
        ),
    }
    if (
        not isinstance(raw_symbols, Mapping)
        or set(raw_symbols) != set(expected)
        or any(type(value) is not str for value in raw_symbols.values())
        or not _same_json_identity(raw_symbols, expected)
    ):
        raise GeneratedDecodeError(
            "packed generated decode wrapper symbols disagree with its "
            "variant identity"
        )
    return expected


def _packed_memref_abi(
    raw_abi: Any,
    descriptor: Mapping[str, Any],
) -> tuple[str, ...]:
    """Require the exact redundant memref-name projection of the wrapper ABI."""

    expected = tuple(
        entry["name"]
        for entry in _expected_packed_argument_abi(descriptor)
        if entry["kind"] == "memref"
    )
    if (
        type(raw_abi) is not list
        or any(type(name) is not str for name in raw_abi)
        or tuple(raw_abi) != expected
    ):
        raise GeneratedDecodeError(
            "packed generated decode memref names disagree with its runtime "
            "descriptor"
        )
    return expected


def _packed_memref_specs(
    raw_specs: Any,
    descriptor: Mapping[str, Any],
) -> tuple[dict[str, list[int]], ...]:
    """Validate the packed wrapper's exact compiler-derived memref masks."""

    expected = []
    for argument in _arguments(descriptor):
        if argument.get("transport") not in {
            "tensor",
            "layer_address_table",
            "raw_pointer",
        }:
            continue
        shape = argument.get("shape")
        if not isinstance(shape, (list, tuple)) or any(
            isinstance(dim, bool) or not isinstance(dim, int) or dim <= 0
            for dim in shape
        ):
            raise GeneratedDecodeError(
                "packed generated decode descriptor has malformed memref shape"
            )
        rank = len(shape)
        dynamic_axes = frozenset(_dynamic_stride_axes(argument, rank))
        expected.append({
            "shape_mask": [0] * rank,
            "stride_mask": [
                int(axis in dynamic_axes) for axis in range(rank)
            ],
        })

    if not isinstance(raw_specs, (list, tuple)) or len(raw_specs) != len(expected):
        raise GeneratedDecodeError(
            "packed generated decode memref ABI disagrees with its runtime "
            "descriptor"
        )
    values = []
    for raw, wanted in zip(raw_specs, expected, strict=True):
        if isinstance(raw, Mapping):
            if set(raw) != {"shape_mask", "stride_mask"}:
                raise GeneratedDecodeError(
                    "packed generated decode memref ABI is malformed"
                )
            shape_mask = raw.get("shape_mask")
            stride_mask = raw.get("stride_mask")
        else:
            shape_mask = getattr(raw, "shape_mask", None)
            stride_mask = getattr(raw, "stride_mask", None)
        if (
            not isinstance(shape_mask, (list, tuple))
            or not isinstance(stride_mask, (list, tuple))
            or any(type(value) is not int or value not in {0, 1} for value in shape_mask)
            or any(type(value) is not int or value not in {0, 1} for value in stride_mask)
        ):
            raise GeneratedDecodeError(
                "packed generated decode memref ABI is malformed"
            )
        value = {
            "shape_mask": list(shape_mask),
            "stride_mask": list(stride_mask),
        }
        if value != wanted:
            raise GeneratedDecodeError(
                "packed generated decode memref ABI disagrees with its runtime "
                "descriptor"
            )
        values.append(value)
    return tuple(values)


def _packed_wrapper_abi(
    bundle: Any,
    metadata: Mapping[str, Any],
    descriptor: Mapping[str, Any],
    inventory_variant_key: Any,
) -> tuple[dict[str, str], ...]:
    """Validate every runtime-consumed packed-wrapper ABI projection."""

    packed_arg_abi = _packed_argument_abi(metadata, descriptor)
    _packed_memref_abi(metadata.get("memref_abi"), descriptor)
    bundle_kinds = getattr(bundle, "arg_kinds", None)
    if (
        not isinstance(bundle_kinds, (list, tuple))
        or tuple(bundle_kinds)
        != tuple(argument["kind"] for argument in packed_arg_abi)
    ):
        raise GeneratedDecodeError(
            "packed generated decode wrapper argument kinds disagree with its "
            "exact argument ABI"
        )
    bundle_aot = getattr(bundle, "aot", None)
    _packed_symbol_map(
        getattr(bundle_aot, "_symbols", None),
        inventory_variant_key,
    )
    _packed_memref_specs(getattr(bundle, "memref_specs", None), descriptor)
    return packed_arg_abi


def _pack_scalar_value(dtype: Any, value: Any, *, name: str) -> Any:
    try:
        scalar_type = _SCALAR_TYPES[dtype]
    except (KeyError, TypeError) as exc:
        raise GeneratedDecodeError(
            f"generated decode scalar {name!r} has unsupported dtype {dtype!r}"
        ) from exc
    if dtype in {"int32", "int64"}:
        if type(value) is not int:
            raise GeneratedDecodeError(
                f"generated decode scalar {name!r} needs an exact integer"
            )
        bits = ctypes.sizeof(scalar_type) * 8
        lower = -(1 << (bits - 1))
        upper = (1 << (bits - 1)) - 1
        if not lower <= value <= upper:
            raise GeneratedDecodeError(
                f"generated decode scalar {name!r}={value} is outside its "
                f"signed {bits}-bit ABI"
            )
    elif dtype == "fp32":
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise GeneratedDecodeError(
                f"generated decode scalar {name!r} needs a finite number"
            )
        try:
            value = float(value)
        except (OverflowError, TypeError, ValueError) as exc:
            raise GeneratedDecodeError(
                f"generated decode scalar {name!r} needs a finite number"
            ) from exc
        if not isfinite(value):
            raise GeneratedDecodeError(
                f"generated decode scalar {name!r} needs a finite number"
            )
    try:
        packed = scalar_type(value)
    except (OverflowError, TypeError, ValueError) as exc:
        raise GeneratedDecodeError(
            f"generated decode scalar {name!r} is malformed") from exc
    if dtype == "fp32" and not isfinite(float(packed.value)):
        raise GeneratedDecodeError(
            f"generated decode scalar {name!r} overflows its fp32 ABI")
    return packed


def _validate_tensor_storage_span(value: torch.Tensor, *, label: str) -> None:
    shape = tuple(int(dim) for dim in value.shape)
    strides = tuple(int(stride) for stride in value.stride())
    offset = int(value.storage_offset())
    if (
        value.layout != torch.strided
        or any(dim <= 0 for dim in shape)
        or any(stride < 0 for stride in strides)
        or offset < 0
    ):
        raise GeneratedDecodeError(
            f"generated decode {label} has an invalid storage view")
    final_element = offset + sum(
        (dim - 1) * stride for dim, stride in zip(shape, strides, strict=True)
    )
    required_bytes = (final_element + 1) * int(value.element_size())
    available_bytes = int(value.untyped_storage().nbytes())
    if required_bytes > available_bytes:
        raise GeneratedDecodeError(
            f"generated decode {label} needs {required_bytes} storage bytes, "
            f"but its allocation has {available_bytes}")


def _validate_workspace_storage(
    descriptor: Mapping[str, Any],
    argument: Mapping[str, Any],
    binding: Mapping[str, Any],
    value: torch.Tensor,
) -> None:
    name = str(argument["name"])
    try:
        dtype = _TORCH_DTYPES[binding["dtype"]]
    except (KeyError, TypeError) as exc:
        raise GeneratedDecodeError(
            f"generated decode workspace {name!r} has an invalid dtype") from exc
    expected_shape = _workspace_capacity_shape(descriptor, binding)
    actual_shape = tuple(int(dim) for dim in value.shape)
    if value.dtype != dtype or actual_shape != expected_shape:
        raise GeneratedDecodeError(
            f"generated decode workspace {name!r} expects {dtype} storage "
            f"shape {expected_shape}, got {value.dtype} {actual_shape}")
    expected_strides = _contiguous_strides(expected_shape)
    actual_strides = tuple(int(stride) for stride in value.stride())
    if actual_strides != expected_strides:
        raise GeneratedDecodeError(
            f"generated decode workspace {name!r} expects contiguous storage "
            f"strides {expected_strides}, got {actual_strides}")
    _validate_tensor_storage_span(value, label=f"workspace {name!r}")


def _validate_tensor_binding(
    argument: Mapping[str, Any],
    value: torch.Tensor,
) -> tuple[int, ...]:
    """Fail closed when a live tensor disagrees with the compiler-owned ABI."""

    name = str(argument.get("name", "<unnamed>"))
    dtype = argument.get("dtype")
    if not isinstance(dtype, str):
        raise GeneratedDecodeError(
            f"generated decode tensor {name!r} has an invalid dtype contract"
        )
    try:
        expected_dtype = _TORCH_DTYPES[dtype]
    except KeyError as exc:
        raise GeneratedDecodeError(
            f"generated decode tensor {name!r} has an invalid dtype contract"
        ) from exc
    if value.dtype != expected_dtype:
        raise GeneratedDecodeError(
            f"generated decode tensor {name!r} expects dtype {expected_dtype}, "
            f"got {value.dtype}"
        )

    shape = argument.get("shape")
    if (
        not isinstance(shape, (list, tuple))
        or any(
            isinstance(dim, bool) or not isinstance(dim, int) or dim <= 0
            for dim in shape
        )
    ):
        raise GeneratedDecodeError(
            f"generated decode tensor {name!r} has an invalid shape contract"
        )
    expected_shape = tuple(shape)
    _validate_tensor_storage_span(value, label=f"tensor {name!r}")
    transport = argument.get("transport")
    if transport == "raw_pointer":
        return expected_shape
    if transport not in {"tensor", "layer_address_table"}:
        raise GeneratedDecodeError(
            f"generated decode tensor {name!r} has an invalid transport contract"
        )
    actual_shape = tuple(int(dim) for dim in value.shape)
    if actual_shape != expected_shape:
        raise GeneratedDecodeError(
            f"generated decode tensor {name!r} expects shape {expected_shape}, "
            f"got {actual_shape}"
        )
    return expected_shape


def _contiguous_strides(shape: Sequence[int]) -> tuple[int, ...]:
    strides = []
    elements = 1
    for extent in reversed(tuple(int(value) for value in shape)):
        strides.append(elements)
        elements *= extent
    return tuple(reversed(strides))


def _dynamic_stride_axes(
    argument: Mapping[str, Any],
    rank: int,
) -> tuple[int, ...]:
    name = str(argument.get("name", "<unnamed>"))
    axes = argument.get("dynamic_stride_axes", ())
    if (
        not isinstance(axes, (list, tuple))
        or any(
            isinstance(axis, bool)
            or not isinstance(axis, int)
            or not 0 <= axis < rank
            for axis in axes
        )
        or len(axes) != len(set(axes))
        or (axes and argument.get("transport") != "tensor")
    ):
        raise GeneratedDecodeError(
            f"generated decode tensor {name!r} has invalid dynamic stride axes"
        )
    return tuple(axes)


def _validate_memref_contract(
    argument: Mapping[str, Any],
    spec: Any,
    value: torch.Tensor,
) -> None:
    """Refuse tensors the fake-argument AOT memref ABI cannot represent."""

    name = str(argument.get("name", "<unnamed>"))
    expected_shape = tuple(int(dim) for dim in argument["shape"])
    rank = len(expected_shape)
    dynamic_axes = frozenset(_dynamic_stride_axes(argument, rank))
    expected_shape_mask = (0,) * rank
    expected_stride_mask = tuple(
        int(axis in dynamic_axes) for axis in range(rank)
    )
    try:
        shape_mask = tuple(spec.shape_mask)
        stride_mask = tuple(spec.stride_mask)
    except (AttributeError, TypeError) as exc:
        raise GeneratedDecodeError(
            f"generated decode memref {name!r} has a malformed mask contract"
        ) from exc
    if (
        shape_mask != expected_shape_mask
        or stride_mask != expected_stride_mask
    ):
        raise GeneratedDecodeError(
            f"generated decode memref {name!r} encodes shape/stride masks "
            f"{shape_mask}/{stride_mask}, but the compiler ABI requires "
            f"{expected_shape_mask}/{expected_stride_mask}"
        )

    actual_shape = tuple(int(dim) for dim in value.shape)
    if actual_shape != expected_shape:
        raise GeneratedDecodeError(
            f"generated decode memref {name!r} expects shape {expected_shape}, "
            f"got {actual_shape}"
        )
    actual_stride = tuple(int(dim) for dim in value.stride())
    expected_stride = _contiguous_strides(expected_shape)
    mismatches = tuple(
        axis
        for axis, (actual, expected) in enumerate(
            zip(actual_stride, expected_stride, strict=True)
        )
        if axis not in dynamic_axes and actual != expected
    )
    if mismatches:
        raise GeneratedDecodeError(
            f"generated decode memref {name!r} has static stride "
            f"{actual_stride}, but its compiled contiguous stride is "
            f"{expected_stride}; mismatched axes={mismatches}"
        )


def _tensor_binding_identity(value: torch.Tensor) -> tuple[Any, ...]:
    """Snapshot the full tensor ABI while a memref is being packed."""

    storage = value.untyped_storage()
    device = value.device
    return (
        int(value.data_ptr()),
        int(storage.nbytes()),
        int(value.storage_offset()),
        tuple(int(dim) for dim in value.shape),
        tuple(int(dim) for dim in value.stride()),
        value.dtype,
        value.layout,
        device.type,
        device.index,
    )


def _tensor_identity_transaction(
    value: torch.Tensor,
    *,
    label: str,
    validator: Callable[[], Any],
) -> tuple[Any, ...]:
    """Validate one caller-reachable tensor without blessing a concurrent edit."""

    before = _tensor_binding_identity(value)
    validator()
    after = _tensor_binding_identity(value)
    if after != before:
        raise GeneratedDecodeError(
            f"generated decode {label} changed while its binding was validated"
        )
    return after


def _require_tensor_snapshot_authority(
    values: Sequence[torch.Tensor],
    snapshots: Any,
    *,
    label: str,
) -> tuple[tuple[Any, ...], ...]:
    """Require live tensors to match an earlier validated handoff exactly."""

    if not isinstance(snapshots, (list, tuple)) or any(
        not isinstance(snapshot, tuple) for snapshot in snapshots
    ):
        raise GeneratedDecodeError(
            f"generated decode {label} has malformed binding authority"
        )
    expected = tuple(snapshots)
    actual = tuple(_tensor_binding_identity(value) for value in values)
    if len(expected) != len(values) or actual != expected:
        raise GeneratedDecodeError(
            f"generated decode {label} changed during binding handoff"
        )
    return expected


def _adopt_tensor_authority(
    values: Sequence[torch.Tensor],
    authority: Sequence[tuple[Any, ...]],
    *,
    label: str,
) -> tuple[tuple[Any, ...], ...]:
    """Adopt exact earlier authority around one final storage-span check."""

    snapshots = _require_tensor_snapshot_authority(
        values,
        authority,
        label=label,
    )
    for index, value in enumerate(values):
        _validate_tensor_storage_span(value, label=f"{label} {index}")
    return _require_tensor_snapshot_authority(
        values,
        snapshots,
        label=label,
    )


def _binding_authority_capability():
    """Create the Python-private Program.bind-to-Bound authority handoff."""

    nonce = object()

    def issue(tensor_snapshots, pointee_snapshots, capacity_snapshots):
        return (
            nonce,
            tuple(tensor_snapshots),
            tuple(pointee_snapshots),
            tuple(capacity_snapshots),
        )

    def unpack(authority):
        if (
            not isinstance(authority, tuple)
            or len(authority) != 4
            or authority[0] is not nonce
        ):
            raise GeneratedDecodeError(
                "BoundGeneratedDecode must be constructed by "
                "GeneratedDecodeProgram.bind"
            )
        return authority[1:]

    return issue, unpack


(
    _issue_bound_binding_authority,
    _unpack_bound_binding_authority,
) = _binding_authority_capability()


@dataclass(frozen=True)
class _StorageGuard:
    """One caller-reachable allocation checked once regardless of view count."""

    storage: Any
    data_ptr: int
    nbytes: int
    labels: tuple[str, ...]

    def validate(self) -> None:
        if (
            int(self.storage.data_ptr()) != self.data_ptr
            or int(self.storage.nbytes()) != self.nbytes
        ):
            raise GeneratedDecodeError(
                "generated decode caller-owned storage changed allocation after "
                f"binding: {', '.join(self.labels)}")


def _storage_guards(
    values: Sequence[tuple[str, torch.Tensor]],
) -> tuple[_StorageGuard, ...]:
    grouped: dict[tuple[str, int], tuple[Any, list[str]]] = {}
    for label, value in values:
        storage = value.untyped_storage()
        key = (str(value.device), int(storage._cdata))
        if key not in grouped:
            grouped[key] = (storage, [])
        grouped[key][1].append(label)
    return tuple(
        _StorageGuard(
            storage=storage,
            data_ptr=int(storage.data_ptr()),
            nbytes=int(storage.nbytes()),
            labels=tuple(labels),
        )
        for storage, labels in grouped.values()
    )


def _host_reset_counter_names(descriptor: Mapping[str, Any]) -> tuple[str, ...]:
    counters = tuple(
        argument for argument in _arguments(descriptor)
        if argument.get("source") == "counter"
    )
    if not counters:
        return ()
    if len(counters) != 1:
        raise GeneratedDecodeError("generated decode has multiple counter buffers")
    try:
        num_counters = descriptor[
            "device_program"
        ]["synchronization_plan"]["num_counters"]
        raw_shape = counters[0]["shape"]
    except (KeyError, TypeError) as exc:
        raise GeneratedDecodeError(
            "generated decode has a malformed counter reset ABI"
        ) from exc
    if (
        type(num_counters) is not int
        or num_counters < 0
        or not isinstance(raw_shape, (list, tuple))
        or any(type(dim) is not int or dim <= 0 for dim in raw_shape)
    ):
        raise GeneratedDecodeError(
            "generated decode has a malformed counter reset ABI"
        )
    shape = tuple(raw_shape)
    if shape == (num_counters,):
        return (str(counters[0]["name"]),)
    if shape == (num_counters + 2,):
        return ()
    raise GeneratedDecodeError(
        f"generated counter storage has an unknown reset ABI: {shape}"
    )


def _packed_argument_alignments(
    signature: Mapping[str, Any],
    descriptor: Mapping[str, Any],
    arch: str,
) -> tuple[dict, ...]:
    """Validate the target-bound alignment contract beside a packed wrapper."""

    base_fields = {
        "schema_version",
        "device_program",
        "implementation_sha256",
        "source_sha256",
    }
    schema_version = signature.get("schema_version")
    if (
        isinstance(schema_version, bool)
        or not isinstance(schema_version, int)
    ):
        raise GeneratedDecodeError(
            "packed generated decode signature has non-integer schema version")
    alignment_schema = schema_version
    packed_signature = schema_version in {6, 7}
    if schema_version in {4, 5, 6, 7}:
        base_fields.add("runtime_descriptor_sha256")
        if packed_signature:
            base_fields.remove("device_program")
        alignment_schema -= 4 if packed_signature else 2
    target_arch = _normalized_cuda_arch(
        arch,
        contract="packed artifact target",
    )
    try:
        arguments = tuple(
            argument for argument in _arguments(descriptor)
            if argument.get("transport") in {
                "tensor", "layer_address_table", "raw_pointer",
            }
        )
    except GeneratedDecodeError:
        if (
            alignment_schema == 2
            and set(signature) == base_fields
            and descriptor.get("argument_alignments") is None
        ):
            return ()
        raise
    expected = []
    strengthened = False
    for argument in arguments:
        name = argument.get("name")
        planned = argument.get("assumed_align")
        if (
            not isinstance(name, str)
            or not name
            or isinstance(planned, bool)
            or not isinstance(planned, int)
            or planned <= 0
            or planned & (planned - 1)
        ):
            raise GeneratedDecodeError(
                "packed generated decode descriptor has malformed argument "
                "alignment")
        effective = (
            max(planned, 8)
            if target_arch == "sm100" and name == "instruction_tape"
            else planned
        )
        expected.append({"name": name, "assumed_align": effective})
        strengthened |= effective != planned
    if alignment_schema == 2:
        if set(signature) != base_fields:
            raise GeneratedDecodeError(
                "packed generated decode schema-v2 signature has invalid fields")
        if descriptor.get("argument_alignments") is not None:
            raise GeneratedDecodeError(
                "schema-v2 generated decode descriptor has argument alignments")
        if strengthened:
            raise GeneratedDecodeError(
                "sm100 generated decode instruction tape lacks its strengthened "
                "alignment contract")
        return ()
    if alignment_schema != 3:
        raise GeneratedDecodeError(
            "packed generated decode signature has unsupported schema version")
    if set(signature) != base_fields | {"argument_alignments"}:
        raise GeneratedDecodeError(
            "packed generated decode schema-v3 signature has invalid fields")
    raw = signature.get("argument_alignments")
    if not isinstance(raw, list) or not raw:
        raise GeneratedDecodeError(
            "packed generated decode schema-v3 signature has no argument alignments")
    if len(raw) != len(expected):
        raise GeneratedDecodeError(
            "packed generated decode argument alignment order disagrees with "
            "the runtime descriptor")
    values = []
    for expected_entry, entry in zip(expected, raw, strict=True):
        if (
            not isinstance(entry, Mapping)
            or set(entry) != {"name", "assumed_align"}
            or type(entry.get("name")) is not str
            or entry.get("name") != expected_entry["name"]
            or isinstance(entry.get("assumed_align"), bool)
            or not isinstance(entry.get("assumed_align"), int)
            or int(entry["assumed_align"]) & (int(entry["assumed_align"]) - 1)
        ):
            raise GeneratedDecodeError(
                "packed generated decode argument alignment contract is malformed")
        values.append({
            "name": str(entry["name"]),
            "assumed_align": int(entry["assumed_align"]),
        })
    if values != expected:
        raise GeneratedDecodeError(
            "packed generated decode argument alignments do not match the "
            "target-derived contract")
    if not strengthened:
        raise GeneratedDecodeError(
            "schema-v3 generated decode alignment contract strengthens no argument")
    descriptor_rows = descriptor.get("argument_alignments")
    if not isinstance(descriptor_rows, list) or len(descriptor_rows) != len(expected):
        raise GeneratedDecodeError(
            "packed generated decode runtime descriptor does not match the "
            "target-derived argument alignments")
    descriptor_values = []
    for expected_entry, entry in zip(expected, descriptor_rows, strict=True):
        if (
            not isinstance(entry, Mapping)
            or set(entry) != {"name", "assumed_align"}
            or type(entry.get("name")) is not str
            or entry.get("name") != expected_entry["name"]
            or type(entry.get("assumed_align")) is not int
        ):
            raise GeneratedDecodeError(
                "packed generated decode runtime descriptor does not match the "
                "target-derived argument alignments")
        descriptor_values.append({
            "name": entry["name"],
            "assumed_align": entry["assumed_align"],
        })
    if descriptor_values != expected:
        raise GeneratedDecodeError(
            "packed generated decode runtime descriptor does not match the "
            "target-derived argument alignments")
    return tuple(values)


def _shape_environment(descriptor: Mapping[str, Any], name: str) -> int | None:
    device_program = descriptor.get("device_program", {})
    if not isinstance(device_program, Mapping):
        raise GeneratedDecodeError(
            "generated decode descriptor has a malformed device program")
    values = device_program.get("shape_env", {})
    if not isinstance(values, Mapping):
        raise GeneratedDecodeError(
            "generated decode descriptor has a malformed shape environment")
    raw = values.get(name)
    if raw is None:
        return None
    if type(raw) is not int or raw <= 0:
        raise GeneratedDecodeError(
            f"generated decode shape extent {name!r} is invalid: {raw!r}")
    return raw


def _descriptor_capacity(descriptor: Mapping[str, Any]) -> int:
    value = descriptor.get("capacity")
    if type(value) is not int or value <= 0:
        raise GeneratedDecodeError(
            f"generated decode descriptor capacity is invalid: {value!r}")
    return value


def _descriptor_num_ctas(descriptor: Mapping[str, Any]) -> int:
    value = descriptor.get("num_ctas")
    if type(value) is not int or value <= 0:
        raise GeneratedDecodeError(
            f"generated decode descriptor num_ctas is invalid: {value!r}")
    return value


def _validate_descriptor_emitted_grid(
    descriptor: Mapping[str, Any],
) -> int:
    """Require the runtime grid to equal the emitted device-program grid."""

    device_program = descriptor.get("device_program")
    shape_env = (
        device_program.get("shape_env")
        if isinstance(device_program, Mapping)
        else None
    )
    emitted_num_ctas = (
        shape_env.get("num_ctas") if isinstance(shape_env, Mapping) else None
    )
    descriptor_num_ctas = _descriptor_num_ctas(descriptor)
    if (
        type(emitted_num_ctas) is not int
        or emitted_num_ctas <= 0
        or emitted_num_ctas != descriptor_num_ctas
    ):
        raise GeneratedDecodeError(
            "packed generated decode emitted grid disagrees with its runtime "
            "descriptor"
        )
    return descriptor_num_ctas


def _emitted_dynamic_smem_bytes(descriptor: Mapping[str, Any]) -> int:
    """Read the SharedStorage footprint that the generated launch emits."""

    device_program = descriptor.get("device_program")
    resource_plan = (
        device_program.get("resource_plan")
        if isinstance(device_program, Mapping) else None
    )
    geometry = (
        resource_plan.get("lease_geometry")
        if isinstance(resource_plan, Mapping) else None
    )
    value = geometry.get("smem_used") if isinstance(geometry, Mapping) else None
    if type(value) is not int or value < 0:
        raise GeneratedDecodeError(
            "generated decode descriptor has no exact emitted dynamic shared-"
            "memory footprint"
        )
    return value


def _strict_runtime_projection_map(
    value: Any,
    *,
    contract: str,
    minimum: int,
) -> dict[str, int]:
    if not isinstance(value, Mapping):
        raise GeneratedDecodeError(
            f"generated decode descriptor has malformed {contract}"
        )
    result = {}
    for name, extent in value.items():
        if (
            type(name) is not str
            or not name
            or type(extent) is not int
            or extent < minimum
        ):
            raise GeneratedDecodeError(
                f"generated decode descriptor has invalid {contract}"
            )
        result[name] = extent
    return result


def _validate_descriptor_runtime_projection(
    descriptor: Mapping[str, Any],
) -> None:
    """Prove runtime selection fields are exact compiler projections."""

    required = {
        "capacity",
        "static_extent_bindings",
        "runtime_extent_minimums",
    }
    missing = required - set(descriptor)
    if missing:
        raise GeneratedDecodeError(
            "generated decode packed descriptor lacks exact runtime projection "
            f"fields {sorted(missing)}"
        )
    device_program = descriptor.get("device_program")
    if not isinstance(device_program, Mapping):
        raise GeneratedDecodeError(
            "generated decode descriptor has a malformed device program"
        )
    shape_env = device_program.get("shape_env")
    if not isinstance(shape_env, Mapping):
        raise GeneratedDecodeError(
            "generated decode descriptor has a malformed shape environment"
        )
    capacity = _descriptor_capacity(descriptor)
    emitted_capacity = shape_env.get("active_batch")
    if type(emitted_capacity) is not int or emitted_capacity <= 0:
        raise GeneratedDecodeError(
            "generated decode device program has no exact positive "
            "active_batch capacity"
        )
    if emitted_capacity != capacity:
        raise GeneratedDecodeError(
            "generated decode runtime capacity disagrees with device-program "
            f"active_batch: runtime={capacity}, device_program={emitted_capacity}"
        )

    runtime_static = _strict_runtime_projection_map(
        descriptor["static_extent_bindings"],
        contract="runtime static extent projection",
        minimum=1,
    )
    device_static = _strict_runtime_projection_map(
        device_program.get("static_runtime_extents", {}),
        contract="device-program static extent projection",
        minimum=1,
    )
    if not _same_json_identity(runtime_static, device_static):
        raise GeneratedDecodeError(
            "generated decode runtime static extents disagree with the device "
            "program"
        )

    runtime_minimums = _strict_runtime_projection_map(
        descriptor["runtime_extent_minimums"],
        contract="runtime extent-minimum projection",
        minimum=2,
    )
    device_minimums = _strict_runtime_projection_map(
        device_program.get("runtime_extent_minimums", {}),
        contract="device-program extent-minimum projection",
        minimum=2,
    )
    if not _same_json_identity(runtime_minimums, device_minimums):
        raise GeneratedDecodeError(
            "generated decode runtime extent minimums disagree with the device "
            "program"
        )
    runtime_maximums = _strict_runtime_projection_map(
        descriptor.get("runtime_extent_maximums", {}),
        contract="runtime extent-maximum projection",
        minimum=1,
    )
    device_maximums = _strict_runtime_projection_map(
        device_program.get("runtime_extent_maximums", {}),
        contract="device-program extent-maximum projection",
        minimum=1,
    )
    if not _same_json_identity(runtime_maximums, device_maximums):
        raise GeneratedDecodeError(
            "generated decode runtime extent maximums disagree with the device "
            "program"
        )


def _validate_live_artifact_target(
    descriptor: Mapping[str, Any],
    receipt: Mapping[str, Any],
    *,
    device_index: int,
    device_properties: Any,
) -> None:
    """Match packed target metadata to exact live CUDA launch authority."""

    expected_arch = _normalized_cuda_arch(
        receipt.get("architecture"),
        contract="artifact receipt",
    )
    live_arch = _live_cuda_arch(device_index)
    if expected_arch != live_arch:
        raise GeneratedDecodeError(
            "generated decode artifact architecture disagrees with the live "
            f"device: artifact={expected_arch!r}, device={live_arch!r}"
        )
    smem_cap = getattr(
        device_properties, "shared_memory_per_block_optin", None,
    )
    if type(smem_cap) is not int or smem_cap <= 0:
        raise GeneratedDecodeError(
            "generated decode live device has no positive opt-in dynamic "
            "shared-memory cap"
        )
    emitted_smem = _emitted_dynamic_smem_bytes(descriptor)
    if emitted_smem > smem_cap:
        raise GeneratedDecodeError(
            "generated decode emitted dynamic shared memory exceeds the live "
            f"device cap: emitted={emitted_smem}, cap={smem_cap}"
        )


def _static_extent_bindings(descriptor: Mapping[str, Any]) -> dict[str, int]:
    """Read an artifact's compiler-owned static domain, including old bundles."""

    values = descriptor.get("static_extent_bindings")
    if values is None:
        device_program = descriptor.get("device_program", {})
        if isinstance(device_program, Mapping):
            values = device_program.get("static_runtime_extents", {})
    if not isinstance(values, Mapping):
        raise GeneratedDecodeError(
            "generated decode descriptor has malformed static extent bindings")
    result = {}
    for name, value in values.items():
        if (
            not isinstance(name, str)
            or not name
            or type(value) is not int
            or value <= 0
        ):
            raise GeneratedDecodeError(
                "generated decode descriptor has invalid static extent bindings")
        result[name] = value
    return result


def _runtime_extent_minimums(
    descriptor: Mapping[str, Any],
) -> dict[str, int]:
    """Read explicit runtime lower bounds, defaulting old bundles to one."""

    values = descriptor.get("runtime_extent_minimums", {})
    if not isinstance(values, Mapping):
        raise GeneratedDecodeError(
            "generated decode descriptor has malformed runtime extent minimums")
    result = {}
    for name, value in values.items():
        if (
            not isinstance(name, str)
            or not name
            or isinstance(value, bool)
            or not isinstance(value, int)
            or value <= 1
        ):
            raise GeneratedDecodeError(
                "generated decode descriptor has invalid runtime extent minimum")
        capacity = (
            _descriptor_capacity(descriptor)
            if name == "active_batch" and "capacity" in descriptor
            else _shape_environment(descriptor, name)
        )
        if capacity is not None and value > capacity:
            raise GeneratedDecodeError(
                f"runtime extent {name!r} minimum {value} exceeds capacity "
                f"{capacity!r}")
        static_value = _static_extent_bindings(descriptor).get(name)
        if static_value is not None and static_value < value:
            raise GeneratedDecodeError(
                f"static runtime extent {name!r}={static_value} is below "
                f"artifact minimum {value}")
        result[name] = value
    return result


def _runtime_extent_maximums(
    descriptor: Mapping[str, Any],
) -> dict[str, int]:
    """Read explicit runtime upper bounds, defaulting to physical capacity."""

    values = descriptor.get("runtime_extent_maximums", {})
    if not isinstance(values, Mapping):
        raise GeneratedDecodeError(
            "generated decode descriptor has malformed runtime extent maximums")
    minimums = _runtime_extent_minimums(descriptor)
    result = {}
    for name, value in values.items():
        capacity = (
            _descriptor_capacity(descriptor)
            if name == "active_batch" and "capacity" in descriptor
            else _shape_environment(descriptor, name)
        )
        if (
            not isinstance(name, str)
            or not name
            or isinstance(value, bool)
            or not isinstance(value, int)
            or value <= 0
            or capacity is None
            or value >= capacity
            or value < minimums.get(name, 1)
        ):
            raise GeneratedDecodeError(
                "generated decode descriptor has invalid runtime extent maximum")
        static_value = _static_extent_bindings(descriptor).get(name)
        if static_value is not None and static_value > value:
            raise GeneratedDecodeError(
                f"static runtime extent {name!r}={static_value} exceeds "
                f"artifact maximum {value}")
        result[name] = value
    return result


def _program_identity(
    descriptor: Mapping[str, Any],
) -> tuple[
    int,
    tuple[tuple[str, int], ...],
    tuple[tuple[str, int], ...],
    tuple[tuple[str, int], ...],
    int,
]:
    return (
        _descriptor_capacity(descriptor),
        tuple(sorted(_static_extent_bindings(descriptor).items())),
        tuple(sorted(_runtime_extent_minimums(descriptor).items())),
        tuple(sorted(_runtime_extent_maximums(descriptor).items())),
        _descriptor_num_ctas(descriptor),
    )


def _has_exact_runtime_descriptor_schema(
    descriptor: Mapping[str, Any],
) -> bool:
    if not isinstance(descriptor, Mapping):
        return False
    schema_version = descriptor.get("schema_version")
    program = descriptor.get("program")
    return (
        type(schema_version) is int
        and schema_version == 1
        and isinstance(program, Mapping)
        and type(program.get("schema_version")) is int
        and program.get("schema_version") == 1
    )


def _validate_packed_runtime_weight_contract(
    descriptor: Mapping[str, Any],
) -> None:
    """Validate compiler-owned weight topology before accepting packed code.

    Legacy descriptors have no recipe ownership or logical branch-map field.
    They remain safe because a missing source is always treated as active by
    :func:`_recipe_row_sources`.  Once either ownership field is present, the
    complete compiler contract is required; a partially refreshed or coherently
    corrupted runtime index must not authorize inactive zero rows.
    """

    weights = descriptor.get("weights")
    if weights is not None:
        if type(weights) is not list:
            raise GeneratedDecodeError(
                "packed generated decode runtime weight recipes are malformed"
            )
        for recipe in weights:
            if type(recipe) is not dict:
                raise GeneratedDecodeError(
                    "packed generated decode runtime weight recipe is malformed"
                )
            _recipe_expected(recipe)
    ownership_declared = (
        "weight_layer_branches" in descriptor
        or (
            isinstance(weights, Sequence)
            and not isinstance(weights, (str, bytes))
            and any(
                isinstance(recipe, Mapping) and "branches" in recipe
                for recipe in weights
            )
        )
    )
    if not ownership_declared:
        return
    if (
        not isinstance(weights, Sequence)
        or isinstance(weights, (str, bytes))
        or not weights
    ):
        raise GeneratedDecodeError(
            "packed generated decode runtime weight recipes are missing")

    num_layers = descriptor.get("num_layers")
    validated_num_layers = (
        num_layers
        if (
            not isinstance(num_layers, bool)
            and isinstance(num_layers, int)
            and num_layers > 0
        )
        else None
    )
    layer_branches = descriptor.get("weight_layer_branches")
    program = descriptor.get("device_program")
    device_layer_branches = (
        # DeviceProgram.serialize omits this field for an unbranched program.
        program.get("layer_branches", ())
        if isinstance(program, Mapping)
        else None
    )
    if (
        validated_num_layers is None
        or not isinstance(layer_branches, Sequence)
        or isinstance(layer_branches, (str, bytes))
        # An explicitly empty map denotes an unbranched program. Its recipes
        # are still limited below to unconditional "both"/"tail" ownership.
        or len(layer_branches) not in (0, validated_num_layers)
        or any(
            not isinstance(branch, str) or not branch
            for branch in layer_branches
        )
        or not isinstance(device_layer_branches, Sequence)
        or isinstance(device_layer_branches, (str, bytes))
        or list(layer_branches) != list(device_layer_branches)
    ):
        raise GeneratedDecodeError(
            "packed generated decode logical layer-branch metadata is "
            "missing or malformed"
        )

    allowed_branches = frozenset(layer_branches) | {"both", "tail"}
    names = set()
    for recipe in weights:
        if not isinstance(recipe, Mapping):
            raise GeneratedDecodeError(
                "packed generated decode runtime weight recipe is malformed")
        name = recipe.get("name")
        if not isinstance(name, str) or not name or name in names:
            raise GeneratedDecodeError(
                "packed generated decode runtime weight recipe identity is "
                "malformed"
            )
        names.add(name)

        branches = recipe.get("branches")
        if (
            not isinstance(branches, Sequence)
            or isinstance(branches, (str, bytes))
            or not branches
            or any(
                not isinstance(branch, str) or not branch
                for branch in branches
            )
            or len(frozenset(branches)) != len(branches)
            or not frozenset(branches).issubset(allowed_branches)
        ):
            raise GeneratedDecodeError(
                f"packed generated decode weight {name!r} has missing or "
                "malformed branch ownership"
            )

        physical_layers = recipe.get("physical_layers")
        if (
            not isinstance(physical_layers, Sequence)
            or isinstance(physical_layers, (str, bytes))
            or not physical_layers
        ):
            raise GeneratedDecodeError(
                f"packed generated decode weight {name!r} has malformed "
                "physical layers"
            )
        if recipe.get("per_layer") is True:
            if any(
                isinstance(layer, bool)
                or not isinstance(layer, int)
                or layer < 0
                or (
                    validated_num_layers is not None
                    and layer >= validated_num_layers
                )
                for layer in physical_layers
            ) or len(set(physical_layers)) != len(physical_layers):
                raise GeneratedDecodeError(
                    f"packed generated decode weight {name!r} has malformed "
                    "physical layers"
                )
        elif (
            recipe.get("per_layer") is not False
            or list(physical_layers) != [None]
        ):
            raise GeneratedDecodeError(
                f"packed generated decode weight {name!r} has malformed "
                "model-scoped rows"
            )


def available_programs(*, arch: str) -> tuple[dict, ...]:
    """Return packaged descriptors, rejecting cross-archive program conflicts."""

    from .cubin_runtime import iter_packed_family_variant_indices

    _normalized_cuda_arch(arch, contract="requested artifact target")
    descriptors = []
    by_program = {}
    for archive_priority, variant_key, descriptor in iter_packed_family_variant_indices(
        "generated_decode",
        "runtime_index",
        arch=arch,
        require_aot=True,
    ):
        if not _has_exact_runtime_descriptor_schema(descriptor):
            continue
        num_ctas = descriptor.get("num_ctas")
        if (
            isinstance(num_ctas, bool)
            or not isinstance(num_ctas, int)
            or num_ctas <= 0
        ):
            continue
        program = descriptor.get("program")
        identity = (
            json.dumps(program, sort_keys=True, separators=(",", ":")),
            int(descriptor["num_ctas"]),
        )
        existing = by_program.get(identity)
        if existing is not None:
            existing_priority, existing_key = existing
            if existing_priority == archive_priority:
                raise GeneratedDecodeError(
                    "same archive declares multiple generated decode variants "
                    f"for {dict(program)!r}: {existing_key!r}, {variant_key!r}"
                )
            raise GeneratedDecodeError(
                "different archives declare conflicting generated decode variants "
                f"for {dict(program)!r}: archive {existing_priority} has "
                f"{existing_key!r}, archive {archive_priority} has {variant_key!r}"
            )
        copied = dict(descriptor)
        copied["variant_key"] = str(variant_key)
        descriptors.append(copied)
        by_program[identity] = (archive_priority, variant_key)
    return tuple(sorted(
        descriptors,
        key=lambda item: (
            str(item["program"]["registration"]),
            str(item["program"]["program"]),
            int(item["num_ctas"]),
        ),
    ))


def _packed_artifact_receipt(
    resolved,
    descriptor: Mapping[str, Any],
    *,
    metadata: Mapping[str, Any] | None = None,
) -> dict:
    receipt = resolved.receipt
    if (
        receipt.get("family") != "generated_decode"
        or (
            "variant_key" in descriptor
            and receipt.get("variant_key") != descriptor.get("variant_key")
        )
    ):
        raise GeneratedDecodeError(
            "packed generated decode receipt disagrees with the selected variant")
    if not isinstance(receipt.get("architecture"), str) or not receipt["architecture"]:
        raise GeneratedDecodeError(
            "packed generated decode receipt is missing 'architecture'")
    archive_hashes = {
        name: _receipt_sha256(receipt.get(name), name)
        for name in (
            "manifest_content_fingerprint",
            "inventory_fingerprint", "wrapper_sha256",
        )
    }
    if "build_toolchain_sha256" in receipt:
        archive_hashes["build_toolchain_sha256"] = _receipt_sha256(
            receipt["build_toolchain_sha256"], "build_toolchain_sha256"
        )

    if metadata is None:
        metadata = resolved.variant_metadata
    if not isinstance(metadata, Mapping):
        raise GeneratedDecodeError(
            "packed generated decode receipt has malformed variant metadata")
    signature = metadata.get("decode_aot_signature")
    if not isinstance(signature, Mapping):
        raise GeneratedDecodeError(
            "packed generated decode receipt has no AOT signature")
    (
        descriptor_sha256,
        program_key,
        source_sha256,
    ) = _packed_runtime_descriptor_identity(
        signature,
        descriptor,
        variant_key=receipt["variant_key"],
    )
    _validate_descriptor_runtime_projection(descriptor)
    descriptor_num_ctas = _validate_descriptor_emitted_grid(descriptor)
    _packed_wrapper_abi(
        resolved.bundle,
        metadata,
        descriptor,
        resolved.inventory_variant_key,
    )
    _emitted_dynamic_smem_bytes(descriptor)

    hashes = {
        "implementation_sha256": _receipt_sha256(
            signature.get("implementation_sha256"),
            "implementation_sha256",
        ),
        "source_sha256": source_sha256,
        "runtime_descriptor_sha256": descriptor_sha256,
    }

    return {
        **{
            key: value
            for key, value in receipt.items()
            if key != "source_fingerprint"
        },
        "device_program_key": program_key,
        "capacity": int(descriptor["capacity"]),
        "static_extent_bindings": _static_extent_bindings(descriptor),
        "runtime_extent_minimums": _runtime_extent_minimums(descriptor),
        "runtime_extent_maximums": _runtime_extent_maximums(descriptor),
        "num_ctas": descriptor_num_ctas,
        **archive_hashes,
        **hashes,
    }


def _resolve_program_descriptor(
    descriptor: Mapping[str, Any],
    arch: str,
) -> "GeneratedDecodeProgram | None":
    _normalized_cuda_arch(arch, contract="requested artifact target")
    if not _has_exact_runtime_descriptor_schema(descriptor):
        raise GeneratedDecodeError(
            "packed generated decode runtime index has noncanonical schema"
        )
    variant_key = str(descriptor["variant_key"])
    resolved = _FAMILY._resolve_shipped_with_receipt(variant_key, arch)
    if resolved is None:
        return None
    metadata = resolved.variant_metadata
    if not isinstance(metadata, Mapping):
        raise GeneratedDecodeError(
            "packed generated decode variant has malformed compiler metadata"
        )
    full = metadata.get("runtime_descriptor")
    if not isinstance(full, Mapping):
        raise GeneratedDecodeError(
            "packed generated decode variant has no authoritative runtime "
            "descriptor"
        )
    try:
        full = expand_runtime_descriptor_tape(full)
    except RuntimeDescriptorIdentityError as exc:
        raise GeneratedDecodeError(
            "packed generated decode variant has an invalid tape codec"
        ) from exc
    if not _has_exact_runtime_descriptor_schema(full):
        raise GeneratedDecodeError(
            "packed generated decode runtime descriptor has noncanonical schema"
        )
    signature = metadata.get("decode_aot_signature")
    if not isinstance(signature, Mapping):
        raise GeneratedDecodeError(
            "packed generated decode receipt has no AOT signature")
    copied = dict(full)
    copied["variant_key"] = variant_key
    artifact_receipt = _packed_artifact_receipt(
        resolved,
        copied,
        metadata=metadata,
    )
    for name in (
        "schema_version",
        "program",
        "capacity",
        "static_extent_bindings",
        "runtime_extent_minimums",
        "runtime_extent_maximums",
        "num_ctas",
        "num_layers",
        "weight_layer_branches",
        "weight_layer_prefix",
        "weights",
    ):
        if name == "static_extent_bindings":
            full_value = _static_extent_bindings(full)
            index_value = _static_extent_bindings(descriptor)
        elif name == "runtime_extent_minimums":
            full_value = _runtime_extent_minimums(full)
            index_value = _runtime_extent_minimums(descriptor)
        elif name == "runtime_extent_maximums":
            full_value = _runtime_extent_maximums(full)
            index_value = _runtime_extent_maximums(descriptor)
        elif name == "capacity":
            full_value = _descriptor_capacity(full)
            index_value = _descriptor_capacity(descriptor)
        elif name == "num_ctas":
            full_value = _descriptor_num_ctas(full)
            index_value = _descriptor_num_ctas(descriptor)
        else:
            full_value = full.get(name)
            index_value = descriptor.get(name)
        if not _same_json_identity(full_value, index_value):
            raise GeneratedDecodeError(
                f"packed runtime index disagrees with exact descriptor field {name!r}"
            )
    _validate_packed_runtime_weight_contract(full)
    _packed_argument_alignments(signature, full, arch)
    return GeneratedDecodeProgram(
        descriptor=copied,
        bundle=resolved.bundle,
        artifact_receipt=artifact_receipt,
    )


def resolve_program(
    *,
    registration: str,
    program: str,
    arch: str,
    device_sms: int,
):
    """Resolve one exact compiler declaration from the shipped bundle."""

    device_sms = _positive_device_sms(device_sms)
    matches = [
        descriptor
        for descriptor in available_programs(arch=arch)
        if descriptor["program"] == {
            "schema_version": 1,
            "registration": str(registration),
            "program": str(program),
        }
        and int(descriptor["num_ctas"]) <= device_sms
    ]
    if not matches:
        return None
    widest = max(int(descriptor["num_ctas"]) for descriptor in matches)
    matches = [
        descriptor for descriptor in matches
        if int(descriptor["num_ctas"]) == widest
    ]
    if len(matches) != 1:
        raise GeneratedDecodeError(
            "ambiguous generated decode program "
            f"{registration}/{program} at num_ctas={widest}")
    return _resolve_program_descriptor(matches[0], arch)


def _weights_match(
    module: torch.nn.Module,
    descriptor: Mapping[str, Any],
    layer_prefix: str,
    weight_sources: Mapping[str, torch.Tensor] | None = None,
) -> bool:
    if weight_sources is None:
        named = dict(module.named_parameters(remove_duplicate=False))
        named.update(dict(module.named_buffers(remove_duplicate=False)))
    else:
        named = dict(weight_sources)
        if not all(isinstance(value, torch.Tensor) for value in named.values()):
            return False
    try:
        for recipe in descriptor["weights"]:
            if recipe.get("kind", "param") != "param":
                continue
            expected_shape, expected_dtype = _recipe_expected(recipe)
            if _recipe_is_explicit_zero(recipe):
                continue
            active_rows = 0
            for layer in recipe["physical_layers"]:
                resolved = _recipe_row_sources(
                    descriptor, recipe, layer, layer_prefix, named
                )
                if resolved is None:
                    continue
                active_rows += 1
                sources = tuple(
                    torch.empty_like(source, device="meta") for source in resolved
                )
                value = _prepare_weight(
                    sources, recipe.get("prep"), expected_shape=expected_shape)
                if tuple(value.shape) != expected_shape:
                    return False
                if value.dtype != expected_dtype:
                    return False
            if active_rows == 0:
                return False
    except (KeyError, GeneratedDecodeError, RuntimeError, TypeError, ValueError):
        return False
    return True


def _positive_device_sms(value: int | None) -> int:
    if type(value) is not int or value <= 0:
        raise GeneratedDecodeError(
            "generated decode requires a positive device SM count")
    return value


def _positive_selection_capacity(value: Any) -> int:
    if type(value) is not int or value <= 0:
        raise GeneratedDecodeError(
            "generated decode requires a positive exact capacity"
        )
    return value


def resolve_compatible_program(
    module: torch.nn.Module,
    *,
    layer_prefix: str,
    capacity: int,
    arch: str,
    device_sms: int,
    active_extent_bindings: Mapping[str, int] | None = None,
    weight_sources: Mapping[str, torch.Tensor] | None = None,
) -> GeneratedDecodeProgram | None:
    """Select the preferred shipped artifact compatible with model storage.

    Selection uses compiler-emitted weight recipes and dimensions, not a model
    name or a public architecture table.
    """

    device_sms = _positive_device_sms(device_sms)
    capacity = _positive_selection_capacity(capacity)
    programs = []
    for descriptor in available_programs(arch=arch):
        if (
            _descriptor_capacity(descriptor) != capacity
            or _descriptor_num_ctas(descriptor) > device_sms
            or not _weights_match(
                module, descriptor, str(layer_prefix), weight_sources)
        ):
            continue
        programs.append(GeneratedDecodeProgram(descriptor, None))
    if active_extent_bindings is None:
        covering = [
            program for program in programs
            if (
                not program.static_extent_bindings
                or (
                    capacity == 1
                    and program.static_extent_bindings == {"active_batch": 1}
                )
            )
        ]
        if not covering:
            return None
        widest = max(program.num_ctas for program in covering)
        covering = [
            program for program in covering if program.num_ctas == widest
        ]
        if len(covering) != 1:
            names = [program.descriptor["program"] for program in covering]
            raise GeneratedDecodeError(
                "model storage matches multiple dynamic generated decode "
                f"programs: {names}")
        winner = covering[0]
    else:
        winner = select_compatible_program(
            programs,
            active_extent_bindings,
            device_sms=device_sms,
        )
        if winner is None:
            return None
    return _resolve_program_descriptor(winner.descriptor, arch)


def resolve_compatible_programs(
    module: torch.nn.Module,
    *,
    layer_prefix: str,
    arch: str,
    device_sms: int,
    weight_sources: Mapping[str, torch.Tensor] | None = None,
    program_names: Collection[str] | None = None,
) -> tuple["GeneratedDecodeProgram", ...]:
    """Resolve every artifact identity compiled for one model's weights."""

    device_sms = _positive_device_sms(device_sms)
    if program_names is None:
        allowed_programs = None
    else:
        if (
            isinstance(program_names, (str, bytes))
            or not isinstance(program_names, Collection)
        ):
            raise GeneratedDecodeError(
                "generated decode program names must be a collection of "
                "nonempty strings"
            )
        names = tuple(program_names)
        if any(type(name) is not str or not name for name in names):
            raise GeneratedDecodeError(
                "generated decode program names must be a collection of "
                "nonempty strings"
            )
        allowed_programs = frozenset(names)
    by_identity = {}
    for descriptor in available_programs(arch=arch):
        if (
            allowed_programs is not None
            and str(descriptor["program"]["program"]) not in allowed_programs
        ) or (
            _descriptor_num_ctas(descriptor) > device_sms
            or not _weights_match(
                module, descriptor, str(layer_prefix), weight_sources)
        ):
            continue
        identity = _program_identity(descriptor)
        if identity in by_identity:
            declarations = [
                by_identity[identity]["program"], descriptor["program"]]
            raise GeneratedDecodeError(
                "model storage matches multiple generated decode programs for "
                f"identity {identity!r}: {declarations}")
        by_identity[identity] = descriptor
    programs = []
    for descriptor in by_identity.values():
        resolved = _resolve_program_descriptor(descriptor, arch)
        if resolved is not None:
            programs.append(resolved)
    return tuple(sorted(programs, key=lambda item: item.identity))


def select_compatible_program(
    programs,
    active_extent_bindings: Mapping[str, int],
    *,
    device_sms: int,
) -> "GeneratedDecodeProgram | None":
    """Select the smallest covering program, preferring an exact static match.

    Static bindings are compiler facts. A candidate is legal only when every
    bound extent equals the live request, and its persistent grid must fit the
    live device. An unbound artifact remains the coverage fallback. Within the
    smallest physical capacity, then the tightest admitted maximum, more
    static matches, and finally the widest fitting grid.
    """

    device_sms = _positive_device_sms(device_sms)
    if not isinstance(active_extent_bindings, Mapping):
        raise GeneratedDecodeError(
            "generated decode selection extents must be a mapping"
        )
    requested = {}
    for name, value in active_extent_bindings.items():
        if type(name) is not str or not name or type(value) is not int or value <= 0:
            raise GeneratedDecodeError(
                "generated decode selection requires positive exact integer "
                "extents with nonempty string names"
            )
        requested[name] = value
    try:
        active_batch = requested["active_batch"]
    except KeyError as exc:
        raise GeneratedDecodeError(
            "generated decode selection requires active_batch") from exc
    candidates = []
    for program in programs:
        minimums = program.runtime_extent_minimums
        maximums = program.runtime_extent_maximums
        if (
            any(
                name not in requested or requested[name] < minimum
                for name, minimum in minimums.items()
            )
            or any(
                name not in requested or requested[name] > maximum
                for name, maximum in maximums.items()
            )
            or program.capacity < active_batch
            or program.num_ctas > device_sms
        ):
            continue
        static = program.static_extent_bindings
        if any(requested.get(name) != value for name, value in static.items()):
            continue
        candidates.append(program)
    if not candidates:
        return None
    candidates.sort(key=lambda program: (
        program.capacity,
        program.runtime_extent_maximums.get("active_batch", program.capacity),
        -len(program.static_extent_bindings),
        -program.num_ctas,
        program.identity,
    ))
    winner = candidates[0]
    priority = (
        winner.capacity,
        winner.runtime_extent_maximums.get("active_batch", winner.capacity),
        -len(winner.static_extent_bindings),
        -winner.num_ctas,
    )
    ambiguous = [
        program for program in candidates
        if (
            program.capacity,
            program.runtime_extent_maximums.get("active_batch", program.capacity),
            -len(program.static_extent_bindings),
            -program.num_ctas,
        ) == priority
    ]
    if len(ambiguous) != 1:
        raise GeneratedDecodeError(
            "ambiguous generated decode programs for runtime extents "
            f"{requested!r}: "
            f"{[program.descriptor['program'] for program in ambiguous]}")
    return winner


def select_compatible_program_receipt(
    receipts: Sequence[Mapping[str, Any]],
    active_extent_bindings: Mapping[str, int],
    *,
    device_sms: int,
) -> Mapping[str, Any] | None:
    """Apply runtime selection to immutable public artifact receipts."""

    validated = tuple(_validated_packed_receipt(receipt) for receipt in receipts)
    selected = select_compatible_program(
        tuple(GeneratedDecodeProgram(receipt, None) for receipt in validated),
        active_extent_bindings,
        device_sms=device_sms,
    )
    return None if selected is None else selected.descriptor


@dataclass(frozen=True)
class GeneratedDecodeProgram:
    descriptor: Mapping[str, Any]
    bundle: Any
    artifact_receipt: Mapping[str, Any] | None = None

    def __post_init__(self) -> None:
        object.__setattr__(self, "descriptor", _freeze_identity(self.descriptor))
        if self.artifact_receipt is not None:
            object.__setattr__(
                self,
                "artifact_receipt",
                _freeze_identity(self.artifact_receipt),
            )

    @property
    def capacity(self) -> int:
        return _descriptor_capacity(self.descriptor)

    @property
    def num_ctas(self) -> int:
        return _descriptor_num_ctas(self.descriptor)

    @property
    def static_extent_bindings(self) -> dict[str, int]:
        return _static_extent_bindings(self.descriptor)

    @property
    def runtime_extent_minimums(self) -> dict[str, int]:
        return _runtime_extent_minimums(self.descriptor)

    @property
    def runtime_extent_maximums(self) -> dict[str, int]:
        return _runtime_extent_maximums(self.descriptor)

    @property
    def identity(self) -> tuple[
        int,
        tuple[tuple[str, int], ...],
        tuple[tuple[str, int], ...],
        tuple[tuple[str, int], ...],
        int,
    ]:
        return _program_identity(self.descriptor)

    def preload(self, device: torch.device | str) -> None:
        """Make this program's CUDA module resident before memory fitting.

        ``CuteAotVariant._ensure_device`` owns the per-device idempotence, so
        repeated preparation and the later bind are no-ops after the first load.
        """
        target = torch.device(device)
        if target.type != "cuda":
            raise GeneratedDecodeError("generated decode preload requires CUDA")
        device_index = (
            torch.cuda.current_device() if target.index is None else int(target.index)
        )
        try:
            ensure_device = self.bundle.aot._ensure_device
        except AttributeError as exc:
            raise GeneratedDecodeError(
                "generated decode program has no CUDA module loader"
            ) from exc
        ensure_device(device_index)

    def bind(self, bindings: Mapping[str, Any]) -> "BoundGeneratedDecode":
        if self.artifact_receipt is not None:
            _validate_descriptor_runtime_projection(self.descriptor)
        arguments = _arguments(self.descriptor)
        tape_contract = (
            _validated_tape_contract(
                self.descriptor,
                require_metadata=self.artifact_receipt is not None,
            )
            if any(argument.get("source") == "tape" for argument in arguments)
            else None
        )
        expected = {argument["name"] for argument in arguments}
        actual = set(bindings)
        if expected != actual:
            raise GeneratedDecodeError(
                "generated decode binding mismatch: "
                f"missing={sorted(expected - actual)}, extra={sorted(actual - expected)}")

        external_arguments = tuple(
            argument for argument in arguments
            if argument.get("source") == "external"
        )
        if external_arguments:
            physical_operands = _validated_external_operands(
                self.descriptor,
                arguments,
            )
        else:
            physical_operands = {}
        workspace_bindings = (
            _validated_workspace_bindings(self.descriptor, arguments)
            if any(argument.get("source") == "workspace" for argument in arguments)
            else {}
        )
        assembled_extents = None
        if isinstance(bindings, _AssembledBindings):
            if not _same_json_identity(
                bindings._device_program,
                self.descriptor.get("device_program"),
            ):
                raise GeneratedDecodeError(
                    "generated decode binding extent provenance belongs to a "
                    "different device program"
                )
            assembled_extents = bindings._runtime_extents
        runtime_extents = {}
        for argument in arguments:
            if argument.get("source") != "runtime_extent":
                continue
            value = bindings[argument["name"]]
            if type(value) is not int or value <= 0:
                raise GeneratedDecodeError(
                    f"generated decode runtime extent {argument['name']!r} "
                    f"has invalid value {value!r}")
            name = str(argument["name"])
            if (
                assembled_extents is not None
                and assembled_extents.get(name) != value
            ):
                raise GeneratedDecodeError(
                    f"generated decode runtime extent {name!r} changed after "
                    "binding assembly"
                )
            runtime_extents[name] = value
        if assembled_extents is not None:
            for name, value in assembled_extents.items():
                if type(name) is not str or type(value) is not int or value <= 0:
                    raise GeneratedDecodeError(
                        "generated decode binding has malformed runtime extent "
                        "provenance"
                    )
                runtime_extents.setdefault(name, value)
        dynamic_storage_extents = (
            _physical_dynamic_scalars(self.descriptor)
            if physical_operands else ()
        )
        workspace_storage_extents = _workspace_dynamic_scalars(
            workspace_bindings
        )
        runtime_argument_names = {
            str(argument["name"])
            for argument in arguments
            if argument.get("source") == "runtime_extent"
        }
        if (
            (
                set(dynamic_storage_extents)
                | (workspace_storage_extents - runtime_argument_names)
            )
            and assembled_extents is None
        ):
            raise GeneratedDecodeError(
                "generated decode dynamic storage requires assembled runtime "
                "extent provenance"
            )
        storage_extents = (
            _storage_extent_capacities(self.descriptor, runtime_extents)
            if physical_operands else {}
        )
        storage_extent_scalar_names = (
            frozenset(dynamic_storage_extents) | workspace_storage_extents
        )
        fixed_runtime_extents = {}
        for name in _stride_forming_runtime_extents(
            physical_operands,
            workspace_bindings,
        ):
            live = runtime_extents.get(name)
            capacity = storage_extents.get(name)
            if capacity is None:
                capacity = (
                    _descriptor_capacity(self.descriptor)
                    if name == "active_batch"
                    else _shape_environment(self.descriptor, name)
                )
            if live != capacity:
                raise GeneratedDecodeError(
                    f"generated decode stride-forming runtime extent {name!r} "
                    f"must equal backing capacity {capacity!r}, got {live!r}")
            fixed_runtime_extents[name] = capacity
        for name, capacity in storage_extents.items():
            if (
                name != "active_batch"
                and _shape_environment(self.descriptor, name) is None
            ):
                # Construction-derived extents have no separate compiler-owned
                # maximum. The assembled backing shape is therefore their exact
                # authority for this binding, including outer axes whose
                # contiguous stride does not otherwise force equality.
                fixed_runtime_extents[name] = capacity
        table_provenance = (
            bindings._address_tables
            if isinstance(bindings, _AssembledBindings)
            else {}
        )
        stream_arguments = tuple(
            argument for argument in arguments
            if argument.get("transport") == "stream"
        )
        if len(stream_arguments) != 1:
            raise GeneratedDecodeError(
                f"generated decode has {len(stream_arguments)} stream arguments")
        binding_stream = bindings[stream_arguments[0]["name"]]

        alignment_rows = self.descriptor.get("argument_alignments", ())
        if not isinstance(alignment_rows, (list, tuple)) or any(
            not isinstance(entry, Mapping)
            or not isinstance(entry.get("name"), str)
            or not entry["name"]
            or type(entry.get("assumed_align")) is not int
            or entry["assumed_align"] <= 0
            or entry["assumed_align"] & (entry["assumed_align"] - 1)
            for entry in alignment_rows
        ):
            raise GeneratedDecodeError(
                "generated decode argument alignment contract is malformed")
        argument_alignments = {
            entry["name"]: entry["assumed_align"]
            for entry in alignment_rows
        }
        if len(argument_alignments) != len(tuple(alignment_rows)):
            raise GeneratedDecodeError(
                "generated decode argument alignment contract has duplicate names")
        expected_alignment_names = tuple(
            str(argument["name"])
            for argument in arguments
            if argument.get("transport") in {
                "tensor", "layer_address_table", "raw_pointer",
            }
        )
        if alignment_rows and tuple(argument_alignments) != expected_alignment_names:
            raise GeneratedDecodeError(
                "generated decode argument alignment contract does not exactly "
                "cover memory arguments in ABI order")
        base_argument_alignments = {}
        for argument in arguments:
            if argument.get("transport") not in {
                "tensor", "layer_address_table", "raw_pointer",
            }:
                continue
            assumed_align = argument.get("assumed_align")
            if (
                type(assumed_align) is not int
                or assumed_align <= 0
                or assumed_align & (assumed_align - 1)
            ):
                raise GeneratedDecodeError(
                    f"generated decode argument {argument['name']!r} has an "
                    "invalid base alignment contract")
            base_argument_alignments[str(argument["name"])] = assumed_align

        expected_kinds = []
        memrefs = []
        memref_arguments = []
        tensors = []
        tensor_snapshots = []
        capacity_authority_tensors = []
        capacity_authority_snapshots = []
        address_table_pointees = []
        address_table_pointee_snapshots = []
        address_table_storage_ids = set()
        counter_tensors = {}
        scalar_defaults = {}
        scalar_order = []
        stream = None
        device_index = None
        for argument in arguments:
            name = argument["name"]
            value = bindings[name]
            transport = argument["transport"]
            if transport in {"tensor", "layer_address_table", "raw_pointer"}:
                source = argument.get("source")
                allowed_transports = {
                    "external": {"tensor", "layer_address_table", "raw_pointer"},
                    "workspace": {"tensor", "raw_pointer"},
                    "tape": {"tensor"},
                    "counter": {"tensor"},
                }
                if transport not in allowed_transports.get(source, set()):
                    raise GeneratedDecodeError(
                        f"generated decode memory argument {name!r} has "
                        f"unsupported source/transport {source!r}/{transport!r}")
                expected_kinds.append("memref")
                if not isinstance(value, torch.Tensor) or not value.is_cuda:
                    raise GeneratedDecodeError(f"{name!r} must be a CUDA tensor")
                if argument.get("source") == "tape":
                    tape_stream = _binding_torch_stream(
                        binding_stream,
                        value.device,
                    )
                    with torch.cuda.stream(tape_stream):
                        value = _tape_tensor(
                            self.descriptor,
                            argument,
                            device=value.device,
                            tape=tape_contract,
                        )
                elif argument.get("source") == "counter":
                    counter_stream = _binding_torch_stream(
                        binding_stream,
                        value.device,
                    )
                    with torch.cuda.stream(counter_stream):
                        value = torch.zeros(
                            tuple(argument["shape"]),
                            dtype=_TORCH_DTYPES[argument["dtype"]],
                            device=value.device,
                        )
                if source == "external":
                    try:
                        operand = physical_operands[name]
                    except KeyError as exc:
                        raise GeneratedDecodeError(
                            f"generated decode argument {name!r} has no physical "
                            "ABI") from exc
                    _validate_external_operand_contract(argument, operand)
                    if transport == "layer_address_table":
                        _address_table_operand_contract(
                            argument,
                            operand,
                            storage_extents,
                        )
                        ownership = table_provenance.get(name)
                        if ownership is None:
                            raise GeneratedDecodeError(
                                f"generated decode address table {name!r} needs "
                                "generated row/pointee provenance")
                        if ownership.table is not value:
                            raise GeneratedDecodeError(
                                f"generated decode address table {name!r} was "
                                "replaced after assembly")
                        if (
                            _tensor_binding_identity(ownership.table)
                            != ownership.table_identity
                        ):
                            raise GeneratedDecodeError(
                                f"generated decode address table {name!r} "
                                "changed storage after assembly")
                        retained = []
                        retained_snapshots = []
                        for row, alias in enumerate(ownership.rows):
                            if alias is None:
                                if ownership.pointers[row] != 0:
                                    raise GeneratedDecodeError(
                                        f"generated decode address table "
                                        f"{name!r} row {row} has a non-null "
                                        "pointer without a pointee")
                                continue
                            row_before = _tensor_binding_identity(alias)
                            validated = _validate_address_table_row(
                                argument,
                                operand,
                                alias,
                                storage_extents,
                                device=value.device,
                                row=row,
                            )
                            row_snapshot = _tensor_binding_identity(validated)
                            if row_snapshot != row_before:
                                raise GeneratedDecodeError(
                                    f"generated decode address table {name!r} "
                                    f"row {row} changed while it was validated"
                                )
                            expected_pointer = ownership.pointers[row]
                            if int(validated.data_ptr()) != expected_pointer:
                                raise GeneratedDecodeError(
                                    f"generated decode address table {name!r} "
                                    f"row {row} changed storage allocation "
                                    "after assembly")
                            storage_id = (
                                str(validated.device),
                                int(validated.untyped_storage()._cdata),
                            )
                            if storage_id not in address_table_storage_ids:
                                retained.append(validated)
                                retained_snapshots.append(row_snapshot)
                                address_table_storage_ids.add(storage_id)
                        # Launch a private table rebuilt from retained aliases;
                        # caller-side edits to the assembly result cannot
                        # redirect its pointers after this point.
                        value = _pointer_table(
                            ownership.pointers,
                            device=value.device,
                            stream=binding_stream,
                        )
                        _require_tensor_snapshot_authority(
                            retained,
                            retained_snapshots,
                            label=f"address table {name!r} row storage",
                        )
                        address_table_pointees.extend(retained)
                        address_table_pointee_snapshots.extend(
                            retained_snapshots
                        )
                elif source == "workspace":
                    try:
                        workspace_binding = workspace_bindings[name]
                    except KeyError as exc:
                        raise GeneratedDecodeError(
                            f"generated decode workspace {name!r} has no compiler "
                            "storage plan") from exc
                elif transport in {"raw_pointer", "layer_address_table"}:
                    raise GeneratedDecodeError(
                        f"generated decode {transport} argument {name!r} has "
                        f"unsupported source {source!r}")
                # Keep metadata independent from caller-side ``set_`` or
                # ``.data=`` replacement. ``resize_`` can still replace the
                # shared storage allocation, so its identity is snapshotted
                # and revalidated below and before every launch.
                value = value.detach()
                backing_snapshot = None
                if source == "external" and transport == "raw_pointer":
                    backing_snapshot = _tensor_identity_transaction(
                        value,
                        label=f"raw pointer {name!r}",
                        validator=lambda: _validate_raw_pointer_storage(
                            argument,
                            operand,
                            value,
                            storage_extents,
                        ),
                    )
                elif source == "workspace":
                    backing_snapshot = _tensor_identity_transaction(
                        value,
                        label=f"workspace {name!r}",
                        validator=lambda: _validate_workspace_storage(
                            self.descriptor,
                            argument,
                            workspace_binding,
                            value,
                        ),
                    )
                if transport == "raw_pointer" and backing_snapshot is not None:
                    capacity_authority_tensors.append(value)
                    capacity_authority_snapshots.append(backing_snapshot)
                if source == "counter":
                    # Reset the same detached tensor whose memref is packed.
                    # A pre-detach alias can be redirected with ``set_`` while
                    # leaving the wrapper's real counter storage unchanged.
                    counter_tensors[name] = value
                if transport == "raw_pointer":
                    elements = prod(int(dim) for dim in argument["shape"])
                    if not value.is_contiguous() or value.numel() < elements:
                        raise GeneratedDecodeError(
                            f"raw pointer {name!r} cannot provide {elements} elements")
                    value = value.view(-1)[:elements].view(argument["shape"])
                tensor_snapshot = _tensor_identity_transaction(
                    value,
                    label=f"tensor {name!r}",
                    validator=lambda: _validate_tensor_binding(argument, value),
                )
                if transport == "raw_pointer" and backing_snapshot is not None:
                    if (
                        tensor_snapshot[0] != backing_snapshot[0]
                        or tensor_snapshot[1] != backing_snapshot[1]
                        or tensor_snapshot[2] != backing_snapshot[2]
                        or tensor_snapshot[5:] != backing_snapshot[5:]
                    ):
                        raise GeneratedDecodeError(
                            f"generated decode pointer-only argument {name!r} "
                            "changed while its one-element ABI view was built"
                        )
                base_alignment = base_argument_alignments[name]
                strengthened_alignment = argument_alignments.get(name)
                if (
                    strengthened_alignment is not None
                    and (
                        strengthened_alignment < base_alignment
                        or strengthened_alignment % base_alignment
                    )
                ):
                    raise GeneratedDecodeError(
                        f"generated decode argument {name!r} has invalid "
                        f"strengthened alignment {strengthened_alignment} for "
                        f"base alignment {base_alignment}")
                required_alignment = (
                    base_alignment
                    if strengthened_alignment is None else strengthened_alignment
                )
                if (
                    int(value.data_ptr()) % required_alignment
                ):
                    raise GeneratedDecodeError(
                        f"generated decode argument {name!r} address "
                        f"{int(value.data_ptr()):#x} is not "
                        f"{required_alignment}-byte aligned")
                index = value.device.index
                if index is None:
                    raise GeneratedDecodeError(f"{name!r} has no CUDA device index")
                if device_index is None:
                    device_index = int(index)
                elif device_index != int(index):
                    raise GeneratedDecodeError("generated decode bindings span CUDA devices")
                tensors.append(value)
                tensor_snapshots.append(tensor_snapshot)
                memrefs.append(value)
                memref_arguments.append(argument)
            elif transport == "scalar":
                source = argument.get("source")
                if source not in {"external", "runtime_extent"}:
                    raise GeneratedDecodeError(
                        f"generated decode scalar argument {name!r} has "
                        f"unsupported source {source!r}")
                if source == "external":
                    operand = physical_operands.get(name)
                    if operand is None or operand.get("transport") != "scalar":
                        raise GeneratedDecodeError(
                            f"generated decode external scalar argument {name!r} "
                            "has no matching physical ABI")
                expected_kinds.append("scalar")
                packed = _pack_scalar_value(
                    argument.get("dtype"),
                    value,
                    name=name,
                )
                if name in storage_extent_scalar_names:
                    if argument.get("dtype") != "int32":
                        raise GeneratedDecodeError(
                            f"generated decode storage extent scalar {name!r} "
                            "must use the compiler int32 ABI"
                        )
                    assembled_value = runtime_extents.get(name)
                    if assembled_value is None or packed.value != assembled_value:
                        raise GeneratedDecodeError(
                            f"generated decode storage extent scalar {name!r}="
                            f"{packed.value!r} disagrees with assembled extent "
                            f"provenance {assembled_value!r}"
                        )
                scalar_defaults[name] = packed.value
                scalar_order.append(name)
            elif transport == "stream":
                if argument.get("source") != "stream":
                    raise GeneratedDecodeError(
                        f"generated decode stream argument {name!r} has "
                        f"unsupported source {argument.get('source')!r}")
                expected_kinds.append("stream")
                if stream is not None:
                    raise GeneratedDecodeError("generated decode has multiple streams")
                stream = value
            else:
                raise GeneratedDecodeError(
                    f"unsupported argument transport {transport!r}")

        if tuple(expected_kinds) != tuple(self.bundle.arg_kinds):
            raise GeneratedDecodeError("bundle argument ABI disagrees with runtime descriptor")
        if len(self.bundle.memref_specs) != len(memrefs):
            raise GeneratedDecodeError("bundle memref ABI disagrees with runtime descriptor")
        for argument, spec, value in zip(
            memref_arguments,
            self.bundle.memref_specs,
            memrefs,
            strict=True,
        ):
            _validate_memref_contract(argument, spec, value)
        binding_snapshots = tuple(tensor_snapshots)
        pointee_binding_snapshots = tuple(address_table_pointee_snapshots)
        capacity_binding_snapshots = tuple(capacity_authority_snapshots)

        def require_binding_authorities() -> None:
            _require_tensor_snapshot_authority(
                tensors,
                binding_snapshots,
                label="tensor storage",
            )
            _require_tensor_snapshot_authority(
                address_table_pointees,
                pointee_binding_snapshots,
                label="address-table storage",
            )
            _require_tensor_snapshot_authority(
                capacity_authority_tensors,
                capacity_binding_snapshots,
                label="pointer-only backing storage",
            )

        require_binding_authorities()
        if stream is None or device_index is None:
            raise GeneratedDecodeError("generated decode requires tensors and one stream")
        device_properties = torch.cuda.get_device_properties(device_index)
        device_sms = getattr(device_properties, "multi_processor_count", None)
        if type(device_sms) is not int or device_sms <= 0:
            raise GeneratedDecodeError(
                "generated decode live device has no positive SM count")
        if self.num_ctas > device_sms:
            raise GeneratedDecodeError(
                "generated decode artifact grid exceeds the live device: "
                f"num_ctas={self.num_ctas}, device_sms={device_sms}")
        if self.artifact_receipt is not None:
            _validate_live_artifact_target(
                self.descriptor,
                self.artifact_receipt,
                device_index=device_index,
                device_properties=device_properties,
            )
        stream = _binding_torch_stream(
            stream,
            torch.device("cuda", device_index),
        )
        recorded_storages = set()
        for value in (
            *tensors,
            *address_table_pointees,
            *capacity_authority_tensors,
        ):
            storage_id = (
                str(value.device),
                int(value.untyped_storage()._cdata),
            )
            if storage_id in recorded_storages:
                continue
            value.record_stream(stream)
            recorded_storages.add(storage_id)
        self.preload(torch.device("cuda", device_index))
        require_binding_authorities()
        structs = tuple(
            spec.build(value)
            for spec, value in zip(self.bundle.memref_specs, memrefs, strict=True)
        )
        require_binding_authorities()
        for argument, struct, value in zip(
            memref_arguments, structs, tensors, strict=True
        ):
            try:
                packed_pointer = int(struct.data or 0)
            except (AttributeError, TypeError, ValueError) as exc:
                raise GeneratedDecodeError(
                    f"generated decode memref {argument['name']!r} has a "
                    "malformed packed pointer"
                ) from exc
            if packed_pointer != int(value.data_ptr()):
                raise GeneratedDecodeError(
                    f"generated decode memref {argument['name']!r} packed a "
                    "pointer different from its validated tensor"
                )
        require_binding_authorities()
        artifact = dict(self.artifact_receipt or {})
        launch_receipt = {
            "schema_version": 1,
            "backend": "generated_decode_aot",
            "family": "generated_decode",
            "program": dict(self.descriptor["program"]),
            "variant_key": str(self.descriptor["variant_key"]),
            "manifest_content_fingerprint": artifact.get(
                "manifest_content_fingerprint"
            ),
            "inventory_fingerprint": artifact.get("inventory_fingerprint"),
            "wrapper_sha256": artifact.get("wrapper_sha256"),
            "architecture": artifact.get("architecture"),
            "device_program_key": artifact.get("device_program_key"),
            "implementation_sha256": artifact.get("implementation_sha256"),
            "source_sha256": artifact.get("source_sha256"),
            "runtime_descriptor_sha256": artifact.get(
                "runtime_descriptor_sha256"
            ),
            "delivery": "packed_aot",
            "capacity": self.capacity,
            "static_extent_bindings": self.static_extent_bindings,
            "runtime_extent_minimums": self.runtime_extent_minimums,
            "runtime_extent_maximums": self.runtime_extent_maximums,
            "num_ctas": self.num_ctas,
        }
        if "build_toolchain_sha256" in artifact:
            launch_receipt["build_toolchain_sha256"] = artifact[
                "build_toolchain_sha256"
            ]
        binding_authority = _issue_bound_binding_authority(
            binding_snapshots,
            pointee_binding_snapshots,
            capacity_binding_snapshots,
        )
        return BoundGeneratedDecode(
            descriptor=self.descriptor,
            _bundle=self.bundle,
            _counter_tensors=counter_tensors,
            _tensors=tuple(tensors),
            _memref_structs=structs,
            _scalar_defaults=scalar_defaults,
            _scalar_order=tuple(scalar_order),
            stream=stream,
            _counter_names=_host_reset_counter_names(self.descriptor),
            _launch_receipt=launch_receipt,
            _address_table_pointees=tuple(address_table_pointees),
            _capacity_authority_tensors=tuple(capacity_authority_tensors),
            _binding_authority=binding_authority,
            _fixed_runtime_extents=fixed_runtime_extents,
            _device_index=device_index,
        )


@dataclass(frozen=True)
class _LaunchScalarPlan:
    arguments: Mapping[str, Mapping[str, Any]]
    minimums: Mapping[str, int]
    maximums: Mapping[str, int]
    static_extents: Mapping[str, int]
    extent_scalar_names: frozenset[str]


@dataclass(frozen=True, slots=True)
class _PreparedDynamicScalar:
    name: str
    dtype: str
    default: Any
    holder: Any
    extent_lower: int | None
    extent_upper: int | None
    abi_lower: int | None
    abi_upper: int | None


@dataclass(frozen=True)
class BoundGeneratedDecode:
    """Program-bound launch state with pre-enqueue storage validation.

    As with PyTorch operations generally, resizing shared storage concurrently
    with a launch is a caller data race; binding-handoff and prelaunch changes
    are rejected, but launch does not serialize caller-side storage mutation.
    """

    descriptor: Mapping[str, Any]
    _bundle: Any = field(repr=False)
    _counter_tensors: Mapping[str, torch.Tensor] = field(repr=False)
    _tensors: tuple[torch.Tensor, ...] = field(repr=False)
    _memref_structs: tuple[Any, ...] = field(repr=False)
    _memref_snapshots: tuple[bytes, ...] = field(
        default=(), init=False, repr=False,
    )
    _tensor_snapshots: tuple[tuple[Any, ...], ...] = field(
        default=(), init=False, repr=False,
    )
    _pointee_snapshots: tuple[tuple[Any, ...], ...] = field(
        default=(), init=False, repr=False,
    )
    _capacity_snapshots: tuple[tuple[Any, ...], ...] = field(
        default=(), init=False, repr=False,
    )
    _scalar_defaults: Mapping[str, Any] = field(repr=False)
    _scalar_order: tuple[str, ...] = field(repr=False)
    stream: Any
    _counter_names: tuple[str, ...] = field(repr=False)
    _launch_receipt: InitVar[Mapping[str, Any]]
    _binding_authority: InitVar[Any] = None
    _launch_counter: _GeneratedDecodeLaunchCounter = field(
        init=False,
        repr=False,
    )
    _address_table_pointees: tuple[torch.Tensor, ...] = field(
        default=(), repr=False,
    )
    _capacity_authority_tensors: tuple[torch.Tensor, ...] = field(
        default=(), repr=False,
    )
    _storage_guards: tuple[_StorageGuard, ...] = field(
        default=(), init=False, repr=False,
    )
    _fixed_runtime_extents: Mapping[str, int] = field(
        default_factory=dict, repr=False,
    )
    _device_index: int | None = field(default=None, repr=False)
    _launch_lock: Any = field(
        default_factory=threading.Lock,
        init=False,
        repr=False,
        compare=False,
    )
    _dynamic_invocation: Any = field(
        default=None,
        init=False,
        repr=False,
        compare=False,
    )
    _dynamic_scalars: tuple[Any, ...] = field(
        default=(),
        init=False,
        repr=False,
        compare=False,
    )
    _launch_scalar_plan: _LaunchScalarPlan | None = field(
        default=None,
        init=False,
        repr=False,
        compare=False,
    )

    def __post_init__(
        self,
        _launch_receipt: Mapping[str, Any],
        _binding_authority: Any,
    ) -> None:
        validated_launch_receipt = _validated_packed_receipt(_launch_receipt)
        object.__setattr__(self, "descriptor", _freeze_identity(self.descriptor))
        raw_stream = getattr(self.stream, "cuda_stream", self.stream)
        if type(raw_stream) is not int or raw_stream < 0:
            raise GeneratedDecodeError(
                "bound generated decode has a malformed CUDA stream")
        if (
            self._device_index is not None
            and (type(self._device_index) is not int or self._device_index < 0)
        ):
            raise GeneratedDecodeError(
                "bound generated decode has a malformed CUDA device index"
            )
        object.__setattr__(
            self,
            "_counter_tensors",
            MappingProxyType(dict(self._counter_tensors)),
        )
        object.__setattr__(
            self,
            "_scalar_defaults",
            MappingProxyType(dict(self._scalar_defaults)),
        )
        object.__setattr__(
            self,
            "_fixed_runtime_extents",
            MappingProxyType(dict(self._fixed_runtime_extents)),
        )
        if (
            len(self._tensors) != len(self._memref_structs)
            or tuple(self._scalar_defaults) != self._scalar_order
            or any(name not in self._counter_tensors for name in self._counter_names)
        ):
            raise GeneratedDecodeError(
                "bound generated decode has incomplete private launch state"
            )
        arguments = _arguments(self.descriptor)
        expected_memrefs = sum(
            entry["kind"] == "memref"
            for entry in _expected_packed_argument_abi(self.descriptor)
        )
        expected_capacity_authorities = sum(
            argument.get("transport") == "raw_pointer"
            for argument in arguments
        )
        (
            tensor_authority,
            pointee_authority,
            capacity_authority,
        ) = _unpack_bound_binding_authority(_binding_authority)
        if (
            len(self._tensors) != expected_memrefs
            or len(self._capacity_authority_tensors)
            != expected_capacity_authorities
        ):
            raise GeneratedDecodeError(
                "bound generated decode memory state disagrees with its "
                "descriptor ABI"
            )
        capacity_snapshots = _adopt_tensor_authority(
            self._capacity_authority_tensors,
            capacity_authority,
            label="pointer-only backing storage",
        )
        tensor_snapshots = _adopt_tensor_authority(
            self._tensors,
            tensor_authority,
            label="tensor storage",
        )
        pointee_snapshots = _adopt_tensor_authority(
            self._address_table_pointees,
            pointee_authority,
            label="address-table pointee",
        )
        object.__setattr__(
            self,
            "_storage_guards",
            _storage_guards((
                *(
                    (f"memref {index}", value)
                    for index, value in enumerate(self._tensors)
                ),
                *(
                    (f"address-table pointee {index}", value)
                    for index, value in enumerate(self._address_table_pointees)
                ),
                *(
                    (f"pointer-only backing storage {index}", value)
                    for index, value in enumerate(
                        self._capacity_authority_tensors
                    )
                ),
            )),
        )
        object.__setattr__(
            self,
            "_tensor_snapshots",
            tensor_snapshots,
        )
        object.__setattr__(
            self,
            "_pointee_snapshots",
            pointee_snapshots,
        )
        object.__setattr__(
            self,
            "_capacity_snapshots",
            capacity_snapshots,
        )
        try:
            memref_snapshots = tuple(
                bytes(struct) for struct in self._memref_structs
            )
        except (TypeError, ValueError) as exc:
            raise GeneratedDecodeError(
                "bound generated decode has malformed packed memref state"
            ) from exc
        object.__setattr__(self, "_memref_snapshots", memref_snapshots)
        for index, (value, struct) in enumerate(zip(
            self._tensors,
            self._memref_structs,
            strict=True,
        )):
            try:
                packed_pointer = int(struct.data or 0)
            except (AttributeError, TypeError, ValueError) as exc:
                raise GeneratedDecodeError(
                    f"bound generated decode memref {index} has a malformed "
                    "packed pointer"
                ) from exc
            if packed_pointer != int(value.data_ptr()):
                raise GeneratedDecodeError(
                    f"bound generated decode memref {index} does not point to "
                    "its validated tensor"
                )
        self._validate_bound_memory()
        object.__setattr__(
            self,
            "_launch_counter",
            _register_launch_counter(validated_launch_receipt),
        )

    def _validate_bound_storage(self) -> None:
        for guard in self._storage_guards:
            guard.validate()
        if tuple(
            _tensor_binding_identity(value) for value in self._tensors
        ) != self._tensor_snapshots:
            raise GeneratedDecodeError(
                "generated decode tensor binding changed after binding"
            )
        if tuple(
            _tensor_binding_identity(value)
            for value in self._address_table_pointees
        ) != self._pointee_snapshots:
            raise GeneratedDecodeError(
                "generated decode address-table pointee changed after binding"
            )
        if tuple(
            _tensor_binding_identity(value)
            for value in self._capacity_authority_tensors
        ) != self._capacity_snapshots:
            raise GeneratedDecodeError(
                "generated decode pointer-only backing storage changed after "
                "binding"
            )

    def _validate_bound_memory(self) -> None:
        self._validate_bound_storage()
        if (
            len(self._memref_structs) != len(self._memref_snapshots)
            or any(
                bytes(struct) != snapshot
                for struct, snapshot in zip(
                    self._memref_structs,
                    self._memref_snapshots,
                    strict=True,
                )
            )
        ):
            raise GeneratedDecodeError(
                "generated decode memref state changed after binding"
            )

    def _fresh_memref_structs(self) -> tuple[Any, ...]:
        """Rebuild launch-local structs from immutable packed ABI authority."""

        try:
            return tuple(
                type(struct).from_buffer_copy(snapshot)
                for struct, snapshot in zip(
                    self._memref_structs,
                    self._memref_snapshots,
                    strict=True,
                )
            )
        except (AttributeError, TypeError, ValueError) as exc:
            raise GeneratedDecodeError(
                "bound generated decode cannot reconstruct packed memref state"
            ) from exc

    def _reset_counters(self) -> None:
        if not self._counter_names:
            return
        with torch.cuda.stream(self.stream):
            for name in self._counter_names:
                self._counter_tensors[name].zero_()

    def _validate_launch_device(self) -> None:
        if self._device_index is None:
            return
        current = torch.cuda.current_device()
        if type(current) is not int or current != self._device_index:
            raise GeneratedDecodeError(
                "generated decode launch requires the current CUDA device to "
                f"match its bound device: current={current!r}, "
                f"bound={self._device_index}"
            )

    def _validated_launch_scalars(
        self,
        scalar_overrides: Mapping[str, Any],
    ) -> tuple[int, list[Any]]:
        plan = self._launch_scalar_plan
        if plan is None:
            plan = self._build_launch_scalar_plan()
            object.__setattr__(self, "_launch_scalar_plan", plan)
        arguments = plan.arguments
        minimums = plan.minimums
        maximums = plan.maximums
        static_extents = plan.static_extents
        extent_scalar_names = plan.extent_scalar_names
        unknown = set(scalar_overrides) - set(self._scalar_defaults)
        if unknown:
            raise GeneratedDecodeError(f"unknown scalar overrides {sorted(unknown)}")
        effective = {}
        packed = []
        for name in self._scalar_order:
            argument = arguments[name]
            value = scalar_overrides.get(name, self._scalar_defaults[name])
            if name in extent_scalar_names:
                static_value = static_extents.get(name)
                fixed_value = self._fixed_runtime_extents.get(name)
                capacity = (
                    _descriptor_capacity(self.descriptor)
                    if name == "active_batch"
                    else _shape_environment(self.descriptor, name)
                )
                if capacity is None and fixed_value is not None:
                    capacity = fixed_value
                minimum = minimums.get(name, 1)
                maximum = maximums.get(name, capacity)
                if (
                    isinstance(value, bool)
                    or not isinstance(value, int)
                    or capacity is None
                    or value < minimum
                    or value > maximum
                    or (static_value is not None and value != static_value)
                    or (fixed_value is not None and value != fixed_value)
                ):
                    exact_value = (
                        static_value if static_value is not None else fixed_value
                    )
                    lower = exact_value if exact_value is not None else minimum
                    upper = exact_value if exact_value is not None else maximum
                    raise GeneratedDecodeError(
                        f"runtime extent {name!r}={value} is outside artifact "
                        f"interval [{lower}, {upper}]")
            effective[name] = value
            packed.append(_pack_scalar_value(
                argument.get("dtype"),
                value,
                name=name,
            ))

        static_active_batch = static_extents.get("active_batch")
        if static_active_batch is not None:
            active_batch = static_active_batch
        elif "active_batch" in effective:
            active_batch = effective["active_batch"]
        else:
            active_batch = _descriptor_capacity(self.descriptor)
        minimum_batch = minimums.get("active_batch", 1)
        maximum_batch = maximums.get(
            "active_batch", _descriptor_capacity(self.descriptor))
        if (
            isinstance(active_batch, bool)
            or not isinstance(active_batch, int)
            or not minimum_batch <= active_batch <= maximum_batch
        ):
            raise GeneratedDecodeError(
                f"launch active_batch {active_batch!r} is outside artifact "
                f"interval [{minimum_batch}, {maximum_batch}]")

        return active_batch, packed

    def _build_launch_scalar_plan(self) -> _LaunchScalarPlan:
        arguments = {item["name"]: item for item in _arguments(self.descriptor)}
        minimums = _runtime_extent_minimums(self.descriptor)
        maximums = _runtime_extent_maximums(self.descriptor)
        static_extents = _static_extent_bindings(self.descriptor)
        scalar_names = tuple(
            name for name, argument in arguments.items()
            if argument.get("transport") == "scalar"
        )
        if scalar_names != self._scalar_order:
            raise GeneratedDecodeError(
                "bound generated decode scalar ABI differs from its descriptor"
            )
        runtime_names = {
            name for name, argument in arguments.items()
            if argument.get("source") == "runtime_extent"
        }
        device_program = self.descriptor.get("device_program")
        physical_abi = (
            device_program.get("physical_abi")
            if isinstance(device_program, Mapping) else None
        )
        dynamic_storage_names = (
            set(_physical_dynamic_scalars(self.descriptor))
            if physical_abi is not None else set()
        )
        workspace_bindings = (
            _validated_workspace_bindings(
                self.descriptor,
                tuple(arguments.values()),
            )
            if any(
                argument.get("source") == "workspace"
                for argument in arguments.values()
            ) else {}
        )
        storage_extent_names = (
            dynamic_storage_names
            | set(_workspace_dynamic_scalars(workspace_bindings))
        )
        extent_scalar_names = runtime_names | (
            storage_extent_names & set(scalar_names)
        )
        missing_storage_scalars = storage_extent_names - extent_scalar_names
        if missing_storage_scalars:
            raise GeneratedDecodeError(
                "generated decode dynamic storage has no scalar arguments: "
                f"{sorted(missing_storage_scalars)}"
            )
        undeclared_domains = (
            set(minimums)
            | set(maximums)
            | set(static_extents)
        ) - extent_scalar_names
        if undeclared_domains:
            raise GeneratedDecodeError(
                "generated decode runtime domains have no scalar arguments: "
                f"{sorted(undeclared_domains)}")
        return _LaunchScalarPlan(
            arguments=MappingProxyType(arguments),
            minimums=MappingProxyType(dict(minimums)),
            maximums=MappingProxyType(dict(maximums)),
            static_extents=MappingProxyType(dict(static_extents)),
            extent_scalar_names=frozenset(extent_scalar_names),
        )

    def _prepare_dynamic_scalars(
        self,
    ) -> tuple[tuple[_PreparedDynamicScalar, ...], int | None]:
        plan = self._launch_scalar_plan
        if plan is None:
            plan = self._build_launch_scalar_plan()
            object.__setattr__(self, "_launch_scalar_plan", plan)
        slots = []
        active_batch_slot = None
        for index, name in enumerate(self._scalar_order):
            argument = plan.arguments[name]
            dtype = argument.get("dtype")
            default = self._scalar_defaults[name]
            holder = _pack_scalar_value(dtype, default, name=name)
            extent_lower = None
            extent_upper = None
            if name in plan.extent_scalar_names:
                static_value = plan.static_extents.get(name)
                fixed_value = self._fixed_runtime_extents.get(name)
                capacity = (
                    _descriptor_capacity(self.descriptor)
                    if name == "active_batch"
                    else _shape_environment(self.descriptor, name)
                )
                if capacity is None and fixed_value is not None:
                    capacity = fixed_value
                if capacity is None:
                    raise GeneratedDecodeError(
                        f"runtime extent {name!r} has no artifact capacity"
                    )
                exact = static_value if static_value is not None else fixed_value
                extent_lower = (
                    exact if exact is not None else plan.minimums.get(name, 1)
                )
                extent_upper = (
                    exact if exact is not None else plan.maximums.get(name, capacity)
                )
            abi_lower = None
            abi_upper = None
            if dtype in {"int32", "int64"}:
                bits = ctypes.sizeof(type(holder)) * 8
                abi_lower = -(1 << (bits - 1))
                abi_upper = (1 << (bits - 1)) - 1
            slots.append(_PreparedDynamicScalar(
                name=name,
                dtype=dtype,
                default=default,
                holder=holder,
                extent_lower=extent_lower,
                extent_upper=extent_upper,
                abi_lower=abi_lower,
                abi_upper=abi_upper,
            ))
            if name == "active_batch":
                active_batch_slot = index
        return tuple(slots), active_batch_slot

    def _update_prepared_dynamic_scalars(
        self,
        slots: tuple[_PreparedDynamicScalar, ...],
        active_batch_slot: int | None,
        scalar_overrides: Mapping[str, Any],
    ) -> int:
        unknown = [
            name for name in scalar_overrides
            if name not in self._scalar_defaults
        ]
        if unknown:
            raise GeneratedDecodeError(f"unknown scalar overrides {sorted(unknown)}")
        active_batch = None
        for index, slot in enumerate(slots):
            value = scalar_overrides.get(slot.name, slot.default)
            if slot.extent_lower is not None and (
                type(value) is not int
                or value < slot.extent_lower
                or value > slot.extent_upper
            ):
                raise GeneratedDecodeError(
                    f"runtime extent {slot.name!r}={value} is outside artifact "
                    f"interval [{slot.extent_lower}, {slot.extent_upper}]"
                )
            if slot.dtype in {"int32", "int64"}:
                if type(value) is not int:
                    raise GeneratedDecodeError(
                        f"generated decode scalar {slot.name!r} needs an exact integer"
                    )
                if not slot.abi_lower <= value <= slot.abi_upper:
                    bits = ctypes.sizeof(type(slot.holder)) * 8
                    raise GeneratedDecodeError(
                        f"generated decode scalar {slot.name!r}={value} is outside "
                        f"its signed {bits}-bit ABI"
                    )
            elif slot.dtype == "fp32":
                if isinstance(value, bool) or not isinstance(value, (int, float)):
                    raise GeneratedDecodeError(
                        f"generated decode scalar {slot.name!r} needs a finite number"
                    )
                try:
                    value = float(value)
                except (OverflowError, TypeError, ValueError) as exc:
                    raise GeneratedDecodeError(
                        f"generated decode scalar {slot.name!r} needs a finite number"
                    ) from exc
                if not isfinite(value):
                    raise GeneratedDecodeError(
                        f"generated decode scalar {slot.name!r} needs a finite number"
                    )
            try:
                slot.holder.value = value
            except (OverflowError, TypeError, ValueError) as exc:
                raise GeneratedDecodeError(
                    f"generated decode scalar {slot.name!r} is malformed"
                ) from exc
            if slot.dtype == "fp32" and not isfinite(float(slot.holder.value)):
                raise GeneratedDecodeError(
                    f"generated decode scalar {slot.name!r} overflows its fp32 ABI"
                )
            if index == active_batch_slot:
                active_batch = value

        if active_batch is None:
            active_batch = self._launch_scalar_plan.static_extents.get(
                "active_batch"
            )
            if active_batch is None:
                active_batch = _descriptor_capacity(self.descriptor)
        return active_batch

    def _prepare_launch(self, scalar_overrides, *, validate_each_launch):
        self._validate_bound_memory()
        memref_structs = self._fresh_memref_structs()
        active_batch, scalars = self._validated_launch_scalars(scalar_overrides)
        raw_stream = getattr(self.stream, "cuda_stream", self.stream)
        invocation = self._bundle.prepare_invoke(
            memref_structs,
            scalars,
            ctypes.c_void_p(int(raw_stream)),
        )

        def launch():
            with self._launch_lock:
                if validate_each_launch:
                    self._validate_bound_storage()
                self._validate_launch_device()
                self._reset_counters()
                result = invocation.invoke()
                _record_launch(self._launch_counter, active_batch)
                return result

        return launch

    def prepare_launch(self, **scalar_overrides):
        """Validate and pack one repeated launch with stable scalar extents."""

        return self._prepare_launch(
            scalar_overrides, validate_each_launch=True
        )

    def prepare_repeated_launch(self, **scalar_overrides):
        """Prepare a low-overhead launch for an owned fixed-binding session.

        Binding memory is validated while this launcher is prepared.  The
        caller must then retain exclusive ownership of tensor metadata for the
        launcher's lifetime; unlike :meth:`prepare_launch`, this path
        intentionally does not re-walk every tensor and storage before every
        invocation.  Counter reset, device validation, launch accounting, and
        serialization remain per invocation.
        """

        return self._prepare_launch(
            scalar_overrides, validate_each_launch=False
        )

    def prepare_repeated_dynamic_launch(self):
        """Prepare an owned-binding launcher with per-call scalar overrides.

        This is the dynamic-scalar counterpart to
        :meth:`prepare_repeated_launch`. Binding memory is validated once while
        the launcher is prepared, while every invocation still validates its
        scalar overrides. The caller must retain exclusive ownership of tensor
        metadata for the launcher's lifetime.
        """

        self._validate_bound_memory()
        prepare_invoke = getattr(self._bundle, "prepare_invoke", None)
        if prepare_invoke is None:
            def launch(**scalar_overrides):
                return self._launch_dynamic(
                    scalar_overrides,
                    validate_each_launch=False,
                )

            return launch

        slots, active_batch_slot = self._prepare_dynamic_scalars()
        memref_structs = self._fresh_memref_structs()
        raw_stream = getattr(self.stream, "cuda_stream", self.stream)
        invocation = prepare_invoke(
            memref_structs,
            tuple(slot.holder for slot in slots),
            ctypes.c_void_p(int(raw_stream)),
        )

        def launch(**scalar_overrides):
            with self._launch_lock:
                active_batch = self._update_prepared_dynamic_scalars(
                    slots,
                    active_batch_slot,
                    scalar_overrides,
                )
                self._validate_launch_device()
                self._reset_counters()
                result = invocation.invoke()
                _record_launch(self._launch_counter, active_batch)
                return result

        return launch

    def _launch_dynamic(self, scalar_overrides, *, validate_each_launch):
        with self._launch_lock:
            if validate_each_launch:
                self._validate_bound_memory()
            active_batch, scalars = self._validated_launch_scalars(
                scalar_overrides
            )
            self._validate_launch_device()
            invocation = self._dynamic_invocation
            if invocation is None:
                prepare_invoke = getattr(self._bundle, "prepare_invoke", None)
                if prepare_invoke is not None:
                    memref_structs = self._fresh_memref_structs()
                    raw_stream = getattr(self.stream, "cuda_stream", self.stream)
                    dynamic_scalars = tuple(scalars)
                    invocation = prepare_invoke(
                        memref_structs,
                        dynamic_scalars,
                        ctypes.c_void_p(int(raw_stream)),
                    )
                    object.__setattr__(self, "_dynamic_scalars", dynamic_scalars)
                    object.__setattr__(self, "_dynamic_invocation", invocation)
            else:
                if len(self._dynamic_scalars) != len(scalars):
                    raise GeneratedDecodeError(
                        "bound generated decode scalar ABI changed after packing"
                    )
                for holder, value in zip(
                    self._dynamic_scalars,
                    scalars,
                    strict=True,
                ):
                    if type(holder) is not type(value):
                        raise GeneratedDecodeError(
                            "bound generated decode scalar ABI changed after packing"
                        )
                    holder.value = value.value
            self._reset_counters()
            if invocation is not None:
                result = invocation.invoke()
            else:
                memref_structs = self._fresh_memref_structs()
                raw_stream = getattr(self.stream, "cuda_stream", self.stream)
                result = self._bundle.invoke(
                    list(memref_structs),
                    scalars,
                    ctypes.c_void_p(int(raw_stream)),
                )
            _record_launch(self._launch_counter, active_batch)
            return result

    def launch(self, **scalar_overrides):
        return self._launch_dynamic(
            scalar_overrides,
            validate_each_launch=True,
        )


